INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87370, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "与一般情况不同，不寻常，令人感到疑惑。", "primary_collocate": null, "pronunciation": "qí guài", "ipa": "tɕʰi˧˥ kuai˥˩", "syllable_count": 2, "sentences": [{"text": "他的样子看上去有点奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题问得很奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么热，他还穿着大衣，真奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机刚才还在这儿，现在却找不到了，很奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近的做法很奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子里有奇怪的味道。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得很奇怪，我不明白为什么。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直看着我，样子很奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不吃也不喝，真奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天对我的态度很奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奇奇怪怪", "label": "重叠"}], "register": "中性", "sense_fingerprint": "形容词；与一般情况不同；不寻常，令人疑惑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caabb7e0-2a3a-4f9f-b03d-4a7815969b51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远", "is_correct": false, "explanation": "语义：远指距离，不能说样子远。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：饱形容吃得满足，不能修饰样子。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：厚形容物体的厚度，不能用来形容样子。"}, {"text": "奇怪", "is_correct": true, "explanation": "正确。奇怪指与一般情况不同、让人疑惑，可以描述样子。"}], "explanations": {"远": "语义：远指距离，不能说样子远。", "饱": "搭配：饱形容吃得满足，不能修饰样子。", "厚": "搭配：厚形容物体的厚度，不能用来形容样子。", "奇怪": "正确。奇怪指与一般情况不同、让人疑惑，可以描述样子。"}, "sentence_index": 0, "correct_answer": "奇怪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上七点起床，这很奇怪。", "explanation": "这里应该用〈正常〉。奇怪指与一般情况不同、令人疑惑，每天七点起床是平常的事，应说正常。"}, {"text": "这家超市的蔬菜很奇怪，又嫩又便宜。", "explanation": "这里应该用〈新鲜〉。奇怪指与一般情况不同、令人疑惑，形容蔬菜品质好要用新鲜。"}, {"text": "这台电脑的运行速度很奇怪，打开文件只要一秒钟。", "explanation": "这里应该用〈快〉。奇怪指与一般情况不同、令人疑惑，形容速度快要用快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胖", "is_correct": false, "explanation": "体貌：胖形容人的身材，不能用来形容笑的样子。"}, {"text": "窄", "is_correct": false, "explanation": "语义：窄指宽度小，与笑的样子无关。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：整齐形容排列有序，不能用来形容笑。"}, {"text": "奇怪", "is_correct": true, "explanation": "正确。奇怪指与平常不同、让人疑惑，可以形容笑的样子。"}], "explanations": {"胖": "体貌：胖形容人的身材，不能用来形容笑的样子。", "窄": "语义：窄指宽度小，与笑的样子无关。", "整齐": "搭配：整齐形容排列有序，不能用来形容笑。", "奇怪": "正确。奇怪指与平常不同、让人疑惑，可以形容笑的样子。"}, "sentence_index": 6, "correct_answer": "奇怪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "尊敬的各位来宾，今天的开幕式非常奇怪，我代表学校热烈欢迎大家。", "explanation": "这里应该用〈隆重〉。奇怪指不寻常、让人疑惑，形容开幕式的庄重场面要用隆重。"}, {"text": "这张地图画得很奇怪，每条路线都画得很清楚。", "explanation": "这里应该用〈清晰〉。奇怪指不寻常、令人疑惑，形容地图画得明白易懂要用清晰。"}, {"text": "他的成绩很奇怪，考了第一名大家都为他高兴。", "explanation": "这里应该用〈优秀〉。奇怪指让人疑惑，形容成绩好要用优秀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的表情看上去有点的奇怪。", "corrected_sentence": "她的表情看上去有点奇怪。", "error_description": "助词错误：“有点”和“奇怪”之间不能加“的”。应说“有点奇怪”，不能说“有点的奇怪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她不吃也不喝，真很奇怪。", "corrected_sentence": "她不吃也不喝，真奇怪。", "error_description": "程度副词重复：“真”和“很”都表示程度，不能同时修饰“奇怪”，应说“真奇怪”，不能说“真很奇怪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87371, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战争", "is_correct": true, "explanation": "反义：和平指没有战争的状态，战争与之相反。"}, {"text": "河流", "is_correct": false, "explanation": "无关：河流与和平没有反义关系，只是同为名词。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：窗户与和平没有反义关系，只是同为名词。"}, {"text": "科学", "is_correct": false, "explanation": "无关：科学与和平没有反义关系，只是同为名词。"}], "correct_answer": "战争", "explanations": {"战争": "反义：和平指没有战争的状态，战争与之相反。", "河流": "无关：河流与和平没有反义关系，只是同为名词。", "窗户": "无关：窗户与和平没有反义关系，只是同为名词。", "科学": "无关：科学与和平没有反义关系，只是同为名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87371, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战争", "is_correct": true, "explanation": "反义：和平指没有战争的状态，战争与之相反。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：桌子是家具，与和平没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "无关：雨伞是日用品，与和平没有反义关系。"}, {"text": "历史", "is_correct": false, "explanation": "无关：历史是名词，与和平没有反义关系。"}], "correct_answer": "战争", "explanations": {"战争": "反义：和平指没有战争的状态，战争与之相反。", "桌子": "无关：桌子是家具，与和平没有反义关系。", "雨伞": "无关：雨伞是日用品，与和平没有反义关系。", "历史": "无关：历史是名词，与和平没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87371, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "和平是没有打仗，大家都很平安。", "primary_collocate": null, "pronunciation": "hé píng", "ipa": "xɤ˧˥ pʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "大家都希望世界上有和平。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束了，人们终于等到了和平。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，和平比钱重要。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要爱护来之不易的和平。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在联合国工作，为和平努力。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打了很多年仗，大家都想要和平。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有和平，孩子就不能上学。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家已经很久没有和平了。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白鸽是和平的象征。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们经历过动乱，所以特别珍惜和平。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和平共处", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，没有战争、大家平安生活的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1b6033-d2c6-4adf-8a03-9e18bc04078f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和平", "is_correct": true, "explanation": "语义正确：和平指没有战争的状态，“希望……有和平”搭配自然。"}, {"text": "战争", "is_correct": false, "explanation": "语义：大家希望的是没有战争，“希望世界上有战争”与句意相反。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：灾难是大家都不希望出现的，与“希望”的语义冲突。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：大家希望的是没有饥饿，“希望世界上有饥饿”与句意相反。"}], "explanations": {"和平": "语义正确：和平指没有战争的状态，“希望……有和平”搭配自然。", "战争": "语义：大家希望的是没有战争，“希望世界上有战争”与句意相反。", "灾难": "语义：灾难是大家都不希望出现的，与“希望”的语义冲突。", "饥饿": "语义：大家希望的是没有饥饿，“希望世界上有饥饿”与句意相反。"}, "sentence_index": 0, "correct_answer": "和平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们终于得到了一只和平。", "explanation": "这里应该用〈种〉。和平是抽象名词，不用“只”计量（“只”多用于动物），可说“一种和平”。"}, {"text": "祝你一路和平。", "explanation": "这里应该用〈平安〉。“一路平安”是常用的祝福语，指人身无险；和平只指国家或社会没有战争。"}, {"text": "听到这个消息，她的心情很和平。", "explanation": "这里应该用〈平静〉。平静可以形容心情；和平只用于国家、社会之间没有战争，不形容个人心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和平", "is_correct": true, "explanation": "语义正确：“没有和平”指社会动荡，孩子无法安心上学，条件关系成立。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具与上学的条件无关，“没有玩具就不能上学”不合常理。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是上学的内容，不是上学的前提，句意不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“没有饭菜”与“不能上学”之间没有条件关系，这种条件搭配不成立。"}], "explanations": {"和平": "语义正确：“没有和平”指社会动荡，孩子无法安心上学，条件关系成立。", "玩具": "语义：玩具与上学的条件无关，“没有玩具就不能上学”不合常理。", "作业": "语义：作业是上学的内容，不是上学的前提，句意不通。", "饭菜": "搭配：“没有饭菜”与“不能上学”之间没有条件关系，这种条件搭配不成立。"}, "sentence_index": 6, "correct_answer": "和平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试的时候，教室里很和平，没有人说话。", "explanation": "这里应该用〈安静〉。“安静”形容环境没有声音；和平只用于国家或社会没有战争，不形容教室。"}, {"text": "孩子们坐校车时很和平。", "explanation": "这里应该用〈安全〉。“安全”说乘车没有危险；和平不用来形容人身安全。"}, {"text": "今年的物价很和平，没有大的波动。", "explanation": "这里应该用〈稳定〉。“稳定”形容物价等变化平缓；和平指国家或社会之间没有战争，不用来形容物价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过多年的谈判，两国终于赢得了一个和平。", "corrected_sentence": "经过多年的谈判，两国终于赢得了和平。", "error_description": "量词错误：“和平”是抽象名词，不能用“一个”计量；应去掉“一个”，直接说“赢得了和平”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们生活的很和平。", "corrected_sentence": "他们生活得很和平。", "error_description": "结构助词错误：补语前应用「得」，说「生活得很和平」，不能用「的」说「生活的很和平」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87372, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战争", "is_correct": true, "explanation": "反义：和平指没有战争、平静安宁的局面，战争与之相反。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：窗户与和平没有反义关系，只是同为名词。"}, {"text": "科学", "is_correct": false, "explanation": "无关：科学与和平没有反义关系，只是同为名词。"}, {"text": "花园", "is_correct": false, "explanation": "无关：花园与和平没有反义关系，只是同为名词。"}], "correct_answer": "战争", "explanations": {"战争": "反义：和平指没有战争、平静安宁的局面，战争与之相反。", "窗户": "无关：窗户与和平没有反义关系，只是同为名词。", "科学": "无关：科学与和平没有反义关系，只是同为名词。", "花园": "无关：花园与和平没有反义关系，只是同为名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87372, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战争", "is_correct": true, "explanation": "反义：和平指没有战争的局面，战争与之相反。"}, {"text": "字典", "is_correct": false, "explanation": "无关：字典是工具书，与和平没有反义关系。"}, {"text": "茶叶", "is_correct": false, "explanation": "无关：茶叶是食物，与和平没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "无关：海洋是地理事物，与和平没有反义关系。"}], "correct_answer": "战争", "explanations": {"战争": "反义：和平指没有战争的局面，战争与之相反。", "字典": "无关：字典是工具书，与和平没有反义关系。", "茶叶": "无关：茶叶是食物，与和平没有反义关系。", "海洋": "无关：海洋是地理事物，与和平没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "没有战争的状态；平静安宁。", "primary_collocate": null, "pronunciation": "hé píng", "ipa": "xɤ˧˥ pʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "两个国家签了和平协议。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争后，这里恢复了和平。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用谈判来保持和平。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界和平需要每个人努力。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小岛上，人们享受着和平。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们生活在和平的年代。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不想打仗，只希望和平解决问题。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了和平，两国领导人见面了。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和平来了，工厂又开工了。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她梦想成为一名和平大使。", "target_word": "和平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和平共处", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，没有战争、平静安宁的局面，常与保持、恢复、维护搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1b6033-d2c6-4adf-8a03-9e18bc04078f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和平", "is_correct": true, "explanation": "语义正确：“和平协议”指关于停止战争、维护和平的协议，搭配自然。"}, {"text": "战争", "is_correct": false, "explanation": "语义：协议的内容不能是“战争”，“签了战争协议”不合理。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：灾难不是协议的内容，“灾难协议”说不通。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“饥饿”不能用来修饰“协议”，“饥饿协议”不是常见说法。"}], "explanations": {"和平": "语义正确：“和平协议”指关于停止战争、维护和平的协议，搭配自然。", "战争": "语义：协议的内容不能是“战争”，“签了战争协议”不合理。", "灾难": "语义：灾难不是协议的内容，“灾难协议”说不通。", "饥饿": "搭配：“饥饿”不能用来修饰“协议”，“饥饿协议”不是常见说法。"}, "sentence_index": 0, "correct_answer": "和平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次远行，他一家人都和平地回来了。", "explanation": "这里应该用〈平安〉。“平安”指人身没有危险，“平安地回来”是常用说法；和平只指国家或社会没有战争。"}, {"text": "股市这几天很和平。", "explanation": "这里应该用〈稳定〉。“稳定”形容股市、物价等变化平缓；和平多指国家或社会之间没有战争，不用来形容股市。"}, {"text": "我们终于恢复了一只和平。", "explanation": "这里应该用〈种〉。和平是抽象名词，不用“只”计量（“只”多用于动物），可说“恢复了一种和平”或直接说“恢复了和平”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和平", "is_correct": true, "explanation": "语义正确：“和平解决问题”指不用武力的方式解决，与“希望”搭配自然。"}, {"text": "暴力", "is_correct": false, "explanation": "语义：“希望暴力解决问题”与“和平”的诉求相反，句意矛盾。"}, {"text": "战争", "is_correct": false, "explanation": "语义：战争不是解决问题的方式，“希望战争解决问题”不合常理。"}, {"text": "武力", "is_correct": false, "explanation": "语义：前一分句「不想打仗」已排除武力，「只希望武力解决问题」与句意矛盾。"}], "explanations": {"和平": "语义正确：“和平解决问题”指不用武力的方式解决，与“希望”搭配自然。", "暴力": "语义：“希望暴力解决问题”与“和平”的诉求相反，句意矛盾。", "战争": "语义：战争不是解决问题的方式，“希望战争解决问题”不合常理。", "武力": "语义：前一分句「不想打仗」已排除武力，「只希望武力解决问题」与句意矛盾。"}, "sentence_index": 6, "correct_answer": "和平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛很和平。", "explanation": "这里应该用〈激烈〉。“激烈”形容竞争、对抗强烈；和平形容平静安宁，不用来描述竞赛的对抗。"}, {"text": "早高峰时，这段路的交通很和平。", "explanation": "这里应该用〈拥堵〉。“拥堵”形容车多、道路不畅；和平形容平静安宁，不用来描述交通状况。"}, {"text": "伤口很快就和平了。", "explanation": "这里应该用〈愈合〉。“愈合”指伤口长好；和平指国家或社会之间没有战争，不用于描述伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国终于签了很和平条约。", "corrected_sentence": "两国终于签了和平条约。", "error_description": "程度副词错误：「和平」作名词，不能被「很」修饰，作定语时直接说「和平条约」，不能说「很和平条约」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "战后，这里终于恢复了一场和平。", "corrected_sentence": "战后，这里终于恢复了和平。", "error_description": "量词错误：“和平”是抽象名词，不能用“场”（多用于事件、活动）计量；去掉“一场”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
