INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87383, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87383, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "双方在数量、大小、实力或水平上相当，不相上下。", "primary_collocate": null, "pronunciation": "duì děng", "ipa": "twei˥˩ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两份工作的报酬对等，他才愿意接受。", "target_word": "对等", "complexity_tier": "T3", "furigana": "liǎng fèn gōng zuò de bào chóu duì děng, tā cái yuàn yì jiē shòu.", "sentence_source": "generated"}, {"text": "这两边的人数是对等的。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的双方实力对等。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的兵力对等，谁也不敢先动手。", "target_word": "对等", "complexity_tier": "T3", "furigana": "liǎng gè guó jiā de bīng lì duì děng, shéi yě bù gǎn xiān dòng shǒu.", "sentence_source": "generated"}, {"text": "两堆沙子的数量对等，天平保持平衡。", "target_word": "对等", "complexity_tier": "T3", "furigana": "liǎng duī shā zi de shù liàng duì děng, tiān píng bǎo chí píng héng.", "sentence_source": "generated"}, {"text": "付出和得到应该对等。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的代表人数对等。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的条件很对等，所以谈得很顺利。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两边的重量对等，秤杆才不会歪。", "target_word": "对等", "complexity_tier": "T3", "furigana": "liǎng biān de zhòng liàng duì děng, chèng gǎn cái bù huì wāi.", "sentence_source": "generated"}, {"text": "两队的水平对等，比赛非常精彩。", "target_word": "对等", "complexity_tier": "T3", "furigana": "liǎng duì de shuǐ píng duì děng, bǐ sài fēi cháng jīng cǎi.", "sentence_source": "generated"}], "morphological_forms": [{"form": "不对等", "label": "否定形式"}, {"form": "對等", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对等：双方数量、大小、实力或水平相当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 秤 (Zipf 3.34), 杆 (Zipf 3.96), 歪 (Zipf 3.89)']::text[], 'a05bf854-5e1e-422d-a553-c991fceb6ea9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对等", "is_correct": true, "explanation": "对等：两份工作的报酬一样多，符合“他才愿意接受”的句意。"}, {"text": "陌生", "is_correct": false, "explanation": "搭配：“陌生”指不熟悉，不能用来修饰“报酬”。"}, {"text": "轻松", "is_correct": false, "explanation": "搭配：“轻松”多用于工作或心情，不能说报酬轻松。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示人的心情，用在“报酬”上句意不通，也与“才愿意接受”的条件不合。"}], "explanations": {"对等": "对等：两份工作的报酬一样多，符合“他才愿意接受”的句意。", "陌生": "搭配：“陌生”指不熟悉，不能用来修饰“报酬”。", "轻松": "搭配：“轻松”多用于工作或心情，不能说报酬轻松。", "高兴": "语义：“高兴”表示人的心情，用在“报酬”上句意不通，也与“才愿意接受”的条件不合。"}, "sentence_index": 0, "correct_answer": "对等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在法律面前，每个人都是对等的。", "explanation": "这里应该用〈平等〉。对等指双方地位、实力相当，要有两方相互对应；说每个人享有相同权利时用平等。"}, {"text": "我们俩的性格对等，所以很合得来。", "explanation": "这里应该用〈一样〉。对等只用于地位、实力、数量相当，不用来形容性格；说性格相同要用一样。"}, {"text": "这幅画的颜色两边很对等。", "explanation": "对等指数量、大小、实力相当，颜色不能用对等描述；说颜色相同要用〈一致〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对等", "is_correct": true, "explanation": "对等：两国的代表人数相当，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来修饰“代表人数”。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能说人数聪明。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，用在“代表人数”上句意不通。"}], "explanations": {"对等": "对等：两国的代表人数相当，符合句意。", "漂亮": "体貌：“漂亮”形容外貌，不能用来修饰“代表人数”。", "聪明": "搭配：“聪明”形容人的智力，不能说人数聪明。", "温柔": "语义：“温柔”形容性情，用在“代表人数”上句意不通。"}, "sentence_index": 6, "correct_answer": "对等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们两个人的看法很对等。", "explanation": "这里应该用〈一致〉。对等说地位、实力、数量相当，表示看法相同要用一致。"}, {"text": "这对双胞胎长得很对等。", "explanation": "这里应该用〈相像〉。对等不用于形容外貌，说长得相似要用相像。"}, {"text": "士兵们的队伍排得很对等。", "explanation": "这里应该用〈整齐〉。对等指双方相当，队伍排列整齐要用整齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司的薪水比对等，员工才愿意留下。", "corrected_sentence": "两家公司的薪水对等，员工才愿意留下。", "error_description": "错误：“对等”前面多加了“比”。“对等”是形容词，表示相等，不能直接放在“比”后面，应去掉“比”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个班级的人数很对等着，比赛才公平。", "corrected_sentence": "两个班级的人数很对等，比赛才公平。", "error_description": "错误：“对等”是形容词，后面不能加“着”表示状态持续；应说“很对等”，“对等着”不是常用说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
