INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87413, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "星期是一周里的某一天，一共有七天，周一、周二都是。", "primary_collocate": null, "pronunciation": "xīng qī", "ipa": "ɕiŋ˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "今天是星期三。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期一我要上班。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我星期五要考试。", "target_word": "星期", "complexity_tier": "T3", "furigana": "wǒ xīng qī wǔ yào kǎo shì", "sentence_source": "generated"}, {"text": "他星期二有汉语课。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我星期四去看医生。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期六早上我常常跑步。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的生日在星期三。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期五晚上我们看电影。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天是星期五，不是星期四。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期三你有空吗？", "target_word": "星期", "complexity_tier": "T3", "furigana": "xīng qī sān nǐ yǒu kòng ma", "sentence_source": "generated"}], "morphological_forms": [{"form": "星期天", "label": "复合词"}, {"form": "星期日", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一周里的某一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbe6c0-1a36-4377-a066-54ce1f0a44eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87413, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "星期", "is_correct": true, "explanation": "正确答案：星期（xīngqī），一周里的某一天。"}, {"text": "兴起", "is_correct": false, "explanation": "xīng 相同，第二音节 qǐ（第三声）与 qī（第一声）声调不同，意思是“兴起、开始流行”。"}, {"text": "刑期", "is_correct": false, "explanation": "第一音节 xíng（第二声）与 xīng（第一声）声调不同，qī 相同，意思是“服刑的时间”。"}, {"text": "腥气", "is_correct": false, "explanation": "第一音节相同，第二音节 qì（第四声）与 qī（第一声）声调不同，意思是“腥味”。"}, {"text": "经期", "is_correct": false, "explanation": "jīng 与 xīng 声母不同，qī 相同，意思是“月经期”。"}], "explanations": {"星期": "正确答案：星期（xīngqī），一周里的某一天。", "兴起": "xīng 相同，第二音节 qǐ（第三声）与 qī（第一声）声调不同，意思是“兴起、开始流行”。", "刑期": "第一音节 xíng（第二声）与 xīng（第一声）声调不同，qī 相同，意思是“服刑的时间”。", "腥气": "第一音节相同，第二音节 qì（第四声）与 qī（第一声）声调不同，意思是“腥味”。", "经期": "jīng 与 xīng 声母不同，qī 相同，意思是“月经期”。"}, "sentence_index": null, "correct_answer": "星期"}, "level_3": {"options": [{"text": "星期", "is_correct": true, "explanation": "正确答案：“今天是星期三”中，“星期三”是一周中的某一天，表达自然。"}, {"text": "月份", "is_correct": false, "explanation": "搭配：“今天是月份三”不成立，应说“三月份”，“月份”不能直接接序数“三”。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指春夏秋冬，不能与“三”组成日期。"}, {"text": "课程", "is_correct": false, "explanation": "语义：“课程”指学习的内容或安排，与“今天是……三”的日期含义不符。"}], "explanations": {"星期": "正确答案：“今天是星期三”中，“星期三”是一周中的某一天，表达自然。", "月份": "搭配：“今天是月份三”不成立，应说“三月份”，“月份”不能直接接序数“三”。", "季节": "语义：“季节”指春夏秋冬，不能与“三”组成日期。", "课程": "语义：“课程”指学习的内容或安排，与“今天是……三”的日期含义不符。"}, "sentence_index": 0, "correct_answer": "星期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这只星期二有汉语课。", "explanation": "这里应该用“个”：这个星期二。“只”不用来修饰“星期二”这样的时间词。"}, {"text": "我在这里住了两个星期二。", "explanation": "这里是“以七天为周期的时间单位”的意思。“星期二”只指周二这一天，不能用来计量时长。"}, {"text": "他一星期二有汉语课。", "explanation": "这里应该说“每星期二”。“星期二”指一周中的某一天，前面不能直接加“一”表示周数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星期", "is_correct": true, "explanation": "正确答案：“星期三”是具体的一天，与“她的生日在”搭配自然。"}, {"text": "周末", "is_correct": false, "explanation": "语义：“周末”指周六、周日，不能与序数“三”连用。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：“早晨”是一天中的时段，不能组成“早晨三”这样的日期说法。"}, {"text": "课间", "is_correct": false, "explanation": "搭配：“课间”指上课之间的休息时间，不与序数“三”组成日期。"}], "explanations": {"星期": "正确答案：“星期三”是具体的一天，与“她的生日在”搭配自然。", "周末": "语义：“周末”指周六、周日，不能与序数“三”连用。", "早晨": "语义：“早晨”是一天中的时段，不能组成“早晨三”这样的日期说法。", "课间": "搭配：“课间”指上课之间的休息时间，不与序数“三”组成日期。"}, "sentence_index": 6, "correct_answer": "星期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你这张星期三有空吗？", "explanation": "这里应该用“个”：这个星期三。“张”用于平面的东西，不用来修饰时间词。"}, {"text": "你这一星期三有空吗？", "explanation": "数量错误：“这一星期”与“三”不能连用。“星期三”前面不加周数，应说“星期三”或“这个星期三”。"}, {"text": "这部星期三的会议很重要。", "explanation": "这里应该用“个”：这个星期三。“部”用于电影、书籍、机器等，不用来修饰“星期三”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我星期十上班。", "corrected_sentence": "我星期四上班。", "error_description": "数词错误：一周只有七天，没有“星期十”，“十”应改为“四”，说“星期四”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们上星期六见面吧。", "corrected_sentence": "我们星期六见面吧。", "error_description": "时间词错误：“上星期六”指过去的周六，与约定将来见面不符。应说“星期六”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
