INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "历史上了这个城市下过一场很大的雪。", "corrected_sentence": "历史上这个城市下过一场很大的雪。", "error_description": "错误形式：“历史上了这个城市”；正确形式：“历史上这个城市”。“历史上”是副词，后面不能直接加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
