INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87422, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在过去的历史中；从前。", "primary_collocate": null, "pronunciation": "lì shǐ shàng", "ipa": "li˥˩ ʂʅ˨˩˦ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "历史上，这座城市曾经很有名。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上这里发生过很多大事。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国历史上有很多有名的诗人。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方在历史上是一个小村子。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书说的是历史上的一件大事。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，他是第一个到过那里的人。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上这家医院帮过很多人。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上我们学校出过不少名人。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，长城修了很多年。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样大的雨，在历史上很少见。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷史上", "label": "繁体"}], "register": "书面", "sense_fingerprint": "历史上：时间状语，在过去的历史中、从前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7777e7df-230e-4f7a-be5d-05cc2cb71220') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史上", "is_correct": true, "explanation": "历史上：在过去的历史中，正合“曾经很有名”这种长久的过去情况。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上发生，与“曾经很有名”的长久情况相矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示进行中，不能与“曾经很有名”搭配。"}, {"text": "特别", "is_correct": false, "explanation": "搭配：“特别”修饰形容词、表示程度，不能单独放在句首作状语。"}], "explanations": {"历史上": "历史上：在过去的历史中，正合“曾经很有名”这种长久的过去情况。", "立刻": "语义：“立刻”指马上发生，与“曾经很有名”的长久情况相矛盾。", "正在": "搭配：“正在”表示进行中，不能与“曾经很有名”搭配。", "特别": "搭配：“特别”修饰形容词、表示程度，不能单独放在句首作状语。"}, "sentence_index": 0, "correct_answer": "历史上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们历史上是同班同学。", "explanation": "这里应该用〈以前〉。历史上指历史长河中的事，我们的同学关系是个人经历，要用以前。"}, {"text": "历史上我刚吃完饭。", "explanation": "这里应该用〈刚才〉。历史上只指很久以前的过去，刚发生的事要用刚才来说。"}, {"text": "历史上我们下午要去医院。", "explanation": "这里应该用〈以后〉。历史上只指过去，将要发生的安排要用以后来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史上", "is_correct": true, "explanation": "历史上：在过去的历史中，正合“帮过很多人”这种长期的经历。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指很快发生，与“帮过很多人”的长期经历相矛盾。"}, {"text": "再也", "is_correct": false, "explanation": "搭配：“再也”必须与“不”连用，不能直接用在“帮过很多人”前。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指忽然发生的事，与长期帮助他人的历史不符。"}], "explanations": {"历史上": "历史上：在过去的历史中，正合“帮过很多人”这种长期的经历。", "马上": "语义：“马上”指很快发生，与“帮过很多人”的长期经历相矛盾。", "再也": "搭配：“再也”必须与“不”连用，不能直接用在“帮过很多人”前。", "突然": "语义：“突然”指忽然发生的事，与长期帮助他人的历史不符。"}, "sentence_index": 6, "correct_answer": "历史上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "历史上我在这家工厂工作过。", "explanation": "这里应该用〈当年〉。历史上指历史长河中的事，个人经历要用当年。"}, {"text": "历史上我正在学习汉语。", "explanation": "这里应该用〈现在〉。历史上指很久以前的过去，描述此刻正在进行的学习要用现在。"}, {"text": "历史上我们要去北京旅游。", "explanation": "这里应该用〈以后〉。历史上只指过去，不能用来说将要进行的计划；将来的打算要用以后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家历史上的画过很多画。", "corrected_sentence": "这位画家历史上画过很多画。", "error_description": "“历史上”后面直接接动词，不能加“的”：“历史上的画过”误用了“的”，应说“历史上画过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15864d4b-d276-4b70-a8ee-d59a3a4261a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
