INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "容貌美丽的女子。", "primary_collocate": null, "pronunciation": "měi nǚ", "ipa": "meɪ̯˧˥ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "古时候有四大美女，大家都听说过。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画上的美女站在花园里。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位美女不但长得好看，心也很好。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了一位住在山里的美女。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他梦见自己遇到了一位美女。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上走过一位容貌出众的美女。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西施是中国历史上有名的美女。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家有很多美女，也有很多美景。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员们个个都是美女，镜头前很迷人。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说村里来了一位美女，大家都去看。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "美女们", "label": "复数"}], "register": "口语", "sense_fingerprint": "容貌美丽的女子：古代美女、画中美女", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78bd22d5-58b2-46ac-bd58-f8a4351aa496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "搭配：“四大”后多接“美女、名著、发明”等固定组合，不能接“石头”。"}, {"text": "美女", "is_correct": true, "explanation": "符合语境：指古代著名的美丽女子，与“四大”搭配自然。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古时候没有手机，与“古时候”的语境冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：古时候没有汽车，与“古时候”的语境冲突。"}], "explanations": {"石头": "搭配：“四大”后多接“美女、名著、发明”等固定组合，不能接“石头”。", "美女": "符合语境：指古代著名的美丽女子，与“四大”搭配自然。", "手机": "语义：古时候没有手机，与“古时候”的语境冲突。", "汽车": "语义：古时候没有汽车，与“古时候”的语境冲突。"}, "sentence_index": 0, "correct_answer": "美女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书里写的那个计划是个美女。", "explanation": "这里应该用〈好〉。“美女”指人，不能用来评价计划的好坏；评价事物要用“好”。"}, {"text": "书里写的那位女子的职业是美女。", "explanation": "这里应该用〈歌手〉。“美女”描述外貌，不是职业名称。"}, {"text": "书里写的那个猎人是个美女。", "explanation": "这里应该用〈帅哥〉。“美女”只用于女性，不能用来形容男性猎人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皇帝", "is_correct": false, "explanation": "语义：西施是女子，不可能是皇帝，与句子的人物矛盾。"}, {"text": "老太太", "is_correct": false, "explanation": "体貌：老太太的年龄与西施年轻美丽的形象不符。"}, {"text": "美女", "is_correct": true, "explanation": "符合语境：指历史上有名的美丽女子，与西施的身份一致。"}, {"text": "城市", "is_correct": false, "explanation": "语义：西施指人，不是城市，句意矛盾。"}], "explanations": {"皇帝": "语义：西施是女子，不可能是皇帝，与句子的人物矛盾。", "老太太": "体貌：老太太的年龄与西施年轻美丽的形象不符。", "美女": "符合语境：指历史上有名的美丽女子，与西施的身份一致。", "城市": "语义：西施指人，不是城市，句意矛盾。"}, "sentence_index": 6, "correct_answer": "美女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听说村里的庙会是个美女，大家都去看。", "explanation": "这里应该用〈热闹〉。“美女”指人，不用来称呼庙会；形容庙会的场面要说“热闹”。"}, {"text": "听说村里的老房子是美女，大家都去看。", "explanation": "这里应该用〈漂亮〉。“美女”指人，不用来形容建筑；形容老房子的外观要说“漂亮”。"}, {"text": "听说村里来了一个小伙子，他是个美女，大家都去看。", "explanation": "这里应该用〈帅哥〉。“美女”只用于女性，形容男性要说“帅哥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书里写了一美女，她住在山里。", "corrected_sentence": "书里写了一位美女，她住在山里。", "error_description": "量词缺失：数词“一”与“美女”之间应加量词“位”或“个”，应说“一位美女”，不能直接说“一美女”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街上走过很多美女们，大家都回头看。", "corrected_sentence": "街上走过很多美女，大家都回头看。", "error_description": "词尾误加：“很多”已经表示数量多，“美女”后面不应再加“们”，应说“很多美女”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
