INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写给对方，说明事情或问候的文字；书信。", "primary_collocate": null, "pronunciation": "xìn", "ipa": "ɕin˥˩", "syllable_count": 1, "sentences": [{"text": "老师的信里写了很多话。", "target_word": "信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在信里问我身体好不好。", "target_word": "信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我收到一封来自北京的信。", "target_word": "信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶不会用手机，只会写信。", "target_word": "信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读完你的信，我很想家。", "target_word": "信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的信很短，只有三句话。", "target_word": "信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我回一封信。", "target_word": "信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的信我已经看过了。", "target_word": "信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每周都给我寄一封信。", "target_word": "信", "complexity_tier": "T3", "furigana": "xìn", "sentence_source": "generated"}, {"text": "信里说他下个月回国。", "target_word": "信", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "封", "label": "量词"}, {"form": "书信", "label": "复合"}, {"form": "信件", "label": "复合"}], "register": "中性", "sense_fingerprint": "信：名词，写给对方的书信文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a694cc8-f902-4891-9c84-c2b01ecc1500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87444, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "信", "is_correct": true, "explanation": "正确答案：信（xìn），意思是书信。"}, {"text": "心", "is_correct": false, "explanation": "xīn（第一声）与 xìn（第四声）声调不同，意思是心脏、心思。"}, {"text": "兴", "is_correct": false, "explanation": "xìng 与 xìn 只差韵尾 -ng 和 -n，意思是兴趣、高兴。"}, {"text": "薪", "is_correct": false, "explanation": "xīn（第一声）与 xìn（第四声）声调不同，意思是薪水。"}, {"text": "迅", "is_correct": false, "explanation": "xùn 与 xìn 只差韵母 in 和 un，意思是迅速。"}], "explanations": {"信": "正确答案：信（xìn），意思是书信。", "心": "xīn（第一声）与 xìn（第四声）声调不同，意思是心脏、心思。", "兴": "xìng 与 xìn 只差韵尾 -ng 和 -n，意思是兴趣、高兴。", "薪": "xīn（第一声）与 xìn（第四声）声调不同，意思是薪水。", "迅": "xùn 与 xìn 只差韵母 in 和 un，意思是迅速。"}, "sentence_index": null, "correct_answer": "信"}, "level_3": {"options": [{"text": "信", "is_correct": true, "explanation": "“老师的信”指老师写的书信，“信里”表示书信的内容，符合句意。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调不能写字，“老师的空调里写了很多话”与句意不符。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：表示平面上的位置要用“上”，应说“黑板上”，不说“黑板里”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里不会写话，与“写了很多话”的语境不符。"}], "explanations": {"信": "“老师的信”指老师写的书信，“信里”表示书信的内容，符合句意。", "空调": "语义：空调不能写字，“老师的空调里写了很多话”与句意不符。", "黑板": "搭配：表示平面上的位置要用“上”，应说“黑板上”，不说“黑板里”。", "冰箱": "语义：冰箱里不会写话，与“写了很多话”的语境不符。"}, "sentence_index": 0, "correct_answer": "信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶不会用手机，只会写一张信。", "explanation": "这里应该用〈封〉。量词“张”用于纸张等平面物，书信要用“封”。"}, {"text": "爷爷每天都写一条信给我。", "explanation": "这里应该用〈封〉。量词“条”用于细长的东西，不用于书信。"}, {"text": "他寄来一只信，里面写满了话。", "explanation": "这里应该用〈封〉。量词“只”用于动物或成对的东西，书信不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87444, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "信", "is_correct": true, "explanation": "正确答案：信（xìn），意思是书信。"}, {"text": "性", "is_correct": false, "explanation": "xìng 与 xìn 只差韵尾 -ng 和 -n，意思是性格、性质。"}, {"text": "新", "is_correct": false, "explanation": "xīn（第一声）与 xìn（第四声）声调不同，意思是新的。"}, {"text": "辛", "is_correct": false, "explanation": "xīn（第一声）与 xìn（第四声）声调不同，意思是辛苦、辣。"}, {"text": "训", "is_correct": false, "explanation": "xùn 与 xìn 只差韵母 in 和 un，意思是训练。"}], "explanations": {"信": "正确答案：信（xìn），意思是书信。", "性": "xìng 与 xìn 只差韵尾 -ng 和 -n，意思是性格、性质。", "新": "xīn（第一声）与 xìn（第四声）声调不同，意思是新的。", "辛": "xīn（第一声）与 xìn（第四声）声调不同，意思是辛苦、辣。", "训": "xùn 与 xìn 只差韵母 in 和 un，意思是训练。"}, "sentence_index": null, "correct_answer": "信"}, "level_3": {"options": [{"text": "信", "is_correct": true, "explanation": "“一封信”是书信的常用量词搭配，“回信”符合句意。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“封”只用于书信，礼物不用“封”，不说“回一封礼物”。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送的，不能用“回”，与“请给我回……”不相容。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是看的，不能用“回”来搭配，句子不通。"}], "explanations": {"信": "“一封信”是书信的常用量词搭配，“回信”符合句意。", "礼物": "语义：礼物是送的，不能用“回”，与“请给我回……”不相容。", "电影": "语义：电影是看的，不能用“回”来搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶的信生病了，要去医院看看。", "explanation": "这里的〈信〉被当成会生病的东西，信不会生病；〈信〉指写给对方的文字。"}, {"text": "我把爷爷的信煮熟了，当作午饭吃。", "explanation": "这里的〈信〉被当成食物，信不能吃；书信的〈信〉指写给对方的文字，不能用于烹饪。"}, {"text": "他把这封信当成钥匙，用它开门。", "explanation": "这里的〈信〉被当成钥匙用，与书信的意思不符；〈信〉指写给对方的文字，不能用来开门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
