INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他寄给我一个很长的信。", "corrected_sentence": "他寄给我一封很长的信。", "error_description": "量词错误：书信的量词是“封”，“个”不能用于信。正确说法是“他寄给我一封很长的信。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
