INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在人和动物体内循环流动的红色液体。", "primary_collocate": null, "pronunciation": "xuè", "ipa": "ɕɥe˥˩", "syllable_count": 1, "sentences": [{"text": "他的手流了很多血。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血在身体里不停地流动。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给我抽了一点血。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血是红色的。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤了，地上有血。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物的身体里也有血。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衣服上沾着血。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏把血送到全身。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚊子喝了我的血。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些血是从哪里来的？", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "血液", "label": "复合词"}, {"form": "血管", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人和动物体内循环流动的红色液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbe6c0-1a36-4377-a066-54ce1f0a44eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87452, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "血", "is_correct": true, "explanation": "正确答案：血（xuè），在人和动物体内循环流动的红色液体。"}, {"text": "学", "is_correct": false, "explanation": "xué（第二声）与 xuè（第四声）声调不同，意思是“学习”。"}, {"text": "雪", "is_correct": false, "explanation": "xuě（第三声）与 xuè（第四声）声调不同，意思是“雪花”。"}, {"text": "谢", "is_correct": false, "explanation": "xiè 与 xuè 声调相同，韵母的元音不同（ie 与 üe），意思是“感谢”。"}], "explanations": {"血": "正确答案：血（xuè），在人和动物体内循环流动的红色液体。", "学": "xué（第二声）与 xuè（第四声）声调不同，意思是“学习”。", "雪": "xuě（第三声）与 xuè（第四声）声调不同，意思是“雪花”。", "谢": "xiè 与 xuè 声调相同，韵母的元音不同（ie 与 üe），意思是“感谢”。"}, "sentence_index": null, "correct_answer": "血"}, "level_3": {"options": [{"text": "血", "is_correct": true, "explanation": "正确答案：“流了很多血”符合手受伤流血的语境。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不是液体，“流了很多眼睛”不成立。"}, {"text": "字", "is_correct": false, "explanation": "语义：“字”不是能从手上流出的东西，与“流”的意思不符。"}, {"text": "脸", "is_correct": false, "explanation": "搭配：“流”通常指液体流出，“脸”不能与“流了很多”搭配。"}], "explanations": {"血": "正确答案：“流了很多血”符合手受伤流血的语境。", "眼睛": "语义：眼睛不是液体，“流了很多眼睛”不成立。", "字": "语义：“字”不是能从手上流出的东西，与“流”的意思不符。", "脸": "搭配：“流”通常指液体流出，“脸”不能与“流了很多”搭配。"}, "sentence_index": 0, "correct_answer": "血"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一根血是红色的。", "explanation": "量词错误：“血”前一般用“滴”“管”“袋”等，不用“根”。应说“一滴血”。"}, {"text": "地上有一个血，是谁受伤了？", "explanation": "量词错误：“血”不用“个”计量，指一摊或一滴时应说“一摊血”或“一滴血”。"}, {"text": "一颗血掉在地上了。", "explanation": "量词错误：“颗”用于颗粒状的东西，不用来计量“血”。应说“一滴血”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血", "is_correct": true, "explanation": "正确答案：“沾着血”描述衣服上的血迹，符合语境。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是机器，不能沾在衣服上。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不能沾在衣服上。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“沾着”通常指污渍或细小的东西附着，“闹钟”不能这样搭配。"}], "explanations": {"血": "正确答案：“沾着血”描述衣服上的血迹，符合语境。", "电脑": "语义：“电脑”是机器，不能沾在衣服上。", "窗户": "语义：“窗户”是建筑部件，不能沾在衣服上。", "闹钟": "搭配：“沾着”通常指污渍或细小的东西附着，“闹钟”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "血"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一条血是从哪里来的？", "explanation": "量词错误：“条”用于细长的东西，不用来计量“血”。指一摊或一滴时应说“这一摊血”。"}, {"text": "地上这只血是从哪里来的？", "explanation": "量词错误：“只”用于动物或成对的物品，不用来计量“血”。指一摊或一滴时应说“这一摊血”。"}, {"text": "这一本血是从哪里来的？", "explanation": "量词错误：“本”用于书册，不用来计量“血”。指一摊或一滴时应说“这一摊血”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的膝盖流了很多个血。", "corrected_sentence": "他的膝盖流了很多血。", "error_description": "量词错误：“血”是物质名词，前面不能直接用“个”计量。应去掉“个”，说“很多血”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌子上有一摊的血。", "corrected_sentence": "桌子上有一摊血。", "error_description": "结构错误：“有”字句中，“一摊血”是数量名结构，中间不能加“的”。应去掉“的”，说“桌子上有一摊血”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
