INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87457, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装备是做一件事需要的东西，比如打仗或运动时用的东西。", "primary_collocate": null, "pronunciation": "zhuāng bèi", "ipa": "ʈʂwɑŋ˥ pei˥˩", "syllable_count": 2, "sentences": [{"text": "打仗时，士兵要带好装备。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "踢球要有合适的装备。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的潜水装备放在家里。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背着很重的装备上山。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动前先准备好装备。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套钓鱼装备是爸爸送的。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有装备，我们不能下水。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的装备有哪些？", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的摄影装备很专业。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她借了朋友的骑行装备。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "裝備", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事或运动时需要用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbe6c0-1a36-4377-a066-54ce1f0a44eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87457, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "装备", "is_correct": true, "explanation": "正确：“带好装备”指携带打仗所需的器械与用具，符合句意。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话不是打仗时要携带的东西，与语境不合。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“带”的对象是具体物品，不能说“带名字”。"}, {"text": "诗歌", "is_correct": false, "explanation": "语域：诗歌偏文学，与“打仗时要带的东西”这类实用语境不协调。"}], "explanations": {"装备": "正确：“带好装备”指携带打仗所需的器械与用具，符合句意。", "笑话": "语义：笑话不是打仗时要携带的东西，与语境不合。", "名字": "搭配：“带”的对象是具体物品，不能说“带名字”。", "诗歌": "语域：诗歌偏文学，与“打仗时要带的东西”这类实用语境不协调。"}, "sentence_index": 0, "correct_answer": "装备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她戴着一套漂亮的装备去逛街。", "explanation": "这里应该用〈首饰〉。装备指做某件事需要的东西，逛街时戴的饰物不叫装备，要说“首饰”。"}, {"text": "这份装备包装得很精美。", "explanation": "这里应该用〈礼品〉。装备指做某件事需要的东西，包装精美的是礼物，不叫装备。"}, {"text": "客厅里的装备很舒服，大家都喜欢坐。", "explanation": "这里应该用〈沙发〉。装备指做某件事需要的东西，客厅里供人坐的家具不叫装备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装备", "is_correct": true, "explanation": "正确：“没有装备”指缺少下水所需的器材，符合句意。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声与下水的条件无关，句子语义不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是下水需要具备的用品，句子不通。"}, {"text": "诗句", "is_correct": false, "explanation": "语域：诗句偏书面文学，与条件分句的实用语境不协调。"}], "explanations": {"装备": "正确：“没有装备”指缺少下水所需的器材，符合句意。", "笑声": "语义：笑声与下水的条件无关，句子语义不通。", "颜色": "语义：颜色不是下水需要具备的用品，句子不通。", "诗句": "语域：诗句偏书面文学，与条件分句的实用语境不协调。"}, "sentence_index": 6, "correct_answer": "装备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷穿着装备坐在沙发上看报纸。", "explanation": "这里应该用〈居家服〉。装备指为某项活动配备的器械或服装，在家看报时穿的衣服不叫装备。"}, {"text": "孩子晚上抱着装备睡觉。", "explanation": "这里应该用〈玩偶〉。装备指做某件事需要的东西，睡觉时抱的玩偶不叫装备。"}, {"text": "工人把灯装备在天花板上。", "explanation": "这里应该用〈安装〉。装备作动词指配备、供给，不表示把东西固定在某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只登山装备很重。", "corrected_sentence": "这套登山装备很重。", "error_description": "量词误用：“只”用于动物或成对物件中的一件，不能用来计量装备；装备可用“件”或“套”计量，正确说法如“这套登山装备很重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些登山装备们都很新。", "corrected_sentence": "这些登山装备都很新。", "error_description": "“们”只用于指人，不能附在“装备”后面。正确说法是“这些登山装备都很新”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
