INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为从事某项活动所配备的器械、用具、服装等。", "primary_collocate": null, "pronunciation": "zhuāng bèi", "ipa": "ʈʂwɑŋ˥ pei˥˩", "syllable_count": 2, "sentences": [{"text": "消防员穿好了全部装备。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套滑雪装备很贵。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队的装备越来越好。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一套新的登山装备。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发前请检查你的装备。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球员们换好装备走进球场。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野外工作需要专业装备。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把装备放在车里了。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支队伍的装备很先进。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些装备是工厂生产的。", "target_word": "装备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "裝備", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为某项活动配备的器械用具服装", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbe6c0-1a36-4377-a066-54ce1f0a44eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "装备", "is_correct": true, "explanation": "正确：“穿好装备”指穿戴消防所需的全套器具与服装，符合句意。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物或身上的装具，不能说“穿工具”。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是消防员出警时要穿戴的东西，与句子语境不符。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“穿”不能搭配行李，行李是用来装或拿的。"}], "explanations": {"装备": "正确：“穿好装备”指穿戴消防所需的全套器具与服装，符合句意。", "工具": "搭配：“穿”的对象是衣物或身上的装具，不能说“穿工具”。", "食物": "语义：食物不是消防员出警时要穿戴的东西，与句子语境不符。", "行李": "搭配：“穿”不能搭配行李，行李是用来装或拿的。"}, "sentence_index": 0, "correct_answer": "装备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气吃掉了一整套装备。", "explanation": "这里应该用〈点心〉。装备指为某项活动配备的器械、用具或服装，能吃的东西不叫装备，应说“点心”。"}, {"text": "这些装备让橱窗看起来很漂亮。", "explanation": "这里应该用〈装饰〉。装备指为某项活动配备的器械、用具或服装，装点橱窗只能说“装饰”。"}, {"text": "这间屋子的装备很简陋，只有一张床。", "explanation": "这里应该用〈家具〉。装备指为某项活动配备的器械、用具或服装，屋里的床和桌椅是家具，不叫装备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装备", "is_correct": true, "explanation": "正确：“专业装备”指野外工作所需的专业器械与用具，符合句意。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是野外工作所需的专业用品，句子不通。"}, {"text": "玩笑", "is_correct": false, "explanation": "搭配：“专业”不修饰“玩笑”，不能说“专业玩笑”。"}, {"text": "诗歌", "is_correct": false, "explanation": "语域：诗歌是文学体裁，与“野外工作需要”的实用语境不协调。"}], "explanations": {"装备": "正确：“专业装备”指野外工作所需的专业器械与用具，符合句意。", "饮料": "语义：饮料不是野外工作所需的专业用品，句子不通。", "玩笑": "搭配：“专业”不修饰“玩笑”，不能说“专业玩笑”。", "诗歌": "语域：诗歌是文学体裁，与“野外工作需要”的实用语境不协调。"}, "sentence_index": 6, "correct_answer": "装备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿着装备坐在沙发上看电视。", "explanation": "这里应该用〈睡衣〉。装备指为某项活动配备的器械或服装，在家看电视时穿的睡衣不叫装备。"}, {"text": "她戴着这套装备去参加晚宴。", "explanation": "这里应该用〈首饰〉。装备指为某项活动配备的器械、用具或服装，晚宴上戴的饰物不叫装备。"}, {"text": "图书馆里摆放着很多装备。", "explanation": "这里应该用〈书籍〉。装备指为某项活动配备的器械、用具或服装，图书馆里的书籍不叫装备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只登山装备。", "corrected_sentence": "他有一套登山装备。", "error_description": "量词误用：“只”用于动物或成对物件中的一件，不能用来计量装备；装备可用“件”或“套”计量，正确说法如“他有一套登山装备”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些登山装备们都是工厂生产的。", "corrected_sentence": "这些登山装备都是工厂生产的。", "error_description": "“们”只用于指人，不能附在“装备”这类无生命名词后面。正确说法是“这些登山装备都是工厂生产的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
