INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87459, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外国是我们的国家以外的别的国家。", "primary_collocate": null, "pronunciation": "wài guó", "ipa": "waɪ˥˩ kwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "我想去外国旅行。", "target_word": "外国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在外国住了五年。", "target_word": "外国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国的冬天比这里冷。", "target_word": "外国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子从没去过外国。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在外国工作，一年回来一次。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包是从外国买来的。", "target_word": "外国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国的朋友给我寄了一张卡片。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的女儿想去外国上大学。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去外国要先办护照。", "target_word": "外国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国的电影在这儿很受欢迎。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "外國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "外国：我们自己的国家以外的别的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7ff3108-def9-4a18-b93a-70244681d64f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外国", "is_correct": true, "explanation": "正确答案：外国，“我想去___旅行”中指本国以外的国家。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是家务场所，不是旅行的目的地。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，不能作为旅行的目的地。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“旅行”的去向应是地点，“工资”不能作为去向。"}], "explanations": {"外国": "正确答案：外国，“我想去___旅行”中指本国以外的国家。", "厨房": "语义：厨房是家务场所，不是旅行的目的地。", "医院": "语义：医院是看病的地方，不能作为旅行的目的地。", "工资": "搭配：“旅行”的去向应是地点，“工资”不能作为去向。"}, "sentence_index": 0, "correct_answer": "外国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭馆外国有很多人在排队。", "explanation": "这里应该用〈外面〉。外国指别的国家，不能指饭馆的外面。"}, {"text": "屋子外国很冷，你多穿点衣服。", "explanation": "这里应该用〈外头〉。外国指国家，不能指屋子外面的地方。"}, {"text": "这个城市的外国很大，有很多高楼。", "explanation": "这里应该用〈郊区〉。外国指别的国家，不能指本国城市的郊区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外国", "is_correct": true, "explanation": "正确答案：外国，“___的朋友”指来自别国的朋友。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能有朋友给我寄卡片。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能有朋友给我寄卡片。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：“夜晚”是时段，“夜晚的朋友”搭配不通，与寄卡片的情节无关。"}], "explanations": {"外国": "正确答案：外国，“___的朋友”指来自别国的朋友。", "冰箱": "语义：冰箱是家电，不能有朋友给我寄卡片。", "桌子": "语义：桌子是家具，不能有朋友给我寄卡片。", "夜晚": "语义：“夜晚”是时段，“夜晚的朋友”搭配不通，与寄卡片的情节无关。"}, "sentence_index": 6, "correct_answer": "外国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很会说外国，连老师都夸他。", "explanation": "这里应该用〈外语〉。外语指外国的语言；外国是国家，不能指语言。"}, {"text": "这是家里的事，不要让外国知道。", "explanation": "这里应该用〈外人〉。外人指不相关的人；外国是国家，不能指人。"}, {"text": "我外国住在乡下，每年都去看她。", "explanation": "这里应该用〈外婆〉。外婆是指人的称谓；外国是国家，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我外国学习汉语。", "corrected_sentence": "我在外国学习汉语。", "error_description": "错误：“外国”作地点时前面要加介词“在”，漏掉后句子不完整。正确应为：我在外国学习汉语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是外国学成回来的。", "corrected_sentence": "他是从外国学成回来的。", "error_description": "错误：表示“从哪里来”要用介词“从”，漏掉后句子意思不清。正确应为：他是从外国学成回来的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
