INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本国以外的国家。", "primary_collocate": null, "pronunciation": "wài guó", "ipa": "waɪ˥˩ kwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "外国的菜他吃不习惯。", "target_word": "外国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说去外国留学要学好外语。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师来自外国，不会说中文。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在外国看见了很多新东西。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸去外国开会，下周才回家。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，在外国的孩子都会回家。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国的钱和我们的钱不一样。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去过很多外国，看了很多地方。", "target_word": "外国", "complexity_tier": "T3", "furigana": "tā qù guò hěn duō wài guó, kàn le hěn duō dì fāng.", "sentence_source": "generated"}, {"text": "到外国要坐很久的飞机。", "target_word": "外国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖很多外国的东西。", "target_word": "外国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "外國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "外国：本国之外的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7ff3108-def9-4a18-b93a-70244681d64f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外国", "is_correct": true, "explanation": "正确答案：外国，“___的菜”指外国的菜肴。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁不能做菜，不能说“地铁的菜”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能做菜，不能说“手机的菜”。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“衣服”不能修饰“菜”，搭配不当。"}], "explanations": {"外国": "正确答案：外国，“___的菜”指外国的菜肴。", "地铁": "语义：地铁不能做菜，不能说“地铁的菜”。", "手机": "语义：手机不能做菜，不能说“手机的菜”。", "衣服": "搭配：“衣服”不能修饰“菜”，搭配不当。"}, "sentence_index": 0, "correct_answer": "外国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看见了一只外国，很可爱。", "explanation": "外国是国家，量词应用“个”，“只”不能用于国家。"}, {"text": "他的外国借给我一本书。", "explanation": "这里应该用〈外婆〉。外国是国家，不能指人；指他的亲属应用〈外婆〉。"}, {"text": "他在学校学外国，成绩很好。", "explanation": "这里应该用〈外语〉。外语指语言；外国是国家，不能指学习的科目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外国", "is_correct": true, "explanation": "正确答案：外国，“___的钱”指外国的货币。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶没有钱，不能说“树叶的钱”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能拥有钱，句子读起来不通。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“电视”不能拥有钱，搭配不当。"}], "explanations": {"外国": "正确答案：外国，“___的钱”指外国的货币。", "树叶": "语义：树叶没有钱，不能说“树叶的钱”。", "月亮": "语义：月亮不能拥有钱，句子读起来不通。", "电视": "搭配：“电视”不能拥有钱，搭配不当。"}, "sentence_index": 6, "correct_answer": "外国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的外国很漂亮，很多人都来看。", "explanation": "这里应该用〈外观〉。外观指外形；外国是国家，不能指外形。"}, {"text": "这家店的外国刷了白漆。", "explanation": "这里应该用〈外墙〉。外墙指建筑的外面墙壁；外国是国家，不能指墙壁。"}, {"text": "这家店的外国每天都有很多人来。", "explanation": "这里应该用〈门口〉。外国是国家，不能指店铺的出入口；店门外的位置应用〈门口〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐去过好几只外国。", "corrected_sentence": "我姐姐去过好几个外国。", "error_description": "错误：“外国”是国家，量词应用“个”，不能用“只”。正确应为：我姐姐去过好几个外国。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她现在外国教书。", "corrected_sentence": "她现在在外国教书。", "error_description": "错误：“外国”作地点时前面要加介词“在”，漏掉后句子不完整。正确应为：她现在在外国教书。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
