INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87466, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第三人称复数代词，指两个以上的女性。", "primary_collocate": null, "pronunciation": "tā men", "ipa": "tʰa⁵⁵ mən", "syllable_count": 2, "sentences": [{"text": "小丽和小红都来了，她们带来了蛋糕。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的女同事们说，她们明天不上班。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三位女歌手站在台上，大家都看着她们。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶和外婆是好朋友，她们常常聊天。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的姐姐们都很高，她们喜欢打篮球。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些女老师对学生很好，学生也喜欢她们。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玛丽和安娜是我的邻居，她们住在三楼。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩们跑了过来，她们的脸都红了。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李是女警察，她们每天都很忙。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给两个妹妹买了新书，她们很喜欢。", "target_word": "她们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "她", "label": "单数"}], "register": "中性", "sense_fingerprint": "第三人称复数代词，指两个以上的女性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f4d827-5213-4efb-b0e0-f6115791d1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "她们", "is_correct": true, "explanation": "她们指两个以上的女性，「小丽和小红都来了，她们带来了蛋糕」正确。"}, {"text": "他", "is_correct": false, "explanation": "语义：「他」指单个男性，不能指小丽和小红两个女性。"}, {"text": "那个", "is_correct": false, "explanation": "配价：「那个」只指一个事物，不能与两个主语搭配。"}, {"text": "其他", "is_correct": false, "explanation": "搭配：「其他」指其余的人或事，与「小丽和小红」不搭配。"}], "explanations": {"她们": "她们指两个以上的女性，「小丽和小红都来了，她们带来了蛋糕」正确。", "他": "语义：「他」指单个男性，不能指小丽和小红两个女性。", "那个": "配价：「那个」只指一个事物，不能与两个主语搭配。", "其他": "搭配：「其他」指其余的人或事，与「小丽和小红」不搭配。"}, "sentence_index": 0, "correct_answer": "她们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶住在乡下，她们每天给我做饭。", "explanation": "这里应该用〈她〉。句中只有奶奶一人，要用单数〈她〉。"}, {"text": "爷爷和叔叔是好朋友，她们常常聊天。", "explanation": "这里应该用〈他们〉。爷爷和叔叔是男性，她们只指女性，要用〈他们〉。"}, {"text": "桌上的两本书很厚，她们很新。", "explanation": "这里应该用〈它们〉。她们只指人，指书要用〈它们〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "她们", "is_correct": true, "explanation": "她们指两个以上的女性，「玛丽和安娜是我的邻居，她们住在三楼」正确。"}, {"text": "你们", "is_correct": false, "explanation": "语义：「你们」指对话的对象，不指玛丽和安娜。"}, {"text": "这个", "is_correct": false, "explanation": "配价：「这个」只指一个事物，不能与两个人的主语搭配。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：「自己」指主语本人，不能指玛丽和安娜。"}], "explanations": {"她们": "她们指两个以上的女性，「玛丽和安娜是我的邻居，她们住在三楼」正确。", "你们": "语义：「你们」指对话的对象，不指玛丽和安娜。", "这个": "配价：「这个」只指一个事物，不能与两个人的主语搭配。", "自己": "搭配：「自己」指主语本人，不能指玛丽和安娜。"}, "sentence_index": 6, "correct_answer": "她们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明和小红去书店，她们都很喜欢。", "explanation": "这里应该用〈他们〉。句中有男孩小明，「她们」只指女性，有男性在内要用〈他们〉。"}, {"text": "一个女孩去书店，她们都很喜欢。", "explanation": "这里应该用〈她〉。句中只有一个女孩，要用单数〈她〉，「她们」指两个以上的人。"}, {"text": "我买了两只小狗，她们很喜欢。", "explanation": "这里应该用〈它们〉。「她们」只指女性的人，指小狗等动物要用〈它们〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位阿姨住在楼下，她每天早上散步。", "corrected_sentence": "两位阿姨住在楼下，她们每天早上散步。", "error_description": "代词错误：「两位阿姨」是两个人，指代要用复数「她们」，单数「她」只能指一人。正确说法是「她们每天早上散步」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个女孩很高兴，她们的都很开心。", "corrected_sentence": "两个女孩很高兴，她们都很开心。", "error_description": "结构错误：「她们」后面不能加「的」，「她们的」变成所有格，后面不能接「都很开心」。正确说法是「她们都很开心」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
