INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "猪是农场里养的动物，身体胖胖的，鼻子长长的。", "primary_collocate": null, "pronunciation": "zhū", "ipa": "ʈʂu˥", "syllable_count": 1, "sentences": [{"text": "农场里有三头猪，它们正在吃东西。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那头猪的鼻子长长的，身体也很胖。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民每天早上给猪喂饲料。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头猪太胖了，走路很慢。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猪喜欢在泥里玩儿。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家养了五头猪和十只鸡。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，猪都睡在自己的圈里。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说猪的耳朵大大的，鼻子长长的。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在农场看见了一头很大的猪。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一头猪跑出了圈，农民急忙去追。", "target_word": "猪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "头", "label": "量词"}, {"form": "猪肉", "label": "复合"}, {"form": "野猪", "label": "复合"}, {"form": "豬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农场里养的动物，身体胖，鼻子长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00e5633-a762-4029-b384-af5ebcd7e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "猪", "is_correct": true, "explanation": "正确答案：猪（zhū），农场里养的家畜。"}, {"text": "竹", "is_correct": false, "explanation": "竹（zhú，第二声）与猪（zhū，第一声）声调不同，意思是竹子。"}, {"text": "主", "is_correct": false, "explanation": "主（zhǔ，第三声）与猪（zhū，第一声）声调不同，意思是主人。"}, {"text": "煮", "is_correct": false, "explanation": "煮（zhǔ，第三声）与猪（zhū，第一声）声调不同，意思是把食物加热。"}, {"text": "书", "is_correct": false, "explanation": "书（shū）与猪（zhū）声母不同（sh 与 zh），意思是书本。"}, {"text": "出", "is_correct": false, "explanation": "出（chū）与猪（zhū）声母不同（ch 与 zh），意思是出去。"}, {"text": "租", "is_correct": false, "explanation": "租（zū）与猪（zhū）声母不同（z 与 zh），意思是出租或租用。"}], "explanations": {"猪": "正确答案：猪（zhū），农场里养的家畜。", "竹": "竹（zhú，第二声）与猪（zhū，第一声）声调不同，意思是竹子。", "主": "主（zhǔ，第三声）与猪（zhū，第一声）声调不同，意思是主人。", "煮": "煮（zhǔ，第三声）与猪（zhū，第一声）声调不同，意思是把食物加热。", "书": "书（shū）与猪（zhū）声母不同（sh 与 zh），意思是书本。", "出": "出（chū）与猪（zhū）声母不同（ch 与 zh），意思是出去。", "租": "租（zū）与猪（zhū）声母不同（z 与 zh），意思是出租或租用。"}, "sentence_index": null, "correct_answer": "猪"}, "level_3": {"options": [{"text": "猪", "is_correct": true, "explanation": "正确：猪，与“三头”搭配，指农场里的家畜。"}, {"text": "狮子", "is_correct": false, "explanation": "语义：狮子是野生动物，不是农场里养的家畜，与“农场里有”不符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“头”是牲畜的量词，书要用“本”，不能说“三头书”。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象不是农场里常养的家畜，与“农场里”冲突。"}], "explanations": {"猪": "正确：猪，与“三头”搭配，指农场里的家畜。", "狮子": "语义：狮子是野生动物，不是农场里养的家畜，与“农场里有”不符。", "书": "搭配：“头”是牲畜的量词，书要用“本”，不能说“三头书”。", "大象": "语义：大象不是农场里常养的家畜，与“农场里”冲突。"}, "sentence_index": 0, "correct_answer": "猪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家养了一条猪，很胖。", "explanation": "这里应该用〈头〉。猪作为家畜要用量词“头”，“条”多用于鱼、狗等，不用于猪。"}, {"text": "我们村的农民养了一匹猪。", "explanation": "这里应该用〈头〉。匹用于马、驴、骡等，猪不用匹。"}, {"text": "我昨天买了两斤猪。", "explanation": "这里应该用〈猪肉〉。猪指活的家畜，称重量的是肉，买肉要说猪肉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "猪", "is_correct": true, "explanation": "正确答案：猪（zhū），农场里养的家畜。"}, {"text": "住", "is_correct": false, "explanation": "住（zhù，第四声）与猪（zhū，第一声）声调不同，意思是居住。"}, {"text": "祝", "is_correct": false, "explanation": "祝（zhù，第四声）与猪（zhū，第一声）声调不同，意思是祝愿。"}, {"text": "初", "is_correct": false, "explanation": "初（chū）与猪（zhū）声母不同（ch 与 zh），意思是开始。"}, {"text": "舒", "is_correct": false, "explanation": "舒（shū）与猪（zhū）声母不同（sh 与 zh），意思是舒服。"}, {"text": "粗", "is_correct": false, "explanation": "粗（cū）与猪（zhū）声母不同（c 与 zh），意思是粗细。"}], "explanations": {"猪": "正确答案：猪（zhū），农场里养的家畜。", "住": "住（zhù，第四声）与猪（zhū，第一声）声调不同，意思是居住。", "祝": "祝（zhù，第四声）与猪（zhū，第一声）声调不同，意思是祝愿。", "初": "初（chū）与猪（zhū）声母不同（ch 与 zh），意思是开始。", "舒": "舒（shū）与猪（zhū）声母不同（sh 与 zh），意思是舒服。", "粗": "粗（cū）与猪（zhū）声母不同（c 与 zh），意思是粗细。"}, "sentence_index": null, "correct_answer": "猪"}, "level_3": {"options": [{"text": "猪", "is_correct": true, "explanation": "正确：猪，指睡在圈里的家畜。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师不会睡在动物的圈里，与“圈”不符。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“睡”要求有生命的主语，石头不能睡。"}, {"text": "花", "is_correct": false, "explanation": "配价：“睡”要求有生命的主语，花不能睡。"}], "explanations": {"猪": "正确：猪，指睡在圈里的家畜。", "老师": "语义：老师不会睡在动物的圈里，与“圈”不符。", "石头": "配价：“睡”要求有生命的主语，石头不能睡。", "花": "配价：“睡”要求有生命的主语，花不能睡。"}, "sentence_index": 6, "correct_answer": "猪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家买了一块猪，准备养起来。", "explanation": "这里应该用〈头〉。“块”用于块状的东西，不用于猪。"}, {"text": "我们农场买了一把猪。", "explanation": "这里应该用〈头〉。“把”用于有柄的东西，不用于猪。"}, {"text": "农场里有一张猪，很大。", "explanation": "这里应该用〈头〉。“张”用于平面的东西，不用于猪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷家的院子里养着一条猪。", "corrected_sentence": "爷爷家的院子里养着一头猪。", "error_description": "量词错误：应改为“一头猪”。猪作为家畜用量词“头”，“条”不用于猪。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我叔叔的两个猪养得很胖，他每天都很忙。", "corrected_sentence": "我叔叔的两头猪养得很胖，他每天都很忙。", "error_description": "量词错误：应改为“两头猪”。猪作为家畜用量词“头”，“个”不用于猪。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进入", "is_correct": true, "explanation": "“进入”与“退出”是反义词，指从外面走入同一场所，与“退出”的方向相反。"}, {"text": "坐下", "is_correct": false, "explanation": "与“退出”没有反义关系，二者不构成一对相对的词。"}, {"text": "停留", "is_correct": false, "explanation": "与“退出”没有反义关系，“停留”是留在原处，不是与“退出”相对的动作。"}, {"text": "等候", "is_correct": false, "explanation": "与“退出”没有反义关系，“等候”是等待，不是与“退出”相对的动作。"}], "correct_answer": "进入", "explanations": {"进入": "“进入”与“退出”是反义词，指从外面走入同一场所，与“退出”的方向相反。", "坐下": "与“退出”没有反义关系，二者不构成一对相对的词。", "停留": "与“退出”没有反义关系，“停留”是留在原处，不是与“退出”相对的动作。", "等候": "与“退出”没有反义关系，“等候”是等待，不是与“退出”相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进入", "is_correct": true, "explanation": "“进入”与“退出”是反义词，指从外面走入同一场所，与“退出”的方向相反。"}, {"text": "到达", "is_correct": false, "explanation": "与“退出”没有反义关系，“到达”是抵达某地，不是与“退出”相对的动作。"}, {"text": "驻守", "is_correct": false, "explanation": "与“退出”没有反义关系，“驻守”是长期守在某处，不是与“退出”相对的动作。"}, {"text": "待命", "is_correct": false, "explanation": "与“退出”没有反义关系，“待命”是等待行动的命令，不是与“退出”相对的动作。"}], "correct_answer": "进入", "explanations": {"进入": "“进入”与“退出”是反义词，指从外面走入同一场所，与“退出”的方向相反。", "到达": "与“退出”没有反义关系，“到达”是抵达某地，不是与“退出”相对的动作。", "驻守": "与“退出”没有反义关系，“驻守”是长期守在某处，不是与“退出”相对的动作。", "待命": "与“退出”没有反义关系，“待命”是等待行动的命令，不是与“退出”相对的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "退出是从里面走出来，不再待在里面。", "primary_collocate": null, "pronunciation": "tuì chū", "ipa": "tʰuei̯˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他轻轻退出房间，随手关上了门。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员鞠了躬，慢慢退出了舞台。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人都坐好后，服务员退出了包间。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听到有人敲门，便悄悄退出了办公室。", "target_word": "退出", "complexity_tier": "T3", "furigana": "tā tīng dào yǒu rén qiāo mén, biàn qiāo qiāo tuì chū le bàn gōng shì", "sentence_source": "generated"}, {"text": "孩子睡着了，妈妈轻轻退出了卧室。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理放下文件，向大家点点头，退出了会议室。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先退出教室，在门外等我。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得无聊，中途悄悄退出了会场。", "target_word": "退出", "complexity_tier": "T3", "furigana": "tā jué de wú liáo, zhōng tú qiāo qiāo tuì chū le huì chǎng", "sentence_source": "generated"}, {"text": "屋里太闷，我们先退出了房间，到外面透透气。", "target_word": "退出", "complexity_tier": "T3", "furigana": "wū lǐ tài mēn, wǒ men xiān tuì chū le fáng jiān, dào wài miàn tòu tou qì", "sentence_source": "generated"}, {"text": "警察请大家马上退出这间屋子。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "退出了", "label": "体标"}, {"form": "退出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "从房间、舞台等空间里走出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c54d57b-fa77-4f5f-88d9-3e9f8f091722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退出", "is_correct": true, "explanation": "“退出”指从房间里走出，与“轻轻”“随手关上了门”的动作相符。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能接“房间”，与“轻轻……房间”不搭。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的是歌曲，与“房间”不搭，也不符合“随手关上了门”的情境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，与“房间”无关，句子不成立。"}], "explanations": {"退出": "“退出”指从房间里走出，与“轻轻”“随手关上了门”的动作相符。", "吃": "配价：“吃”的宾语应是食物，不能接“房间”，与“轻轻……房间”不搭。", "唱": "语义：唱的是歌曲，与“房间”不搭，也不符合“随手关上了门”的情境。", "喝": "语义：“喝”的对象是液体，与“房间”无关，句子不成立。"}, "sentence_index": 0, "correct_answer": "退出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到有人敲门，便悄悄退出了钥匙。", "explanation": "这里应该用〈拿〉：拿起钥匙说“拿”；“退出”只用于离开场所、组织或活动，不能接物品。"}, {"text": "他站起来，悄悄退出了那块蛋糕。", "explanation": "这里应该用〈端〉：端起蛋糕说“端”；“退出”只用于离开场所、组织或活动，不能接食物。"}, {"text": "他把借来的书退出了图书馆。", "explanation": "这里应该用〈还〉：归还借的书说“还”；“退出”指离开场所，不能用于书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退出", "is_correct": true, "explanation": "“退出”指从教室出去，与“在门外等我”的安排相符。"}, {"text": "进入", "is_correct": false, "explanation": "语义：“进入”与“在门外等我”矛盾，前后意思不一致。"}, {"text": "占领", "is_correct": false, "explanation": "语义：“占领”指强行占据，与“请你先……在门外等我”的语境不搭。"}, {"text": "咬", "is_correct": false, "explanation": "配价：“咬”的宾语应是可以咬的东西，不能接“教室”。"}], "explanations": {"退出": "“退出”指从教室出去，与“在门外等我”的安排相符。", "进入": "语义：“进入”与“在门外等我”矛盾，前后意思不一致。", "占领": "语义：“占领”指强行占据，与“请你先……在门外等我”的语境不搭。", "咬": "配价：“咬”的宾语应是可以咬的东西，不能接“教室”。"}, "sentence_index": 6, "correct_answer": "退出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋天到了，树叶慢慢退出了绿色。", "explanation": "这里应该用〈褪去〉：颜色消退说“褪去”；“退出”指离开场所、组织或活动，不能用于颜色。"}, {"text": "春天到了，树上退出了新芽。", "explanation": "这里应该用〈长出〉：草木生出新芽说“长出”；“退出”指离开场所、组织或活动，不说“退出新芽”。"}, {"text": "他把嘴里的饭退出来了。", "explanation": "这里应该用〈吐出〉：把嘴里的东西吐出来说“吐出”；“退出”不能用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们刚才悄悄退出在会议室。", "corrected_sentence": "我们刚才悄悄退出了会议室。", "error_description": "介词错误：“退出在会议室”。“退出”后不能用“在”引出所离开的场所，应说“退出了会议室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚退出着房间，马上又回来了。", "corrected_sentence": "他刚退出了房间，马上又回来了。", "error_description": "体标错误：“退出”表示已经完成的离开，应该用“了”，不能用“着”表示持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加入", "is_correct": true, "explanation": "“加入”与“退出”是反义词，指成为某组织或活动的一员，与“退出”的意思相对。"}, {"text": "发展", "is_correct": false, "explanation": "与“退出”没有反义关系，“发展”指事物壮大或进步，不与“退出”相对。"}, {"text": "购买", "is_correct": false, "explanation": "与“退出”没有反义关系，“购买”指花钱获得物品，不与“退出”相对。"}, {"text": "聚会", "is_correct": false, "explanation": "与“退出”没有反义关系，“聚会”指人们相聚，不是与“退出”相对的动作。"}], "correct_answer": "加入", "explanations": {"加入": "“加入”与“退出”是反义词，指成为某组织或活动的一员，与“退出”的意思相对。", "发展": "与“退出”没有反义关系，“发展”指事物壮大或进步，不与“退出”相对。", "购买": "与“退出”没有反义关系，“购买”指花钱获得物品，不与“退出”相对。", "聚会": "与“退出”没有反义关系，“聚会”指人们相聚，不是与“退出”相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加入", "is_correct": true, "explanation": "“加入”与“退出”是反义词，指成为某组织或活动的一员，与“退出”的意思相对。"}, {"text": "维持", "is_correct": false, "explanation": "与“退出”没有反义关系，“维持”指保持原状，不与“退出”相对。"}, {"text": "筹备", "is_correct": false, "explanation": "与“退出”没有反义关系，“筹备”指事先做准备，不与“退出”相对。"}, {"text": "研发", "is_correct": false, "explanation": "与“退出”没有反义关系，“研发”指研究开发，不与“退出”相对。"}], "correct_answer": "加入", "explanations": {"加入": "“加入”与“退出”是反义词，指成为某组织或活动的一员，与“退出”的意思相对。", "维持": "与“退出”没有反义关系，“维持”指保持原状，不与“退出”相对。", "筹备": "与“退出”没有反义关系，“筹备”指事先做准备，不与“退出”相对。", "研发": "与“退出”没有反义关系，“研发”指研究开发，不与“退出”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从某个场所、组织或活动中离开，不再参加。", "primary_collocate": null, "pronunciation": "tuì chū", "ipa": "tʰuei̯˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他不想再踢球了，决定退出足球队。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王因为工作太忙，退出了读书会。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很早就退出了那个微信群。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为受伤，他退出了比赛。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，已经退出了公司。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太累了，我想退出这个活动。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个同学退出了学校的篮球队。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他退出过两次比赛，这次一定要坚持。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她退出了合唱团，专心准备考试。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不赚钱，老板决定退出这个市场。", "target_word": "退出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "退出了", "label": "体标"}, {"form": "退出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "离开组织、比赛、活动，不再参加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c54d57b-fa77-4f5f-88d9-3e9f8f091722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退出", "is_correct": true, "explanation": "“退出”指离开球队，与“不想再踢球了，决定……”的意思一致。"}, {"text": "加入", "is_correct": false, "explanation": "语义：“加入”与“不想再踢球了”矛盾，前后意思不一致。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所，不能接“足球队”。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮品，不能接“足球队”。"}], "explanations": {"退出": "“退出”指离开球队，与“不想再踢球了，决定……”的意思一致。", "加入": "语义：“加入”与“不想再踢球了”矛盾，前后意思不一致。", "打扫": "搭配：“打扫”的对象是场所，不能接“足球队”。", "喝": "配价：“喝”的宾语应是饮品，不能接“足球队”。"}, "sentence_index": 0, "correct_answer": "退出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "因为受伤，他退出了那瓶水。", "explanation": "这里的“退出”被当成了拿走物品，应该用〈拿〉：拿起水说“拿”；“退出”只用于离开组织或活动，不能接物品。"}, {"text": "他觉得不满意，就把衣服退出了商店。", "explanation": "这里应该用〈退货〉：把买的东西还回去说“退货”；“退出”指离开组织或活动，不能用于商品。"}, {"text": "他终于退出了危险，松了一口气。", "explanation": "这里应该用〈脱离〉：脱离危险、困境；“退出”用于组织和活动，不说“退出危险”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退出", "is_correct": true, "explanation": "“退出”指离开学校的篮球队，与“三个同学”的语境相符。"}, {"text": "打破", "is_correct": false, "explanation": "语义：“打破”指打碎或突破，不用于人员组织，与“篮球队”不搭。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能接“篮球队”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能用于组织或团队，与“篮球队”不搭。"}], "explanations": {"退出": "“退出”指离开学校的篮球队，与“三个同学”的语境相符。", "打破": "语义：“打破”指打碎或突破，不用于人员组织，与“篮球队”不搭。", "吃": "配价：“吃”的宾语应是食物，不能接“篮球队”。", "洗": "搭配：“洗”不能用于组织或团队，与“篮球队”不搭。"}, "sentence_index": 6, "correct_answer": "退出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最近的头发退出得很厉害。", "explanation": "这里应该用〈脱落〉：头发掉下来说“脱落”；“退出”指离开场所、组织或活动。"}, {"text": "这棵老树今年又退出了好多新叶。", "explanation": "这里应该用〈长出〉：草木生出新叶说“长出”；“退出”指离开场所、组织或活动，不说“退出新叶”。"}, {"text": "他用力把牙膏里的膏退出来了。", "explanation": "这里应该用〈挤出〉：用力把膏状物从管子里压出来说“挤出”；“退出”不能用于膏状物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她上个月就退出在合唱团。", "corrected_sentence": "她上个月就退出了合唱团。", "error_description": "介词错误：“退出在合唱团”。“退出”后不能用“在”引出所退出的团体，应说“退出了合唱团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们决定退出来这个项目。", "corrected_sentence": "他们决定退出这个项目。", "error_description": "补语错误：“退出”直接带宾语时不能再接“来”，应说“退出这个项目”；若要用“来”，须说“从这个项目退出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
