INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87485, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酒是大人喝的一种含酒精的饮料，喝多了人会头晕。", "primary_collocate": null, "pronunciation": "jiǔ", "ipa": "tɕjoʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "爸爸今天晚上不喝酒。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有一瓶酒。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝了很多酒，头很晕。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车的人不能喝酒。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买了两瓶酒送给朋友。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这杯酒是给你的。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不会喝酒，请给我一杯水。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒喝多了对身体不好。", "target_word": "酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柜子里放着一瓶酒。", "target_word": "酒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚他酒喝多了，今天头还疼。", "target_word": "酒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一杯酒", "label": "量词"}, {"form": "一瓶酒", "label": "量词"}, {"form": "白酒", "label": "复合"}], "register": "中性", "sense_fingerprint": "大人喝的、喝多了会头晕的饮料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbe6c0-1a36-4377-a066-54ce1f0a44eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87485, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酒", "is_correct": true, "explanation": "正确：jiǔ（第三声）指大人喝的含酒精饮料。"}, {"text": "旧", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“旧”，不是饮料。"}, {"text": "就", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“就”。"}, {"text": "救", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“救”。"}, {"text": "究", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“追究、研究”。"}], "explanations": {"酒": "正确：jiǔ（第三声）指大人喝的含酒精饮料。", "旧": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“旧”，不是饮料。", "就": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“就”。", "救": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“救”。", "究": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“追究、研究”。"}, "sentence_index": null, "correct_answer": "酒"}, "level_3": {"options": [{"text": "酒", "is_correct": true, "explanation": "正确：“不喝酒”指不饮用含酒精的饮品，符合语境。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“喝”的对象通常是液体，不能说“喝饭”。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“喝”不能搭配固体的面包，应说“吃面包”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是饮品，无法作为“喝”的对象，句子不通。"}], "explanations": {"酒": "正确：“不喝酒”指不饮用含酒精的饮品，符合语境。", "饭": "搭配：“喝”的对象通常是液体，不能说“喝饭”。", "面包": "搭配：“喝”不能搭配固体的面包，应说“吃面包”。", "书": "语义：书不是饮品，无法作为“喝”的对象，句子不通。"}, "sentence_index": 0, "correct_answer": "酒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子每天早上都喝一杯酒。", "explanation": "这里应该用〈牛奶〉。酒是大人喝的饮料，喝多了会头晕，孩子每天早上喝的应是牛奶。"}, {"text": "他把酒切成了小块。", "explanation": "这里应该用〈苹果〉。酒是液体饮料，不能切成小块，切的应是水果。"}, {"text": "孩子生日派对上，大家都举杯喝酒。", "explanation": "这里应该用〈果汁〉。酒是大人喝的饮料，孩子的生日派对上应喝果汁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87485, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "酒", "is_correct": true, "explanation": "正确：jiǔ（第三声）指大人喝的含酒精饮料。"}, {"text": "舅", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“舅舅”。"}, {"text": "纠", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“纠正”。"}, {"text": "揪", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“揪住”。"}], "explanations": {"酒": "正确：jiǔ（第三声）指大人喝的含酒精饮料。", "舅": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“舅舅”。", "纠": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“纠正”。", "揪": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是“揪住”。"}, "sentence_index": null, "correct_answer": "酒"}, "level_3": {"options": [{"text": "酒", "is_correct": true, "explanation": "正确：“我不会喝酒”与后文“请给我一杯水”形成对比，符合语境。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能说“喝饼干”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能喝，与“一杯水”的语境不合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被当作饮品来喝，句子不通。"}], "explanations": {"酒": "正确：“我不会喝酒”与后文“请给我一杯水”形成对比，符合语境。", "饼干": "搭配：“喝”的对象是液体，不能说“喝饼干”。", "石头": "语义：石头不能喝，与“一杯水”的语境不合。", "空气": "语义：空气不能被当作饮品来喝，句子不通。"}, "sentence_index": 6, "correct_answer": "酒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在教室里喝酒。", "explanation": "这里应该用〈汽水〉。酒是大人喝的饮料，学生在教室里喝的应是汽水。"}, {"text": "妈妈给宝宝倒了一杯酒。", "explanation": "这里应该用〈奶〉。酒是大人喝的饮料，给宝宝倒的应是奶。"}, {"text": "猫咪每天都喝一杯酒。", "explanation": "这里应该用〈清水〉。酒是大人喝的饮料，猫咪每天应喝清水，不能喝酒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他晚上喝了一个白酒。", "corrected_sentence": "他晚上喝了一杯白酒。", "error_description": "量词错误：白酒以“杯”或“瓶”计量，不能说“一个白酒”。正确说法是“一杯白酒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被酒喝完了。", "corrected_sentence": "他把酒喝完了。", "error_description": "介词误用：“酒”是被喝掉的对象，不能作“被”字句的施事。应把“被”改为“把”，说“他把酒喝完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
