INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87489, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "中号是不大也不小的那一种尺寸。", "primary_collocate": null, "pronunciation": "zhōng hào", "ipa": "ʈʂʊŋ˥ xau˥˩", "syllable_count": 2, "sentences": [{"text": "我穿中号的衣服。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件有中号吗？", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鞋是中号的。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的衬衫分小号、中号和大号。", "target_word": "中号", "complexity_tier": "T3", "furigana": "zhōng hào", "sentence_source": "generated"}, {"text": "中号太大，小号正好。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个中号的盒子很合适。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一件中号毛衣。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中号的帽子你戴着正好。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一个中号的杯子。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小号太小，中号可以。", "target_word": "中号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "衣物、杯子等物品不大也不小的尺寸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caabb7e0-2a3a-4f9f-b03d-4a7815969b51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中号", "is_correct": true, "explanation": "中号：不大也不小的尺寸，这里用来修饰衣服。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不是可以穿的东西，与“穿”和“衣服”都不相符。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“穿”不搭配“眼镜”，眼镜要说“戴”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是衣服，也不表示尺寸。"}], "explanations": {"中号": "中号：不大也不小的尺寸，这里用来修饰衣服。", "西瓜": "语义：西瓜是水果，不是可以穿的东西，与“穿”和“衣服”都不相符。", "眼镜": "搭配：“穿”不搭配“眼镜”，眼镜要说“戴”。", "面包": "语义：面包是食物，不是衣服，也不表示尺寸。"}, "sentence_index": 0, "correct_answer": "中号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的中号很高。", "explanation": "这里误用了〈中号〉的尺寸义：〈中号〉只指衣服、鞋等有尺寸物品的型号，不用来说山的高矮。"}, {"text": "这间教室的中号很大。", "explanation": "这里误把〈中号〉用于建筑的规模：〈中号〉只表示衣服、鞋等物品的尺寸型号，教室不按号码分。"}, {"text": "这条河的中号很长。", "explanation": "这里误把〈中号〉用于河流的长短：〈中号〉只表示衣服、鞋等物品的尺寸型号，河流不按号码分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中号", "is_correct": true, "explanation": "中号：不大也不小的尺寸，这里用来修饰毛衣。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，不能修饰毛衣，也不是服装。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：钥匙不是服装，不能和“毛衣”组合。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是衣物，与“毛衣”的意思不相符。"}], "explanations": {"中号": "中号：不大也不小的尺寸，这里用来修饰毛衣。", "冰箱": "语义：冰箱是电器，不能修饰毛衣，也不是服装。", "钥匙": "搭配：钥匙不是服装，不能和“毛衣”组合。", "课本": "语义：课本不是衣物，与“毛衣”的意思不相符。"}, "sentence_index": 6, "correct_answer": "中号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的中号很长。", "explanation": "这里误把〈中号〉用于电影的时长：〈中号〉只表示衣服、鞋等物品的尺寸型号，电影不按号码分。"}, {"text": "这个问题的中号很难。", "explanation": "这里误把〈中号〉用于问题的难度：〈中号〉只表示衣服、鞋等物品的尺寸型号，问题不按号码分。"}, {"text": "天空的中号很蓝。", "explanation": "这里误把〈中号〉用于天空的颜色：〈中号〉只表示衣服、鞋等物品的尺寸型号，天空不按号码分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想换一双中号的衣服。", "corrected_sentence": "我想换一件中号的衣服。", "error_description": "量词错误：“衣服”应用量词“件”，“双”只用于成对的东西（如鞋、袜）。正确说法是“一件中号的衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天买了一件被中号毛衣。", "corrected_sentence": "妈妈昨天买了一件中号毛衣。", "error_description": "多加了“被”：“中号”修饰名词时前面不能加“被”，应为“一件中号毛衣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
