INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "在一定范围之外的地方、时间或事物。", "primary_collocate": null, "pronunciation": "yǐ wài", "ipa": "i˨˩˦ wai˥˩", "syllable_count": 2, "sentences": [{"text": "学校以外有一家小书店。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市以外的空气很好。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班以外的时间我都在家。", "target_word": "以外", "complexity_tier": "T3", "furigana": "xià bān yǐ wài de shí jiān wǒ dōu zài jiā.", "sentence_source": "generated"}, {"text": "这条路以外还有别的路吗？", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家以外的地方我很少去。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子以外是一个大花园。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末以外的日子我很忙。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在白线以外等车。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的家在三环以外。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口以外都是雪。", "target_word": "以外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在名词或时间词后，表示某个范围之外的地方、时间或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caabb7e0-2a3a-4f9f-b03d-4a7815969b51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上午", "is_correct": false, "explanation": "语义：上午是时间，不能表示学校的位置。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：星期是时间单位，不能用来指学校的外面。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天指季节，与地点无关。"}, {"text": "以外", "is_correct": true, "explanation": "正确。以外表示在学校的范围之外，可以指地点。"}], "explanations": {"上午": "语义：上午是时间，不能表示学校的位置。", "星期": "搭配：星期是时间单位，不能用来指学校的外面。", "春天": "语义：春天指季节，与地点无关。", "以外": "正确。以外表示在学校的范围之外，可以指地点。"}, "sentence_index": 0, "correct_answer": "以外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃完饭以外，我们去散步。", "explanation": "这里应该用〈以后〉。以外表示某个范围的外面，不表示时间先后；“吃完饭之后”要用以后。"}, {"text": "在我来以外，他已经到了。", "explanation": "这里应该用〈以前〉。以外表示范围的外面，不表示时间先后；“我来之前”要用以前。"}, {"text": "这个问题在讨论以外，已经解决了。", "explanation": "这里应该用〈之前〉。以外表示范围的外面，不表示先后；“讨论之前”要用之前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时候", "is_correct": false, "explanation": "搭配：时候指时间点，不能直接接在“周末”后面组成范围。"}, {"text": "上面", "is_correct": false, "explanation": "语义：上面指位置在高处，与周末的时间范围无关。"}, {"text": "结果", "is_correct": false, "explanation": "语义：结果指事情的最后状态，不能指时间范围。"}, {"text": "以外", "is_correct": true, "explanation": "正确。以外表示周末之外的日子，可以指时间范围。"}], "explanations": {"时候": "搭配：时候指时间点，不能直接接在“周末”后面组成范围。", "上面": "语义：上面指位置在高处，与周末的时间范围无关。", "结果": "语义：结果指事情的最后状态，不能指时间范围。", "以外": "正确。以外表示周末之外的日子，可以指时间范围。"}, "sentence_index": 6, "correct_answer": "以外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "开会以外，我们先吃了午饭。", "explanation": "这里应该用〈以前〉。以外表示范围的外面，不表示先后；“开会之前”要用以前。"}, {"text": "我们在三点以外见面。", "explanation": "这里应该用〈以后〉。以外表示范围的外面，不表示时间先后；“三点以后见面”要用以后。"}, {"text": "我十八岁以外就毕业了。", "explanation": "这里应该用〈以后〉。以外表示范围的外面，不表示时间先后；「十八岁以后」要用以后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园的以外有一座小桥。", "corrected_sentence": "公园以外有一座小桥。", "error_description": "“以外”前面不能加“的”。以外应直接接在表示范围的名词后面，正确说法是“公园以外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗口很以外都是雪。", "corrected_sentence": "窗口以外都是雪。", "error_description": "副词位置错误：“很”是程度副词，不能放在“以外”前面。应说“窗口以外都是雪”，不能说“窗口很以外都是雪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b367b12a-8299-455f-a174-4891011d28c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87497, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "撤出", "is_correct": true, "explanation": "正确：“撤出”与“占领”相对，指离开原先控制的地方。"}, {"text": "学习", "is_correct": false, "explanation": "无反义关系：“学习”指获取知识，与“占领”不构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”是一种休闲活动，与“占领”不构成反义。"}, {"text": "思考", "is_correct": false, "explanation": "无反义关系：“思考”是动脑活动，与“占领”无关。"}], "correct_answer": "撤出", "explanations": {"撤出": "正确：“撤出”与“占领”相对，指离开原先控制的地方。", "学习": "无反义关系：“学习”指获取知识，与“占领”不构成反义。", "散步": "无反义关系：“散步”是一种休闲活动，与“占领”不构成反义。", "思考": "无反义关系：“思考”是动脑活动，与“占领”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
