INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87497, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占领是用力量走进一个地方，把它当成自己的。", "primary_collocate": null, "pronunciation": "zhàn lǐng", "ipa": "ʈʂan˥˩ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "敌人占领了那座小城。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们很快占领了山顶。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们占领了河边的桥。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队占领了这个国家的首都。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队占领了港口，不让船开走。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年冬天，敌人占领了我们的村子。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们先占领高地，再往前走。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队占领了车站，并把旗插在楼上。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队用了三天时间占领了机场。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王带着军队占领了邻国的土地。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占领了", "label": "完成体"}, {"form": "占领过", "label": "经历体"}, {"form": "占领军", "label": "复合词"}], "register": "中性", "sense_fingerprint": "军队进入并据为己有：占领城市、山顶、土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78bd22d5-58b2-46ac-bd58-f8a4351aa496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占领", "is_correct": true, "explanation": "正确：“占领”指用武力取得并控制某地，与敌人夺取小城的意思相符。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”是去看一看，与敌人夺取城市的意思不符。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象是书籍、报刊，不能说出版小城。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋、室内，不能说装修一座小城。"}], "explanations": {"占领": "正确：“占领”指用武力取得并控制某地，与敌人夺取小城的意思相符。", "参观": "语义：“参观”是去看一看，与敌人夺取城市的意思不符。", "出版": "搭配：“出版”的对象是书籍、报刊，不能说出版小城。", "装修": "搭配：“装修”用于房屋、室内，不能说装修一座小城。"}, "sentence_index": 0, "correct_answer": "占领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察占领了那个小偷。", "explanation": "这里应该用〈逮捕〉。占领指用武力取得并控制某地，不用于抓人。"}, {"text": "他们终于占领了对手。", "explanation": "这里应该用〈打败〉。占领只用于地方、据点，不用于人；对手要用打败。"}, {"text": "他们占领了那只猫。", "explanation": "这里应该用〈捕获〉。捕获用于抓住动物；占领指用武力取得并控制某地，只用于地方、据点，不用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占领", "is_correct": true, "explanation": "正确：“占领”与“先……再往前走”的行军语境相符，指先取得高地。"}, {"text": "订购", "is_correct": false, "explanation": "搭配：“订购”的对象是商品、票务，不能说订购高地。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”是把东西卖掉，与先……再往前走的行军意图矛盾。"}, {"text": "讲解", "is_correct": false, "explanation": "搭配：“讲解”的对象是课文、知识，不能说讲解高地。"}], "explanations": {"占领": "正确：“占领”与“先……再往前走”的行军语境相符，指先取得高地。", "订购": "搭配：“订购”的对象是商品、票务，不能说订购高地。", "出售": "语义：“出售”是把东西卖掉，与先……再往前走的行军意图矛盾。", "讲解": "搭配：“讲解”的对象是课文、知识，不能说讲解高地。"}, "sentence_index": 6, "correct_answer": "占领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们占领了那杯水。", "explanation": "这里应该用〈喝〉。占领只用于地方、据点，不用于饮品；喝水要用“喝”。"}, {"text": "猫占领了那只老鼠。", "explanation": "这里应该用〈吃掉〉。动物吃东西要用吃掉，占领不能用于猎物。"}, {"text": "医生占领了那个病人。", "explanation": "这里应该用〈治疗〉。病人要用治疗；占领只用于地方、据点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敌人占领了着那座小城。", "corrected_sentence": "敌人占领着那座小城。", "error_description": "错误在于“占领”后多加了“了”，与表持续的“着”同用；“了”和“着”不能同时附在同一动词上。应为“占领着那座小城”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "军队把那座城占领。", "corrected_sentence": "军队把那座城占领了。", "error_description": "错误在于“把”字句中动词“占领”后缺少“了”等成分，句子不完整；应为“把那座城占领了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
