INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87498, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用武力取得并控制某地。", "primary_collocate": null, "pronunciation": "zhàn lǐng", "ipa": "ʈʂan˥˩ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个国家曾经占领过邻国的大片土地。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队占领那里以后，派人看守着城门。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们很快占领了岛上的基地。", "target_word": "占领", "complexity_tier": "T3", "furigana": "tā men hěn kuài zhàn lǐng le dǎo shàng de jī dì", "sentence_source": "generated"}, {"text": "战争中，两国都想占领这块地方。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌军占领了城东的工厂。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们占领了这个地区，不让当地人出入。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队占领山口后，马上修了工事。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上有很多国家想占领这座古城。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵占领了电台，向全国发出通知。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们占领了整个海岛，还在岛上升起了旗。", "target_word": "占领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占领了", "label": "完成体"}, {"form": "占领过", "label": "经历体"}, {"form": "占领军", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用武力取得并控制某地：占领岛屿、地区、古城", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78bd22d5-58b2-46ac-bd58-f8a4351aa496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占领", "is_correct": true, "explanation": "正确：“占领过”指曾经用武力取得并控制邻国的土地，与句意相符。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”是创造新事物，不能用于已经存在的土地。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的对象是活动、比赛，不能说参加土地。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于物品、房间，不能说装饰土地。"}], "explanations": {"占领": "正确：“占领过”指曾经用武力取得并控制邻国的土地，与句意相符。", "发明": "语义：“发明”是创造新事物，不能用于已经存在的土地。", "参加": "搭配：“参加”的对象是活动、比赛，不能说参加土地。", "装饰": "搭配：“装饰”用于物品、房间，不能说装饰土地。"}, "sentence_index": 0, "correct_answer": "占领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们占领了一条新路。", "explanation": "这里应该用〈开辟〉。占领指用武力取得并控制某地，新路是开出来的，要用开辟。"}, {"text": "会计占领了数据。", "explanation": "这里应该用〈统计〉。数据要用统计，占领只用于地方或据点。"}, {"text": "老师占领了任务。", "explanation": "这里应该用〈分配〉。任务要分配，占领不能用于抽象的任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占领", "is_correct": true, "explanation": "正确：“占领山口后”指部队取得并控制山口，之后才修工事，语境相符。"}, {"text": "开放", "is_correct": false, "explanation": "语义：“开放”是让人进入，与部队修筑工事的意图相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”的对象是人，不能说嘲笑山口。"}, {"text": "迎接", "is_correct": false, "explanation": "搭配：“迎接”的对象是人或来客，不能说迎接山口。"}], "explanations": {"占领": "正确：“占领山口后”指部队取得并控制山口，之后才修工事，语境相符。", "开放": "语义：“开放”是让人进入，与部队修筑工事的意图相反。", "嘲笑": "搭配：“嘲笑”的对象是人，不能说嘲笑山口。", "迎接": "搭配：“迎接”的对象是人或来客，不能说迎接山口。"}, "sentence_index": 6, "correct_answer": "占领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们占领了那笔资金。", "explanation": "这里应该用〈转移〉。资金要转移，占领指取得并控制某地，不用于资金。"}, {"text": "消防队员占领了被困的人。", "explanation": "这里应该用〈救援〉。被困的人要救援，占领不能用于人。"}, {"text": "仓库占领了那批粮食。", "explanation": "这里应该用〈储存〉。粮食要储存，占领指用武力取得并控制某地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们占领着过一座岛。", "corrected_sentence": "他们占领过一座岛。", "error_description": "错误在于“占领着过”同时用了表持续的“着”和表经历的“过”，两者不能并用；应为“占领过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵把海岛占领，马上升起了旗。", "corrected_sentence": "士兵把海岛占领了，马上升起了旗。", "error_description": "错误在于“把”字句中动词“占领”后缺少“了”等成分，句子不完整；应为“把海岛占领了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
