INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87503, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "保险是先交一点钱，以后出了事，会有人帮你出钱。", "primary_collocate": null, "pronunciation": "bǎo xiǎn", "ipa": "pɑʊ˨˩˦ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我先交一点钱买保险，出事就有人帮我。", "target_word": "保险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我们全家都买了保险。", "target_word": "保险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买保险就是先交钱，以后有事别人出钱。", "target_word": "保险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸骑摩托车，所以买了保险。", "target_word": "保险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有保险，生病时就不怕没钱。", "target_word": "保险", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每个月都要花一百块钱买保险。", "target_word": "保险", "complexity_tier": "T3", "furigana": "tā měi gè yuè dōu yào huā yì bǎi kuài qián mǎi bǎo xiǎn", "sentence_source": "generated"}, {"text": "孩子上学前，我给他买了保险。", "target_word": "保险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友劝我买点保险。", "target_word": "保险", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "有保险的话，修车不用自己付钱。", "target_word": "保险", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李出了事，保险帮他付了医药费。", "target_word": "保险", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份保险", "label": "量词"}, {"form": "一种保险", "label": "量词"}, {"form": "保险费", "label": "复合词"}, {"form": "保险公司", "label": "复合词"}, {"form": "保險", "label": "繁体"}], "register": "中性", "sense_fingerprint": "先交钱，以后出事有人出钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c54d57b-fa77-4f5f-88d9-3e9f8f091722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87503, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保险", "is_correct": true, "explanation": "“保险”指先交钱、出事后由别人赔付的制度，与“先交一点钱”“出事就有人帮我”相符。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是食物，与“出事就有人帮我”毫无关系，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：天气是自然现象，不能说“买”，与“先交一点钱”不搭。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“买作业”指花钱求答案，与保险无关，与“出事就有人帮我”不符，句子不成立。"}], "explanations": {"保险": "“保险”指先交钱、出事后由别人赔付的制度，与“先交一点钱”“出事就有人帮我”相符。", "午饭": "语义：午饭是食物，与“出事就有人帮我”毫无关系，句子不成立。", "天气": "搭配：天气是自然现象，不能说“买”，与“先交一点钱”不搭。", "作业": "语义：“买作业”指花钱求答案，与保险无关，与“出事就有人帮我”不符，句子不成立。"}, "sentence_index": 0, "correct_answer": "保险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一把保险。", "explanation": "量词用错：〈把〉用于有柄的器具，保险应用〈份〉或〈种〉。"}, {"text": "这个规定能保险孩子的安全。", "explanation": "这里应该用〈保障〉：保障安全说“保障”；“保险”作动词只用于投保，不说“保险安全”。"}, {"text": "这些文件请你保险好，别丢了。", "explanation": "这里应该用〈保管〉：收好、妥善保存说“保管”；“保险”作动词只用于投保，不表示保管。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保险", "is_correct": true, "explanation": "“保险”指为孩子购买的保障，与“上学前，我给他买了”搭配，符合语境。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不能用“买”，与“给他买了”不搭。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：合同是签订的，一般不说“买”，与语境不合。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气，不能买给孩子，与“上学前”的语境不合。"}], "explanations": {"保险": "“保险”指为孩子购买的保障，与“上学前，我给他买了”搭配，符合语境。", "空气": "搭配：空气不能用“买”，与“给他买了”不搭。", "合同": "搭配：合同是签订的，一般不说“买”，与语境不合。", "雨": "语义：雨是天气，不能买给孩子，与“上学前”的语境不合。"}, "sentence_index": 6, "correct_answer": "保险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天早上都把保险穿在身上，然后出门了。", "explanation": "这里应该用〈衣服〉：穿在身上的是衣服；保险是保险公司收费赔偿的合同，不能“穿”。"}, {"text": "他每天早上都把保险吃下去，然后去上班。", "explanation": "这里应该用〈早饭〉：能吃的是食物；保险是保险公司提供的合同，不能吃。"}, {"text": "他每天在家里给保险浇水，希望它长大。", "explanation": "这里应该用〈植物〉：能浇水的是植物；保险是保险公司收费赔偿的合同，不能“浇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今年给爸爸买了一把保险。", "corrected_sentence": "我今年给爸爸买了一份保险。", "error_description": "量词错误：“保险”应用量词“份”，“把”用于有柄的器具，不能修饰“保险”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈上个月给老人办了一份的保险。", "corrected_sentence": "妈妈上个月给老人办了一份保险。", "error_description": "结构错误：“一份”后不能加“的”再接名词，应说“一份保险”，“的”是多余成分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
