INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "收藏、陈列和研究历史文物、艺术品、标本等的机构或场所。", "primary_collocate": null, "pronunciation": "bó wù guǎn", "ipa": "pwo˧˥ u˥˩ kwan˨˩˦", "syllable_count": 3, "sentences": [{"text": "这家博物馆收藏了很多历史文物。", "target_word": "博物馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里陈列着许多艺术品。", "target_word": "博物馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在博物馆研究古代文物。", "target_word": "博物馆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座博物馆的动物标本很有名。", "target_word": "博物馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里新建了一座博物馆。", "target_word": "博物馆", "complexity_tier": "T3", "furigana": "shì lǐ xīn jiàn le yí zuò bó wù guǎn", "sentence_source": "generated"}, {"text": "博物馆把这件文物放在最中间。", "target_word": "博物馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆今年展出了一批新的艺术品。", "target_word": "博物馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在博物馆工作，每天研究文物。", "target_word": "博物馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博物馆的标本是从山里找来的。", "target_word": "博物馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去博物馆看展览。", "target_word": "博物馆", "complexity_tier": "T3", "furigana": "lǎo shī dài wǒ men qù bó wù guǎn kàn zhǎn lǎn", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座博物馆", "label": "量词"}, {"form": "一家博物馆", "label": "量词"}, {"form": "博物館", "label": "繁体"}], "register": "中性", "sense_fingerprint": "收藏陈列研究文物艺术品标本的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbe6c0-1a36-4377-a066-54ce1f0a44eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "博物馆", "is_correct": true, "explanation": "正确。“收藏了很多历史文物”需要收藏文物的机构，博物馆符合。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆是做饭卖饭的地方，不收藏历史文物。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店提供理发服务，与收藏文物毫无关系。"}, {"text": "加油站", "is_correct": false, "explanation": "搭配：“收藏”的对象是文物，不说“加油站收藏文物”。"}], "explanations": {"博物馆": "正确。“收藏了很多历史文物”需要收藏文物的机构，博物馆符合。", "饭馆": "语义：饭馆是做饭卖饭的地方，不收藏历史文物。", "理发店": "语义：理发店提供理发服务，与收藏文物毫无关系。", "加油站": "搭配：“收藏”的对象是文物，不说“加油站收藏文物”。"}, "sentence_index": 0, "correct_answer": "博物馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座博物馆可以借书。", "explanation": "这里应该用〈图书馆〉。博物馆收藏陈列文物，不外借图书，借书要去图书馆。"}, {"text": "这座博物馆每天都要给小猴子喂香蕉。", "explanation": "这里应该用〈动物园〉。博物馆陈列文物和标本，不饲养活动物，喂小猴子要去动物园。"}, {"text": "这座博物馆每天有很多人打篮球。", "explanation": "这里应该用〈体育馆〉。博物馆是陈列收藏的地方，打篮球要去体育馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "博物馆", "is_correct": true, "explanation": "正确。“展出一批艺术品”需要陈列作品的场所，博物馆符合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不会展出艺术品。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：停车场用来停车，不展出艺术品。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“展出”的主语应是场所或机构，“面包”不搭配。"}], "explanations": {"博物馆": "正确。“展出一批艺术品”需要陈列作品的场所，博物馆符合。", "厨房": "语义：厨房是做饭的地方，不会展出艺术品。", "停车场": "语义：停车场用来停车，不展出艺术品。", "面包": "搭配：“展出”的主语应是场所或机构，“面包”不搭配。"}, "sentence_index": 6, "correct_answer": "博物馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被判了三年，要去博物馆服刑。", "explanation": "这里应该用〈监狱〉。服刑要在监狱，博物馆是收藏研究文物的机构，不关押人。"}, {"text": "傍晚我去博物馆游泳。", "explanation": "这里应该用〈游泳馆〉。博物馆不是游泳的地方，游泳要去游泳馆。"}, {"text": "我下午带孩子去博物馆打疫苗。", "explanation": "这里应该用〈医院〉。博物馆收藏研究文物，不提供诊疗，打疫苗要去医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只博物馆陈列着古代的陶器。", "corrected_sentence": "这座博物馆陈列着古代的陶器。", "error_description": "量词错误：指“博物馆”这种大型建筑，应该用“座”，不能用“只”。“只”多用于动物或小件物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天博物馆研究文物。", "corrected_sentence": "她每天在博物馆研究文物。", "error_description": "介词错误：表示地点的“在”漏掉了，应说“在博物馆研究文物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4410e564-bdc3-4914-a506-44d47667caf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
