INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87521, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "abstract", "definition": "月月是每一个月，一个月也不少。", "primary_collocate": null, "pronunciation": "yuè yuè", "ipa": "ɥɛ˥˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他月月给家里寄钱。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我月月都去看奶奶。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她月月都买新书。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸月月按时交房租。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杂志月月都有新的一期。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班月月开一次会。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她月月都会去医院检查身体。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他月月把工资的一半存起来。", "target_word": "月月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我月月都去图书馆借三本书。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司月月发工资，从来没有晚过。", "target_word": "月月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "月月·每个月·一个月也不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a05bf854-5e1e-422d-a553-c991fceb6ea9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月月", "is_correct": true, "explanation": "月月表示每个月，符合“每个月都寄钱”的句意。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”不能单独表示“每个月”的重复，“他星期给家里寄钱”不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能表示寄钱的时间，句子不通。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生指人，不能作寄钱的时间状语，句意不通。"}], "explanations": {"月月": "月月表示每个月，符合“每个月都寄钱”的句意。", "星期": "搭配：“星期”不能单独表示“每个月”的重复，“他星期给家里寄钱”不通。", "月亮": "语义：月亮是天体，不能表示寄钱的时间，句子不通。", "学生": "语义：学生指人，不能作寄钱的时间状语，句意不通。"}, "sentence_index": 0, "correct_answer": "月月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天月月去看了奶奶。", "explanation": "这里月月误作〈某一天〉的意思。月月表示“每个月”的反复，不能用于只发生在某一天的事。"}, {"text": "她月月出生了。", "explanation": "这里月月误作〈只发生一次〉的意思。月月表示“每个月”的反复，不能用于出生这种只发生一次的事。"}, {"text": "我们公司月月开了一次创立大会。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用于创立大会这种一次性的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
