INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87522, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "abstract", "definition": "每个月；逐月。", "primary_collocate": null, "pronunciation": "yuè yuè", "ipa": "ɥɛ˥˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他的成绩月月都在进步。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的客人月月增加。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的体重月月都在下降。", "target_word": "月月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子月月长高，衣服都小了。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的房价月月上涨。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的收入月月都比上个月多。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小树月月都在长大，现在已经很高了。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语水平月月提高，老师很满意。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的游客月月变多，生意越来越好。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的存款月月变多，他心里很高兴。", "target_word": "月月", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "月月·逐月·逐月变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a05bf854-5e1e-422d-a553-c991fceb6ea9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, 