INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月月", "is_correct": true, "explanation": "月月表示每个月，与“都”搭配，说小树逐月长大，符合句意。"}, {"text": "院子", "is_correct": false, "explanation": "语义：院子是场所，不会“长大”，与主语“小树”不能组合，句子不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的东西，不会长大，句子不通。"}, {"text": "日子", "is_correct": false, "explanation": "搭配：“日子”指日期或生活，不能与“在长大”搭配作主语，句意不通。"}], "explanations": {"月月": "月月表示每个月，与“都”搭配，说小树逐月长大，符合句意。", "院子": "语义：院子是场所，不会“长大”，与主语“小树”不能组合，句子不通。", "石头": "语义：石头是无生命的东西，不会长大，句子不通。", "日子": "搭配：“日子”指日期或生活，不能与“在长大”搭配作主语，句意不通。"}, "sentence_index": 6, "correct_answer": "月月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我月月考上了大学。", "explanation": "这里月月误作〈只发生一次〉的意思。月月表示“每个月”的反复，不能用于考上大学这种只发生一次的事。"}, {"text": "妈妈昨天月月给我打了电话。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用于只发生在某一天的事。"}, {"text": "我们班月月举办了一次毕业典礼。", "explanation": "这里月月误作〈某一次〉的意思。月月表示“每个月”的反复，不能用于毕业典礼这种一次性的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e5806-714e-4af5-9dbb-ff619f4a8273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
