INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小伙子是年轻又有力气的男子。", "primary_collocate": null, "pronunciation": "xiǎo huǒ zi", "ipa": "ɕiɑʊ˨˩ xuɔ˨˩ tsɨ", "syllable_count": 3, "sentences": [{"text": "那个小伙子力气很大，一个人搬了两张桌子。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小伙子扛着一袋米，走得很快。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小伙子又高又壮，大家都喜欢他。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个小伙子帮老人把车推上了山。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小伙子们在工地上干活，一点儿也不累。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁的小伙子每天早上都去跑步。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小伙子很有力气，一口气爬到山顶。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小伙子把重重的箱子搬上了三楼。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的小伙子都来帮忙收麦子。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个壮实的小伙子，干活从不喊累。", "target_word": "小伙子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小伙子们", "label": "复数"}, {"form": "小伙儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "年轻、强壮、有力气的男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3410f726-dd8b-4348-a976-24df9c72ab9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”是器物，没有力气，不能说“力气很大”。"}, {"text": "小伙子", "is_correct": true, "explanation": "正确。小伙子指年轻又有力气的男孩子，这里描写他力气大、能搬桌子。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：“一个人搬了两张桌子”要求人作施事，“小猫”不能与之搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有力气，不能作“力气很大”的主语。"}], "explanations": {"花瓶": "语义：“花瓶”是器物，没有力气，不能说“力气很大”。", "小伙子": "正确。小伙子指年轻又有力气的男孩子，这里描写他力气大、能搬桌子。", "小猫": "配价：“一个人搬了两张桌子”要求人作施事，“小猫”不能与之搭配。", "石头": "语义：“石头”没有力气，不能作“力气很大”的主语。"}, "sentence_index": 0, "correct_answer": "小伙子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的姐姐是个小伙子，很漂亮。", "explanation": "这里应该用〈姑娘〉。“小伙子”指年轻的男子，不能用于女性。"}, {"text": "我父亲是个中年小伙子，力气很大。", "explanation": "这里应该用〈男人〉。“小伙子”指年轻的男子，不能用来形容中年人。"}, {"text": "那位小伙子已经八十岁了，每天早上去公园。", "explanation": "这里应该用〈老人〉。“小伙子”指年轻的男子，不能用于八十岁的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：“书包”没有力气，不能说“很有力气”。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“一口气爬到山顶”要求能自己行动的人作施事，“冰箱”不能。"}, {"text": "石柱", "is_correct": false, "explanation": "语义：“石柱”是固定的物体，不能“一口气爬到山顶”。"}, {"text": "小伙子", "is_correct": true, "explanation": "正确。小伙子指年轻又有力气的男子，这里指这个有力气的年轻人。"}], "explanations": {"书包": "语义：“书包”没有力气，不能说“很有力气”。", "冰箱": "配价：“一口气爬到山顶”要求能自己行动的人作施事，“冰箱”不能。", "石柱": "语义：“石柱”是固定的物体，不能“一口气爬到山顶”。", "小伙子": "正确。小伙子指年轻又有力气的男子，这里指这个有力气的年轻人。"}, "sentence_index": 6, "correct_answer": "小伙子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那台电脑很能干，是个小伙子。", "explanation": "这里应该用〈机器〉，指物品。“小伙子”指年轻的男子，不能用于电脑这样的物品。"}, {"text": "那个小伙子才八岁，已经会自己游泳了。", "explanation": "这里应该用〈男孩〉。“小伙子”指年轻的男子，不能用于八岁的孩子。"}, {"text": "那个小伙子才十二岁，就能帮家里干活。", "explanation": "这里应该用〈少年〉。“小伙子”指年轻的男子，不能用于十二岁的少年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只结实的小伙子扛起了一袋米，很快就走远了。", "corrected_sentence": "一个结实的小伙子扛起了一袋米，很快就走远了。", "error_description": "“小伙子”指人，量词应用“个”，“只”多用于动物或成对的东西，这里用“只”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个小伙子的在河边钓鱼，玩得很开心。", "corrected_sentence": "几个小伙子在河边钓鱼，玩得很开心。", "error_description": "“小伙子”后面直接加“的”，接动词短语作主语，句子不通；应去掉“的”，说“几个小伙子在河边钓鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
