INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87536, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示在任何条件下，结果都不会改变。", "primary_collocate": null, "pronunciation": "wú lùn", "ipa": "u˧˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "无论天气怎么样，我都去跑步。", "target_word": "无论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无论多忙，他都会给妈妈打电话。", "target_word": "无论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无论你去哪儿，我都跟你去。", "target_word": "无论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无论大人还是孩子，都喜欢这部电影。", "target_word": "无论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无论价格多高，他都要买。", "target_word": "无论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无论谁来问，你都别说。", "target_word": "无论", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "无论多难，我们也不放弃。", "target_word": "无论", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "无论是春天还是秋天，这里都很美。", "target_word": "无论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无论你喜欢不喜欢，这件事都要做。", "target_word": "无论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无论他怎么解释，大家都不相信。", "target_word": "无论", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "无论如何", "label": "固定短语"}, {"form": "无论是", "label": "常用搭配"}], "register": "书面", "sense_fingerprint": "连词，常与“都／也”搭配，表示条件不同而结果不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b19c0f9-466f-4374-8e4f-5a9190f00083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无论", "is_correct": true, "explanation": "“无论”引出条件，后接“都”表示结果不变，与句意相符。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，“天气怎么样”是不定的条件，不能作原因。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但/却/还是”呼应，此句没有转折词，前后不构成让步关系。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“天气怎么样”不是前面的结果。"}], "explanations": {"无论": "“无论”引出条件，后接“都”表示结果不变，与句意相符。", "因为": "语义：“因为”引出原因，“天气怎么样”是不定的条件，不能作原因。", "虽然": "搭配：“虽然”要与“但/却/还是”呼应，此句没有转折词，前后不构成让步关系。", "所以": "语义：“所以”表示结果，“天气怎么样”不是前面的结果。"}, "sentence_index": 0, "correct_answer": "无论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "无论昨天下了雨，我们还是去了公园。", "explanation": "这里应该用〈虽然〉。虽然用于已经发生的事实；无论用于尚未确定的条件，说已经发生的雨时不能用无论。"}, {"text": "无论你同意，我们就去。", "explanation": "这里应该用〈如果〉。如果引出假设条件，后面常接“就”；无论强调在各种条件下结果都不变，要与“都/也”呼应，不能用来表示一个假设。"}, {"text": "无论她会唱歌，就会有人请她。", "explanation": "这里应该用〈只要〉。只要表示只需一个条件就够了，后面接“就”；无论强调在任何条件下结果都不变，不能表示条件充分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无论", "is_correct": true, "explanation": "“无论”引出条件，后面“也不放弃”表示结果不变，与句意相符。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出结果，“多难”不是前面的结果，句子语义不通。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示接着发生的结果，“多难”不能引出“不放弃”这一结果。"}, {"text": "或者", "is_correct": false, "explanation": "搭配：“或者”连接两个选项，后面需要并列的选择，不能只接一个条件。"}], "explanations": {"无论": "“无论”引出条件，后面“也不放弃”表示结果不变，与句意相符。", "因此": "语义：“因此”引出结果，“多难”不是前面的结果，句子语义不通。", "于是": "语义：“于是”表示接着发生的结果，“多难”不能引出“不放弃”这一结果。", "或者": "搭配：“或者”连接两个选项，后面需要并列的选择，不能只接一个条件。"}, "sentence_index": 6, "correct_answer": "无论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "无论他没带钥匙，所以进不了门。", "explanation": "这里应该用〈因为〉。因为引出已经发生的原因；无论表示在各种条件下结果都不变，不能用来解释“进不了门”的原因。"}, {"text": "无论努力，才能成功。", "explanation": "这里应该用〈只有〉。只有…才…表示唯一的条件；无论表示任何条件下结果都不变，不能与“才”搭配。"}, {"text": "无论锻炼身体，他每天跑步。", "explanation": "这里应该用〈为了〉。为了引出目的；无论引出的是条件，不能用来说明他跑步的目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "无论路多远，我们会都准时到达。", "corrected_sentence": "无论路多远，我们都会准时到达。", "error_description": "“都”应紧跟主语“我们”，放在“会”之前，应说“我们都会准时到达”，“会都”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "无论怎么，我们都要完成这个任务。", "corrected_sentence": "无论如何，我们都要完成这个任务。", "error_description": "“无论怎么”后缺少成分，不能单独成句；可改为固定短语“无论如何”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
