INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87543, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用数字数一数，看看有多少。", "primary_collocate": null, "pronunciation": "suàn", "ipa": "swan˥˩", "syllable_count": 1, "sentences": [{"text": "你算一算，这里有多少人？", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我算了算，一共有三十本书。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在算今天买菜花了多少钱。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你算一下我们要买几个杯子。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个一个地算羊有多少只。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先算算这个月还剩多少钱。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你算对了，答案是四十。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数学课上，我们学习怎么算加法。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟不会算，要问姐姐。", "target_word": "算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们算一算教室里有几张桌子。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "算算", "label": "重叠"}, {"form": "算了", "label": "体标（了）"}, {"form": "算过", "label": "体标（过）"}, {"form": "计算", "label": "复合词"}], "register": "中性", "sense_fingerprint": "动词，指用数字数一数、算一算，弄清数量多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b19c0f9-466f-4374-8e4f-5a9190f00083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87543, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "算", "is_correct": true, "explanation": "正确答案：算，指用数字数一数、算一算。"}, {"text": "酸", "is_correct": false, "explanation": "suān（第一声）与 suàn（第四声）声调不同，意思是酸味。"}, {"text": "散", "is_correct": false, "explanation": "sàn 比 suàn 少了介音 u，意思是分散。"}, {"text": "窜", "is_correct": false, "explanation": "cuàn 与 suàn 声母不同（c 与 s），意思是逃窜。"}], "explanations": {"算": "正确答案：算，指用数字数一数、算一算。", "酸": "suān（第一声）与 suàn（第四声）声调不同，意思是酸味。", "散": "sàn 比 suàn 少了介音 u，意思是分散。", "窜": "cuàn 与 suàn 声母不同（c 与 s），意思是逃窜。"}, "sentence_index": null, "correct_answer": "算"}, "level_3": {"options": [{"text": "算", "is_correct": true, "explanation": "正确：“算一算”表示数数，与“有多少人”的问句相符。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买一算”不通，句子问的是人数。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送一送”不表示数人数，与“有多少人”无关。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗，与数人数无关。"}], "explanations": {"算": "正确：“算一算”表示数数，与“有多少人”的问句相符。", "买": "搭配：“买一算”不通，句子问的是人数。", "送": "语义：“送一送”不表示数人数，与“有多少人”无关。", "洗": "语义：“洗”是清洗，与数人数无关。"}, "sentence_index": 0, "correct_answer": "算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你算一下杯子有没有坏。", "explanation": "这里应该用〈检查〉。“算”指数数目，不能用来查看杯子是否损坏。"}, {"text": "请你算一下杯子的颜色。", "explanation": "这里应该用〈挑〉。“算”指数数目，颜色不能计数，挑颜色要用“挑”。"}, {"text": "请你算一下这些杯子漂不漂亮。", "explanation": "这里应该用〈看〉。“算”指计数，不能用来判断杯子是否漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87543, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "算", "is_correct": true, "explanation": "正确答案：算，指用数字数一数、算一算。"}, {"text": "钻", "is_correct": false, "explanation": "zuàn 与 suàn 声母不同（z 与 s），意思是钻头、钻研。"}, {"text": "炫", "is_correct": false, "explanation": "xuàn 与 suàn 声母不同（x 与 s），意思是炫耀。"}, {"text": "涮", "is_correct": false, "explanation": "shuàn 与 suàn 声母不同（sh 与 s），意思是在汤里来回烫。"}], "explanations": {"算": "正确答案：算，指用数字数一数、算一算。", "钻": "zuàn 与 suàn 声母不同（z 与 s），意思是钻头、钻研。", "炫": "xuàn 与 suàn 声母不同（x 与 s），意思是炫耀。", "涮": "shuàn 与 suàn 声母不同（sh 与 s），意思是在汤里来回烫。"}, "sentence_index": null, "correct_answer": "算"}, "level_3": {"options": [{"text": "算", "is_correct": true, "explanation": "正确：“算对了”表示计算正确，与“答案是四十”相符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是物体表面，不能说“擦对了，答案是四十”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掷，与答题正确与否无关。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要接可以吃的东西，不能带“答案是四十”作宾语。"}], "explanations": {"算": "正确：“算对了”表示计算正确，与“答案是四十”相符。", "擦": "搭配：“擦”的对象是物体表面，不能说“擦对了，答案是四十”。", "扔": "语义：“扔”是抛掷，与答题正确与否无关。", "吃": "配价：“吃”要接可以吃的东西，不能带“答案是四十”作宾语。"}, "sentence_index": 6, "correct_answer": "算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让我们算一算教室的温度高不高。", "explanation": "这里应该用〈测〉。“算”指计数，测温度要用“测”。"}, {"text": "老师让我们算一算同学们开心不开心。", "explanation": "这里应该用〈猜〉。“算”指计数，同学的心情不能数，要用“猜”。"}, {"text": "老师让我们算一算这节课好不好。", "explanation": "这里应该用〈评价〉。“算”指计数，课的好坏不能数，要用“评价”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我完算了这些书。", "corrected_sentence": "我算完了这些书。", "error_description": "结果补语“完”位置错误：应说“算完”，“完”要紧跟在动词后，不说“完算”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
