INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87544, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "计算；核算；也指当作、认作。", "primary_collocate": null, "pronunciation": "suàn", "ipa": "swan˥˩", "syllable_count": 1, "sentences": [{"text": "我来算一下这个月花了多少钱。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把这笔钱算清楚。", "target_word": "算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算得很快，一下就知道答案。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个数你再算一遍看看。", "target_word": "算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次小测验不算成绩，别紧张。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在我们家住了三年，算一家人了。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这点小事不算什么。", "target_word": "算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天二十度，不算冷。", "target_word": "算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板正在算这个月的工资。", "target_word": "算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一共五个人，把你算进去。", "target_word": "算", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "算了", "label": "体标（了）"}, {"form": "算过", "label": "体标（过）"}, {"form": "算是", "label": "复合词"}, {"form": "计算", "label": "复合词"}], "register": "中性", "sense_fingerprint": "动词，指核算金额数量，或把某人某事当作、认作某种情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b19c0f9-466f-4374-8e4f-5a9190f00083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87544, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "算", "is_correct": true, "explanation": "正确答案：算，指用数字计算或核算。"}, {"text": "酸", "is_correct": false, "explanation": "suān（第一声）与 suàn（第四声）声调不同，意思是酸味。"}, {"text": "散", "is_correct": false, "explanation": "sàn 比 suàn 少了介音 u，意思是分散。"}, {"text": "窜", "is_correct": false, "explanation": "cuàn 与 suàn 声母不同（c 与 s），意思是逃窜。"}], "explanations": {"算": "正确答案：算，指用数字计算或核算。", "酸": "suān（第一声）与 suàn（第四声）声调不同，意思是酸味。", "散": "sàn 比 suàn 少了介音 u，意思是分散。", "窜": "cuàn 与 suàn 声母不同（c 与 s），意思是逃窜。"}, "sentence_index": null, "correct_answer": "算"}, "level_3": {"options": [{"text": "算", "is_correct": true, "explanation": "正确：“算一下”表示核算金额，与“花了多少钱”的语境相符。"}, {"text": "赚", "is_correct": false, "explanation": "语义：“赚”是挣钱，句子问的是花了多少钱，不是挣了多少。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”要接可买的东西，不能接“这个月花了多少钱”这样的小句。"}, {"text": "借", "is_correct": false, "explanation": "配价：“借”要接可借的物品，不能接表示花费的小句。"}], "explanations": {"算": "正确：“算一下”表示核算金额，与“花了多少钱”的语境相符。", "赚": "语义：“赚”是挣钱，句子问的是花了多少钱，不是挣了多少。", "买": "配价：“买”要接可买的东西，不能接“这个月花了多少钱”这样的小句。", "借": "配价：“借”要接可借的物品，不能接表示花费的小句。"}, "sentence_index": 0, "correct_answer": "算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我来算一下明天的天气。", "explanation": "这里应该用〈查〉。“算”指计算数目或金额，天气不能计算，要说“查”。"}, {"text": "他把这块布算了一下颜色。", "explanation": "这里应该用〈看〉。“算”指计算数目，颜色不能计算，要说“看”。"}, {"text": "他算了一场电影。", "explanation": "这里应该用〈看〉。“算”指计算数目，不能用来说看电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87544, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "算", "is_correct": true, "explanation": "正确答案：算，指当作、认作或计入。"}, {"text": "钻", "is_correct": false, "explanation": "zuàn 与 suàn 声母不同（z 与 s），意思是钻头、钻研。"}, {"text": "炫", "is_correct": false, "explanation": "xuàn 与 suàn 声母不同（x 与 s），意思是炫耀。"}, {"text": "涮", "is_correct": false, "explanation": "shuàn 与 suàn 声母不同（sh 与 s），意思是在汤里来回烫。"}], "explanations": {"算": "正确答案：算，指当作、认作或计入。", "钻": "zuàn 与 suàn 声母不同（z 与 s），意思是钻头、钻研。", "炫": "xuàn 与 suàn 声母不同（x 与 s），意思是炫耀。", "涮": "shuàn 与 suàn 声母不同（sh 与 s），意思是在汤里来回烫。"}, "sentence_index": null, "correct_answer": "算"}, "level_3": {"options": [{"text": "算", "is_correct": true, "explanation": "正确：“不算什么”表示不被看作重要的事，与句意相符。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：“抱”不能与“什么”组成表示“不被看作”的说法。"}, {"text": "认", "is_correct": false, "explanation": "配价：“认”要接人或字作宾语，不能接“什么”表示认定。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”与“小事”搭配不当，句意不通。"}], "explanations": {"算": "正确：“不算什么”表示不被看作重要的事，与句意相符。", "抱": "搭配：“抱”不能与“什么”组成表示“不被看作”的说法。", "认": "配价：“认”要接人或字作宾语，不能接“什么”表示认定。", "吃": "搭配：“吃”与“小事”搭配不当，句意不通。"}, "sentence_index": 6, "correct_answer": "算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的话从来不算数。", "explanation": "这里是“算数”的意思，指话或规定有效、作数，不是“计算”或“认作”义。"}, {"text": "这笔账我以后再跟你算。", "explanation": "这里是“算账、清算、计较”的意思，不是“计算”义。"}, {"text": "他总想算计我。", "explanation": "这里是“算计、暗中谋害”的意思，不是“计算”义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我算清晰了这笔账。", "corrected_sentence": "我算清楚了这笔账。", "error_description": "结果补语应为“清楚”，表示算得明白；“清晰”形容图像、思路等明晰，不能用来修饰计算结果，应说“算清楚了”，不说“算清晰了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他算了出三百块的总数。", "corrected_sentence": "他算出了三百块的总数。", "error_description": "结果补语“出”位置错误：应说“算出”，“了”要放在“出”后，不说“算了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
