INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87545, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大只是说人或动物个子很大，身体很壮。", "primary_collocate": null, "pronunciation": "dà zhī", "ipa": "ta˥˩ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他很大只，一个人能搬两箱水。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个大只的男生是我们的篮球队员。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟比同学大只，穿衣服要大号。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条狗太大只了，家里放不下。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天去健身房，所以变大只了。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫很大只，抱起来很重。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很大只，其实很温柔。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买件衣服给大只的爸爸。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些大只的运动员站在门口。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很大只，大家都不敢跟他吵架。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大隻", "label": "繁体"}], "register": "口语", "sense_fingerprint": "形容人或动物个子大、身体壮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00e5633-a762-4029-b384-af5ebcd7e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87545, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大只", "is_correct": true, "explanation": "大只（dà zhī，第四声＋第一声）是正确答案，指人或动物个子大、身体壮。"}, {"text": "大志", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是远大的志向。"}, {"text": "大纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是大张的纸。"}, {"text": "大值", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是数值较大。"}], "explanations": {"大只": "大只（dà zhī，第四声＋第一声）是正确答案，指人或动物个子大、身体壮。", "大志": "zhì（第四声）与 zhī（第一声）声调不同，意思是远大的志向。", "大纸": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是大张的纸。", "大值": "zhí（第二声）与 zhī（第一声）声调不同，意思是数值较大。"}, "sentence_index": null, "correct_answer": "大只"}, "level_3": {"options": [{"text": "大只", "is_correct": true, "explanation": "“大只”指个子大、身体壮，符合“一个人能搬两箱水”的语境。"}, {"text": "虚弱", "is_correct": false, "explanation": "语义：“虚弱”指身体没有力气，与“一个人能搬两箱水”矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”指个子低、身材小，与“大只”的身材义相反。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”指身材瘦、个子小，与“大只”的身材义相反。"}], "explanations": {"大只": "“大只”指个子大、身体壮，符合“一个人能搬两箱水”的语境。", "虚弱": "语义：“虚弱”指身体没有力气，与“一个人能搬两箱水”矛盾。", "矮小": "体貌：“矮小”指个子低、身材小，与“大只”的身材义相反。", "瘦小": "体貌：“瘦小”指身材瘦、个子小，与“大只”的身材义相反。"}, "sentence_index": 0, "correct_answer": "大只"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那棵树很大只，要两个人才能抱住。", "explanation": "这里应该用〈高大〉。大只只用于人或动物的身材，形容树木要用“高大”。"}, {"text": "这个房间很大只，能放十张床。", "explanation": "这里应该用〈宽敞〉。大只只说人或动物，不用来形容房间。"}, {"text": "他的声音很大只，全班都听得见。", "explanation": "这里应该用〈洪亮〉。大只说身体的大小和壮实，不说声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87545, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大只", "is_correct": true, "explanation": "大只（dà zhī，第四声＋第一声）是正确答案，指人或动物个子大、身体壮。"}, {"text": "大致", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是大体、大概。"}, {"text": "大值", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是数值较大。"}, {"text": "大指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是大拇指。"}], "explanations": {"大只": "大只（dà zhī，第四声＋第一声）是正确答案，指人或动物个子大、身体壮。", "大致": "zhì（第四声）与 zhī（第一声）声调不同，意思是大体、大概。", "大值": "zhí（第二声）与 zhī（第一声）声调不同，意思是数值较大。", "大指": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是大拇指。"}, "sentence_index": null, "correct_answer": "大只"}, "level_3": {"options": [{"text": "大只", "is_correct": true, "explanation": "“大只”指身材高大壮实，与“看起来很”的外形描述相符。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”指能透过光，不能用来形容人的外形。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指含水分多，不能用来形容人的外形。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”多用于刀、剑，不能用来形容人看起来的样子。"}], "explanations": {"大只": "“大只”指身材高大壮实，与“看起来很”的外形描述相符。", "透明": "语义：“透明”指能透过光，不能用来形容人的外形。", "潮湿": "语义：“潮湿”指含水分多，不能用来形容人的外形。", "锋利": "搭配：“锋利”多用于刀、剑，不能用来形容人看起来的样子。"}, "sentence_index": 6, "correct_answer": "大只"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山很大只，走起来很累。", "explanation": "这里应该用〈雄伟〉。大只只用于人或动物的身材，形容山要用“雄伟”。"}, {"text": "他的成绩很大只，老师很满意。", "explanation": "这里应该用〈优秀〉。大只只说身材，不说成绩。"}, {"text": "这顿饭很大只，大家吃得很饱。", "explanation": "这里应该用〈丰盛〉。大只只形容人或动物，不用来形容饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她长很大只，大家都让着她。", "corrected_sentence": "她长得很大只，大家都让着她。", "error_description": "补语结构漏了“得”：程度补语要用“长得……”连接，应说“她长得很大只”，不能说“她长很大只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个大只地运动员。", "corrected_sentence": "他是一个大只的运动员。", "error_description": "“的”用于形容词修饰名词：大只的运动员；“地”用于修饰动词，这里用错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
