INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87546, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（方言）形容人或动物身材高大壮实。", "primary_collocate": null, "pronunciation": "dà zhī", "ipa": "ta˥˩ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他是我们村最大只的人。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头牛真大只，比别的牛都壮。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时很瘦，现在变得很大只。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大只的男人站在门口。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗大只得像一头小牛。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友个个都很大只。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们家孩子真大只，几岁了？", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不高，但是很大只。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大只的人吃得也多。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸡长得很大只，肉也多。", "target_word": "大只", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大隻", "label": "繁体"}], "register": "方言", "sense_fingerprint": "方言：人或动物身材高大壮实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00e5633-a762-4029-b384-af5ebcd7e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
