INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87560, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设立", "is_correct": true, "explanation": "正确。设立指新建奖学金、制度等，读 shè lì。"}, {"text": "树立", "is_correct": false, "explanation": "shù（第四声）与 shè 韵母不同（u 与 e），意思是树立，如“树立榜样”。"}, {"text": "竖立", "is_correct": false, "explanation": "shù 与 shè 韵母不同（u 与 e），意思是竖起来、直立。"}, {"text": "设计", "is_correct": false, "explanation": "jì 与 lì 声母不同（j 与 l），意思是设计、规划。"}], "explanations": {"设立": "正确。设立指新建奖学金、制度等，读 shè lì。", "树立": "shù（第四声）与 shè 韵母不同（u 与 e），意思是树立，如“树立榜样”。", "竖立": "shù 与 shè 韵母不同（u 与 e），意思是竖起来、直立。", "设计": "jì 与 lì 声母不同（j 与 l），意思是设计、规划。"}, "sentence_index": null, "correct_answer": "设立"}, "level_3": {"options": [{"text": "设立", "is_correct": true, "explanation": "正确。设立指新建奖学金，与句意相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与句中新设奖学金的意思相反。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬，不能用来指设置奖学金。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语应是衣物等，不能搭配“奖学金”。"}], "explanations": {"设立": "正确。设立指新建奖学金，与句意相符。", "扔": "语义：“扔”指丢弃，与句中新设奖学金的意思相反。", "咬": "语义：“咬”指用牙齿咬，不能用来指设置奖学金。", "洗": "搭配：“洗”的宾语应是衣物等，不能搭配“奖学金”。"}, "sentence_index": 0, "correct_answer": "设立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议设立了改革的方向。", "explanation": "这里应该用〈确立〉。设立指新建机构、奖项、制度，方向、目标要用〈确立〉。"}, {"text": "两国设立了友好的关系。", "explanation": "这里应该用〈形成〉。设立指建立机构、制度，关系、局面要用〈形成〉。"}, {"text": "他设立了早起的习惯。", "explanation": "这里应该用〈养成〉。设立指新建机构、制度、奖项，习惯要用〈养成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设立", "is_correct": true, "explanation": "正确。设立表示新建奖项，与“科学奖”相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热食物，不能用于新建奖项。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，不能用于设立奖项。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣物，与“科学奖”搭配不当。"}], "explanations": {"设立": "正确。设立表示新建奖项，与“科学奖”相符。", "煮": "语义：“煮”指加热食物，不能用于新建奖项。", "踢": "语义：“踢”指用脚击打，不能用于设立奖项。", "穿": "搭配：“穿”的宾语应是衣物，与“科学奖”搭配不当。"}, "sentence_index": 6, "correct_answer": "设立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校设立了开学典礼。", "explanation": "这里应该用〈举行〉。设立指新建机构、奖项、制度，典礼、会议要用〈举行〉。"}, {"text": "他设立了一篇文章。", "explanation": "这里应该用〈发表〉。设立指新建机构或制度，文章这类作品要用〈发表〉。"}, {"text": "政府设立了新的法律。", "explanation": "这里应该用〈颁布〉。设立指新建机构、制度，法律要用〈颁布〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校设立了一只助学基金。", "corrected_sentence": "学校设立了一个助学基金。", "error_description": "量词错误：“一只助学基金”。“只”多用于动物及成对器物中的单个（如一只鸟、一只鞋），不能修饰“基金”；基金应用量词“个”，应说“一个助学基金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所大学正在设立了一个奖励基金。", "corrected_sentence": "这所大学设立了一个奖励基金。", "error_description": "错误在“正在”。“正在”表示动作进行中，与表示完成的“了”冲突；“设立”是一次完成的动作，应去掉“正在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95965839-f764-4e3f-9457-23a216db4921') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
