INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87568, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用于发展经济、办事业等的钱款。", "primary_collocate": null, "pronunciation": "zī jīn", "ipa": "tsɹ̩⁵⁵ tɕin⁵⁵", "syllable_count": 2, "sentences": [{"text": "政府给山区学校拨了一笔发展资金。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的资金主要来自银行。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用新资金建了第二个工厂。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家投入大量资金发展农业。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的发展需要更多资金。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的资金已经全部到位了。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们向银行申请了一笔资金。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业没有资金，就不能扩大生产。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个国家向这个地区投入了资金。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的资金很充足，还准备再开两家店。", "target_word": "资金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "資金", "label": "繁体"}, {"form": "笔", "label": "量词"}, {"form": "资金链", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词；用于发展经济、办事业的钱款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f4d827-5213-4efb-b0e0-f6115791d1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87568, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "资金", "is_correct": true, "explanation": "正确答案：资金（zī jīn），指用于发展经济、办事业的钱款。"}, {"text": "丝巾", "is_correct": false, "explanation": "sī 与 zī 声母不同（s 与 z），意思是丝织的围巾。"}, {"text": "紫金", "is_correct": false, "explanation": "zǐ（第三声）与 zī（第一声）声调不同，意思是紫色的金子。"}, {"text": "自今", "is_correct": false, "explanation": "zì（第四声）与 zī（第一声）声调不同，意思是从今以后，属书面用语。"}], "explanations": {"资金": "正确答案：资金（zī jīn），指用于发展经济、办事业的钱款。", "丝巾": "sī 与 zī 声母不同（s 与 z），意思是丝织的围巾。", "紫金": "zǐ（第三声）与 zī（第一声）声调不同，意思是紫色的金子。", "自今": "zì（第四声）与 zī（第一声）声调不同，意思是从今以后，属书面用语。"}, "sentence_index": null, "correct_answer": "资金"}, "level_3": {"options": [{"text": "资金", "is_correct": true, "explanation": "资金指用于发展的钱款，与“一笔”和“发展”搭配，符合句意。"}, {"text": "人员", "is_correct": false, "explanation": "搭配：量词“笔”用于钱款，不能用来计量“人员”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是钱款，不能拿来拨给学校用于发展。"}, {"text": "土地", "is_correct": false, "explanation": "搭配：“土地”用“块”或“片”计量，不能与量词“笔”搭配。"}], "explanations": {"资金": "资金指用于发展的钱款，与“一笔”和“发展”搭配，符合句意。", "人员": "搭配：量词“笔”用于钱款，不能用来计量“人员”。", "时间": "语义：“时间”不是钱款，不能拿来拨给学校用于发展。", "土地": "搭配：“土地”用“块”或“片”计量，不能与量词“笔”搭配。"}, "sentence_index": 0, "correct_answer": "资金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山里的矿产资金很丰富。", "explanation": "这里应该用〈资源〉。矿产属于自然资源，资金指钱款，不能用来修饰矿产。"}, {"text": "这些资金要装订成册。", "explanation": "这里应该用〈病历〉。病历是记录病情的文件，需要装订成册保存；资金指用来做事的钱款，不能用来指文件。"}, {"text": "大家都在关注最新的资金。", "explanation": "这里应该用〈资讯〉。资讯指新闻和信息，资金只指钱款，不能用来指需要关注的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资金", "is_correct": true, "explanation": "资金指钱款，与“一笔”搭配，银行可以发放资金，符合句意。"}, {"text": "执照", "is_correct": false, "explanation": "语义：“执照”不是钱款，不能向银行“申请一笔”。"}, {"text": "卡片", "is_correct": false, "explanation": "搭配：量词“笔”用于钱款，“卡片”应用“张”计量。"}, {"text": "家具", "is_correct": false, "explanation": "语义：“家具”不是钱款，不能向银行申请。"}], "explanations": {"资金": "资金指钱款，与“一笔”搭配，银行可以发放资金，符合句意。", "执照": "语义：“执照”不是钱款，不能向银行“申请一笔”。", "卡片": "搭配：量词“笔”用于钱款，“卡片”应用“张”计量。", "家具": "语义：“家具”不是钱款，不能向银行申请。"}, "sentence_index": 6, "correct_answer": "资金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的资金包括一套房子和两辆汽车。", "explanation": "这里应该用〈财产〉。财产指个人拥有的房屋、车辆等；资金只指用来做事的钱款，不能指实物。"}, {"text": "药店里有很多资金，都是进口的。", "explanation": "这里应该用〈药品〉。药品指可以买卖的药物；资金只指用来做事的钱款，不能用来指商品。"}, {"text": "仓库里的资金都是饮料。", "explanation": "这里应该用〈库存〉。库存指仓库中存放的货物；资金指钱款，不能用来指饮料等货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府向这个地区拨了一个资金。", "corrected_sentence": "政府向这个地区拨了一笔资金。", "error_description": "量词错误：“资金”应用量词“笔”计量，不能用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几笔资金们已经全部到账了。", "corrected_sentence": "这几笔资金已经全部到账了。", "error_description": "词缀错误：“们”只用于指人的名词，资金不是人，不能加“们”，应直接说“这几笔资金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
