INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87601, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提到是在说话时说起某个人或某件事。", "primary_collocate": null, "pronunciation": "tí dào", "ipa": "tʰi˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他在会上提到了你的名字。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天提到了明天的考试。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常常提到小时候的事。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你刚才提到的那本书，我也想看。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有提到过自己的家人。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友聊天时提到了新工作。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里提到了几个重要问题。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想提到他的名字。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在信里提到下个月要回国。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶聊天时总提到爷爷。", "target_word": "提到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提到了", "label": "体标"}, {"form": "提到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "说话时说起某个人或某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00e5633-a762-4029-b384-af5ebcd7e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87601, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提到", "is_correct": true, "explanation": "提到（tí dào，第二声＋第四声）是正确答案，意思是说起某人或某事。"}, {"text": "踢到", "is_correct": false, "explanation": "tī（第一声）与 tí（第二声）声调不同，意思是用脚碰到。"}, {"text": "抬到", "is_correct": false, "explanation": "tái（第二声）与 tí（第二声）韵母不同（ai 与 i），意思是抬到某处。"}, {"text": "提刀", "is_correct": false, "explanation": "dāo（第一声）与 dào（第四声）声调不同，意思是拿着刀。"}], "explanations": {"提到": "提到（tí dào，第二声＋第四声）是正确答案，意思是说起某人或某事。", "踢到": "tī（第一声）与 tí（第二声）声调不同，意思是用脚碰到。", "抬到": "tái（第二声）与 tí（第二声）韵母不同（ai 与 i），意思是抬到某处。", "提刀": "dāo（第一声）与 dào（第四声）声调不同，意思是拿着刀。"}, "sentence_index": null, "correct_answer": "提到"}, "level_3": {"options": [{"text": "提到", "is_correct": true, "explanation": "“提到”表示在会上说起你的名字，符合语境。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于意见、讲话、文章，不能和“名字”搭配。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”指撤回已说的话或已给出的东西，名字不能被收回。"}, {"text": "评价", "is_correct": false, "explanation": "搭配：“评价”的对象是作品、表现等，不能评价一个名字。"}], "explanations": {"提到": "“提到”表示在会上说起你的名字，符合语境。", "发表": "搭配：“发表”用于意见、讲话、文章，不能和“名字”搭配。", "收回": "语义：“收回”指撤回已说的话或已给出的东西，名字不能被收回。", "评价": "搭配：“评价”的对象是作品、表现等，不能评价一个名字。"}, "sentence_index": 0, "correct_answer": "提到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看着照片，眼泪一下子提到了眼眶。", "explanation": "这里应该用〈涌上〉。“提到”没有涌上的意思，眼泪涌上眼眶要说“涌上”。"}, {"text": "这学期我的英语提到了很高的水平。", "explanation": "这里应该用〈提高〉。“提到”没有提升水平的意思，英语水平的提高要说“提高”。"}, {"text": "他一个人把三个孩子提到了大学毕业。", "explanation": "这里应该用〈拉扯〉。“提到”没有养育孩子的意思，把孩子养大要说“拉扯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87601, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "提到", "is_correct": true, "explanation": "提到（tí dào，第二声＋第四声）是正确答案，意思是说起某人或某事。"}, {"text": "堤道", "is_correct": false, "explanation": "dī（第一声）与 tí（第二声）声母和声调都不同，意思是堤上的路。"}, {"text": "梯道", "is_correct": false, "explanation": "tī（第一声）与 tí（第二声）声调不同，意思是像梯子一样的小路。"}, {"text": "剃到", "is_correct": false, "explanation": "tì（第四声）与 tí（第二声）声调不同，意思是剃时碰到。"}], "explanations": {"提到": "提到（tí dào，第二声＋第四声）是正确答案，意思是说起某人或某事。", "堤道": "dī（第一声）与 tí（第二声）声母和声调都不同，意思是堤上的路。", "梯道": "tī（第一声）与 tí（第二声）声调不同，意思是像梯子一样的小路。", "剃到": "tì（第四声）与 tí（第二声）声调不同，意思是剃时碰到。"}, "sentence_index": null, "correct_answer": "提到"}, "level_3": {"options": [{"text": "提到", "is_correct": true, "explanation": "“提到”表示在报告里说起几个问题，符合语境。"}, {"text": "体验", "is_correct": false, "explanation": "搭配：“体验”的对象是生活、感受，不能说体验问题。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是迎接、接纳的意思，问题不能被欢迎。"}, {"text": "颁发", "is_correct": false, "explanation": "搭配：“颁发”用于奖状、证书等，不能颁发问题。"}], "explanations": {"提到": "“提到”表示在报告里说起几个问题，符合语境。", "体验": "搭配：“体验”的对象是生活、感受，不能说体验问题。", "欢迎": "语义：“欢迎”是迎接、接纳的意思，问题不能被欢迎。", "颁发": "搭配：“颁发”用于奖状、证书等，不能颁发问题。"}, "sentence_index": 6, "correct_answer": "提到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树一年里提到了两米。", "explanation": "这里应该用〈长到〉。“提到”没有长高的意思，树木长到某个高度要说“长到”。"}, {"text": "他从银行提到了一千块钱。", "explanation": "这里应该用〈取〉。“提到”没有取款的意思，从银行取钱要说“取”。"}, {"text": "这张照片让她的心情提到了谷底。", "explanation": "这里应该用〈落到〉。“提到”没有下降的意思，心情跌到低点要说“落到谷底”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前提到了过他的名字。", "corrected_sentence": "我以前提到过他的名字。", "error_description": "体标错误：应改为“提到过”。“了”和“过”不能同时用在“提到”后，表示曾经说起过只用“过”，不说“提到了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈从来不提到过这件事。", "corrected_sentence": "妈妈从来没提到过这件事。", "error_description": "“过”表示曾经有过，否定要用“没”：没提到过。“不”表示习惯或意愿，不能与“过”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
