INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87613, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有点是说有一点点，不太多。", "primary_collocate": null, "pronunciation": "yǒu diǎn", "ipa": "jou˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我口袋里有点钱，你拿去用吧。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里有点水果，你想吃吗？", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他最近有点时间，可以帮你。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有点水，别碰到书。", "target_word": "有点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家有点米，不用买了。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子里有点茶。", "target_word": "有点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你手里有点零钱吗？", "target_word": "有点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我身上有点现金，够付车费。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她包里有点糖，分给孩子们。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盘子里还有点菜，你吃完吧。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有点儿", "label": "儿化"}, {"form": "有一点", "label": "复合"}], "register": "口语", "sense_fingerprint": "动词，后接名词，表示拥有少量的东西或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b19c0f9-466f-4374-8e4f-5a9190f00083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有点", "is_correct": true, "explanation": "正确：“有点钱”表示有少量的钱，与“你拿去用吧”相符。"}, {"text": "没", "is_correct": false, "explanation": "语义：“没钱”与“你拿去用吧”矛盾。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“口袋里”不能与“买钱”搭配，句意不通。"}, {"text": "赚", "is_correct": false, "explanation": "搭配：“赚钱”不能发生在“口袋里”，句意不通。"}], "explanations": {"有点": "正确：“有点钱”表示有少量的钱，与“你拿去用吧”相符。", "没": "语义：“没钱”与“你拿去用吧”矛盾。", "买": "搭配：“口袋里”不能与“买钱”搭配，句意不通。", "赚": "搭配：“赚钱”不能发生在“口袋里”，句意不通。"}, "sentence_index": 0, "correct_answer": "有点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋有点大，你换小一号吧。", "explanation": "这里是程度副词“有点”（稍微）修饰形容词“大”的用法，不是“有一点点”的数量义，不能接名词。"}, {"text": "我今天有点累，不想出门。", "explanation": "这里是程度副词“有点”（稍微）修饰“累”的用法，不是“有一点点”的数量义。"}, {"text": "这个汤有点咸，别加盐了。", "explanation": "这里是程度副词“有点”（稍微）修饰“咸”的用法，不是“有一点点”的数量义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有点", "is_correct": true, "explanation": "正确：“有点零钱”表示手里有少量零钱，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要接可吃的东西，不能接“零钱”。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送零钱”不能说“手里送”，句意不通。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”与“零钱”搭配不当，句意不通。"}], "explanations": {"有点": "正确：“有点零钱”表示手里有少量零钱，与句意相符。", "吃": "配价：“吃”要接可吃的东西，不能接“零钱”。", "送": "搭配：“送零钱”不能说“手里送”，句意不通。", "烧": "搭配：“烧”与“零钱”搭配不当，句意不通。"}, "sentence_index": 6, "correct_answer": "有点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个书包有点重，我帮你背一会儿。", "explanation": "这里是程度副词“有点”（稍微）修饰形容词“重”的用法，不是“有一点点”的数量义。"}, {"text": "这条路有点远，我们骑车去吧。", "explanation": "这里是程度副词“有点”（稍微）修饰“远”的用法，不是“有一点点”的数量义。"}, {"text": "他的脾气有点急，你别跟他争。", "explanation": "这里是程度副词“有点”（稍微）修饰“急”的用法，不是“有一点点”的数量义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冰箱里有点，你拿去吧。", "corrected_sentence": "冰箱里有点牛奶，你拿去吧。", "error_description": "“有点”后缺少所带的名词，应说“有点牛奶”，不能只说“有点”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "抽屉里有点了纸，你拿去用吧。", "corrected_sentence": "抽屉里有点纸，你拿去用吧。", "error_description": "“了”不能插在“有点”和名词“纸”之间：应说“有点纸”，“有点”后直接接宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
