INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87614, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87614, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度不深，稍微；多用于不如意的事。", "primary_collocate": null, "pronunciation": "yǒu diǎn", "ipa": "jou˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天有点冷，多穿件衣服。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨晚没睡好，现在有点累。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菜有点咸，我吃不下。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他迟到了，老师有点生气。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服有点贵，我不想买。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我头有点疼，想早点休息。", "target_word": "有点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里有点吵，我听不清。", "target_word": "有点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这道题有点难，我不会做。", "target_word": "有点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她今天有点不高兴，别问她。", "target_word": "有点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上堵车，我有点担心。", "target_word": "有点", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "有点儿", "label": "儿化"}, {"form": "有一点", "label": "复合"}], "register": "口语", "sense_fingerprint": "副词，放在形容词或心理动词前，表示程度轻微，多含不满或不如意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b19c0f9-466f-4374-8e4f-5a9190f00083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有点", "is_correct": true, "explanation": "正确：“有点冷”表示程度轻，与“多穿件衣服”的建议相符。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不冷”与后句“多穿件衣服”的建议矛盾。"}, {"text": "有", "is_correct": false, "explanation": "搭配：“有”不能直接接形容词“冷”，“今天有冷”不成说法。"}, {"text": "没", "is_correct": false, "explanation": "语义：“没冷”与“多穿件衣服”的语境矛盾。"}], "explanations": {"有点": "正确：“有点冷”表示程度轻，与“多穿件衣服”的建议相符。", "不": "语义：“不冷”与后句“多穿件衣服”的建议矛盾。", "有": "搭配：“有”不能直接接形容词“冷”，“今天有冷”不成说法。", "没": "语义：“没冷”与“多穿件衣服”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "有点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌上还有点饭，你先吃吧。", "explanation": "这里的“有点”是“有少量”的意思，后接名词“饭”，不是程度副词“稍微”。"}, {"text": "我们有点时间，先聊聊吧。", "explanation": "这里的“有点”是“有少量”的意思，接名词，不是程度副词“稍微”。"}, {"text": "他身上有点钱，够打车了。", "explanation": "这里的“有点”是“有少量”的意思，接名词，不是程度副词“稍微”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有点", "is_correct": true, "explanation": "正确：“有点吵”表示程度轻，与“我听不清”的结果相符。"}, {"text": "不再", "is_correct": false, "explanation": "语义：“不再吵”表示已经安静，与“我听不清”的语境矛盾。"}, {"text": "不太", "is_correct": false, "explanation": "语义：“不太吵”说明噪音不大，与“我听不清”的语境矛盾。"}, {"text": "才", "is_correct": false, "explanation": "搭配：副词“才”不能直接修饰“吵”来表示程度，句意不通。"}], "explanations": {"有点": "正确：“有点吵”表示程度轻，与“我听不清”的结果相符。", "不再": "语义：“不再吵”表示已经安静，与“我听不清”的语境矛盾。", "不太": "语义：“不太吵”说明噪音不大，与“我听不清”的语境矛盾。", "才": "搭配：副词“才”不能直接修饰“吵”来表示程度，句意不通。"}, "sentence_index": 6, "correct_answer": "有点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "碗里还有点汤，你喝吧。", "explanation": "这里的“有点”是“有少量”的意思，接名词，不是程度副词“稍微”。"}, {"text": "箱子里有点书，你拿去看吧。", "explanation": "这里的“有点”是“有少量”的意思，接名词，不是程度副词“稍微”。"}, {"text": "他手里有点吃的，你饿了吗？", "explanation": "这里的“有点”是“有少量”的意思，接名词，不是程度副词“稍微”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这顿饭有点了贵，我们换一家吧。", "corrected_sentence": "这顿饭有点贵，我们换一家吧。", "error_description": "“了”不能插在“有点”和形容词“贵”之间：应说“有点贵”。（句末带“了”的“有点贵了”是合法的。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子有点的暗，我们开灯吧。", "corrected_sentence": "这间屋子有点暗，我们开灯吧。", "error_description": "“有点”与形容词之间不能插入“的”，应说“有点暗”，去掉“的”即可。“有点”是程度副词，直接修饰形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
