INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87620, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "每天出版的报纸。", "primary_collocate": null, "pronunciation": "rì bào", "ipa": "ɻ̩˥˩ pau̯˥˩", "syllable_count": 2, "sentences": [{"text": "这是一份中文日报。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天坐地铁时读日报。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家日报有二十个版。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的日报已经卖完了。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们剪下日报里的新闻。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日报和周报哪个更便宜？", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把日报放在桌子上。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那家日报的头版读了两遍。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈不看手机，只看日报。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当日报的记者。", "target_word": "日报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "日報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "每天出版的报纸（出版物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00e5633-a762-4029-b384-af5ebcd7e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面包", "is_correct": false, "explanation": "语义：“中文”修饰的是语言文字，面包不是文字材料，不能说“中文面包”。"}, {"text": "手机", "is_correct": false, "explanation": "量词：手机用“部”，不用“份”，“这是一份中文手机”不成立。"}, {"text": "点心", "is_correct": false, "explanation": "语义：点心是食品，不是印刷的文字材料，不能说“中文点心”。"}, {"text": "日报", "is_correct": true, "explanation": "“日报”是中文报纸，“这是一份中文日报”符合句意。"}], "explanations": {"面包": "语义：“中文”修饰的是语言文字，面包不是文字材料，不能说“中文面包”。", "手机": "量词：手机用“部”，不用“份”，“这是一份中文手机”不成立。", "点心": "语义：点心是食品，不是印刷的文字材料，不能说“中文点心”。", "日报": "“日报”是中文报纸，“这是一份中文日报”符合句意。"}, "sentence_index": 0, "correct_answer": "日报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份日报每周五出版，我每周五都去买。", "explanation": "这里应该用〈周报〉。日报是每天出版的，每周五出版的要用周报。"}, {"text": "医生在日报上写下了诊断结果。", "explanation": "这里应该用〈病历〉。写下诊断结果的是病历，日报是报纸，不记录病情。"}, {"text": "我昨天晚上一口气读完了日报，主角最后找到了宝藏。", "explanation": "这里应该用〈小说〉。讲主角找宝藏的故事是小说，日报报道的是每天的新闻，不写这样的情节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳无法被人拿起来放在桌子上，句子不成立。"}, {"text": "意见", "is_correct": false, "explanation": "搭配：“放”的对象应是具体物品，“意见”是抽象事物，不能放在桌子上。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无形无体，不能被“把”起来放在桌子上。"}, {"text": "日报", "is_correct": true, "explanation": "“日报”是具体的报纸，可以被拿起来放在桌子上，与句意相符。"}], "explanations": {"太阳": "语义：太阳无法被人拿起来放在桌子上，句子不成立。", "意见": "搭配：“放”的对象应是具体物品，“意见”是抽象事物，不能放在桌子上。", "空气": "语义：空气无形无体，不能被“把”起来放在桌子上。", "日报": "“日报”是具体的报纸，可以被拿起来放在桌子上，与句意相符。"}, "sentence_index": 6, "correct_answer": "日报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给我开了一张日报，让我每天吃两次。", "explanation": "这里应该用〈处方〉。让人按时服用的是处方，日报是报纸。"}, {"text": "店员递给我一张日报，上面写着一共付了多少钱。", "explanation": "这里应该用〈收据〉。付款后开出的凭证是收据，日报是报纸，不记录付款金额。"}, {"text": "这台电脑的日报写得很详细。", "explanation": "这里应该用〈说明书〉。介绍电脑用法的是说明书，日报不讲这些内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天都收到一只日报。", "corrected_sentence": "我每天都收到一份日报。", "error_description": "量词错误：报纸应用“份”或“张”，“只”只用于动物等，应改为“一份日报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天早上都读一份日报们。", "corrected_sentence": "他每天早上都读一份日报。", "error_description": "词形错误：报纸是物品名词，不能加“们”表复数，“一份日报们”错误，应说“一份日报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
