INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87640, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "政府中主管某一部门的最高领导人。", "primary_collocate": null, "pronunciation": "bù zhǎng", "ipa": "pu˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "部长今天要去机场接外国客人。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的部长在会上讲了话。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部长回答了记者的问题。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位部长已经在政府工作了二十年。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部长下周要去法国访问。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者问部长明年有什么计划。", "target_word": "部长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部长说，政府会帮助农民。", "target_word": "部长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在电视上见过这位部长。", "target_word": "部长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长带着几位专家去了农村。", "target_word": "部长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总理请部长们把报告写好。", "target_word": "部长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "部長", "label": "繁体"}], "register": "正式", "sense_fingerprint": "部长：政府某一部的最高负责人，即国家的部级官员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50dfcc0b-fc77-441f-aa12-4c4358322b62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部长", "is_correct": true, "explanation": "正确选项。“部长”是政府部门的最高负责人，能够出面接待外国客人。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”指种花草的地方，不是能去机场接人的对象。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑的组成部分，不会去机场接人。"}, {"text": "汽水", "is_correct": false, "explanation": "搭配：“接”的主语须是能行动的人，不能说“汽水去接客人”。"}], "explanations": {"部长": "正确选项。“部长”是政府部门的最高负责人，能够出面接待外国客人。", "花园": "语义：“花园”指种花草的地方，不是能去机场接人的对象。", "窗户": "语义：“窗户”是建筑的组成部分，不会去机场接人。", "汽水": "搭配：“接”的主语须是能行动的人，不能说“汽水去接客人”。"}, "sentence_index": 0, "correct_answer": "部长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的部长每周都去学校接孩子放学。", "explanation": "这里误把“部长”当成“爸爸”来用。部长指政府部门的最高领导人，不能指孩子的父亲，应说“爸爸”。"}, {"text": "这份报告的部长写得很清楚。", "explanation": "这里误把“部长”当成“部分”来用，指报告的一部分。部长指政府或部门的负责人，应说“部分”。"}, {"text": "我们那里选出了一只部长。", "explanation": "这里应该用〈位〉。量词“只”用于动物或小件物品，指人的部长要用“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部长", "is_correct": true, "explanation": "正确选项。“部长”能够发表讲话，句子表示政府部长说政府会帮助农民。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“说”的主语一般是人，“冰箱”不能说话。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有说话的能力，句子说不通。"}, {"text": "树木", "is_correct": false, "explanation": "语义：“树木”不会说话，不能作“说”的主语。"}], "explanations": {"部长": "正确选项。“部长”能够发表讲话，句子表示政府部长说政府会帮助农民。", "冰箱": "搭配：“说”的主语一般是人，“冰箱”不能说话。", "石头": "语义：“石头”没有说话的能力，句子说不通。", "树木": "语义：“树木”不会说话，不能作“说”的主语。"}, "sentence_index": 6, "correct_answer": "部长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们那里来了两条部长。", "explanation": "这里应该用〈位〉。量词“条”用于细长的东西，不能用来数人。"}, {"text": "我们球队的部长每场比赛都进球。", "explanation": "这里误把“部长”当成“球员”来用。部长指政府部门的最高领导人，不能指球队里踢球的人，应说“球员”。"}, {"text": "这张桌子的部长松了，需要修一下。", "explanation": "这里误把“部长”当成“部件”来用，指桌子的零件。部长指政府部门的最高领导人，不能指零件，应说“部件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只部长昨天在会上讲了话。", "corrected_sentence": "那位部长昨天在会上讲了话。", "error_description": "错误：“那只部长”；正确：“那位部长”。“只”用于动物或小件物品，指人的部长要用量词“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "总理昨天请两位部长们来开会。", "corrected_sentence": "总理昨天请两位部长来开会。", "error_description": "错误：“两位部长们”；正确：“两位部长”。有数词修饰时不再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
