INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87651, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "错", "is_correct": true, "explanation": "错是不对，不是应该有的样子。"}, {"text": "坐", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是坐下。"}, {"text": "粗", "is_correct": false, "explanation": "cū（第一声）与 cuò（第四声）声调不同，意思是粗细、不精细。"}, {"text": "醋", "is_correct": false, "explanation": "cù 与 cuò 韵母不同（u / uo），声调相同，意思是醋。"}, {"text": "作", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做、写作。"}], "explanations": {"错": "错是不对，不是应该有的样子。", "坐": "zuò 与 cuò 声母不同（z / c），声调相同，意思是坐下。", "粗": "cū（第一声）与 cuò（第四声）声调不同，意思是粗细、不精细。", "醋": "cù 与 cuò 韵母不同（u / uo），声调相同，意思是醋。", "作": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做、写作。"}, "sentence_index": null, "correct_answer": "错"}, "level_3": {"options": [{"text": "错", "is_correct": true, "explanation": "“没有错”表示自己没有做不对的事，句意成立。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体，不能用来形容人的对错。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，与被骂的原因无关。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“没有高”不成说法，“高”不能表示对错。"}], "explanations": {"错": "“没有错”表示自己没有做不对的事，句意成立。", "厚": "搭配：“厚”形容物体，不能用来形容人的对错。", "甜": "语义：“甜”指味道，与被骂的原因无关。", "高": "搭配：“没有高”不成说法，“高”不能表示对错。"}, "sentence_index": 6, "correct_answer": "错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房间很错，大家都不想进去。", "explanation": "这里应该用〈乱〉。房间的整洁程度说“乱”，“错”不能形容房间。"}, {"text": "他走路很错，总是迟到。", "explanation": "这里应该用〈慢〉。走路快慢说“慢”，“错”不表示速度。"}, {"text": "今天天气很错，我们在家待着。", "explanation": "这里应该用〈冷〉。天气冷热说“冷”，“错”不表示温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
