INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87652, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不正确；与事实或要求不符。", "primary_collocate": null, "pronunciation": "cuò", "ipa": "tsʰwo˥˩", "syllable_count": 1, "sentences": [{"text": "这道题的答案是错的。", "target_word": "错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个数字是错的，请再算一次。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上的路名是错的。", "target_word": "错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你给我的电话号码是错的。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话是错的，事实不是这样。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上的消息是错的。", "target_word": "错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的算法没错，是数据错了。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个结果和事实不符，是错的。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张表里的名字有错的地方。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说的地址是错的，我们找不到。", "target_word": "错", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "错误", "label": "复合"}, {"form": "对错", "label": "复合"}, {"form": "错了", "label": "体标"}, {"form": "錯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词，指答案、数字、消息等不正确，与事实不符", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b19c0f9-466f-4374-8e4f-5a9190f00083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87652, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "错", "is_correct": true, "explanation": "错：不正确，与事实或要求不符。"}, {"text": "做", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做事。"}, {"text": "搓", "is_correct": false, "explanation": "cuō（第一声）与 cuò（第四声）声调不同，意思是用手来回揉。"}, {"text": "脆", "is_correct": false, "explanation": "cuì 与 cuò 韵母不同（ui / uo），声调相同，意思是容易折断、松脆。"}, {"text": "座", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是座位。"}], "explanations": {"错": "错：不正确，与事实或要求不符。", "做": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做事。", "搓": "cuō（第一声）与 cuò（第四声）声调不同，意思是用手来回揉。", "脆": "cuì 与 cuò 韵母不同（ui / uo），声调相同，意思是容易折断、松脆。", "座": "zuò 与 cuò 声母不同（z / c），声调相同，意思是座位。"}, "sentence_index": null, "correct_answer": "错"}, "level_3": {"options": [{"text": "错", "is_correct": true, "explanation": "“错的”表示答案不正确，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，答案不能是甜的。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，答案没有咸淡。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或物的体形，答案没有胖瘦。"}], "explanations": {"错": "“错的”表示答案不正确，符合句意。", "甜": "搭配：“甜”形容味道，答案不能是甜的。", "咸": "搭配：“咸”形容味道，答案没有咸淡。", "瘦": "体貌：“瘦”形容人或物的体形，答案没有胖瘦。"}, "sentence_index": 0, "correct_answer": "错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子很错，搬不动。", "explanation": "这里应该用〈重〉。箱子的轻重说“重”，“错”指不正确，不表示重量。"}, {"text": "这杯水很错，别喝了。", "explanation": "这里应该用〈变质〉。错表示不正确，不用来描述水的状态；水不能喝时说变质。"}, {"text": "这根绳子很错，容易断。", "explanation": "这里应该用〈细〉。绳子的粗细说“细”，“错”不表示粗细。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87652, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "错", "is_correct": true, "explanation": "错：不正确，与事实或要求不符。"}, {"text": "坐", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是坐下。"}, {"text": "粗", "is_correct": false, "explanation": "cū（第一声）与 cuò（第四声）声调不同，意思是粗细、不精细。"}, {"text": "醋", "is_correct": false, "explanation": "cù 与 cuò 韵母不同（u / uo），声调相同，意思是醋。"}, {"text": "作", "is_correct": false, "explanation": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做、写作。"}], "explanations": {"错": "错：不正确，与事实或要求不符。", "坐": "zuò 与 cuò 声母不同（z / c），声调相同，意思是坐下。", "粗": "cū（第一声）与 cuò（第四声）声调不同，意思是粗细、不精细。", "醋": "cù 与 cuò 韵母不同（u / uo），声调相同，意思是醋。", "作": "zuò 与 cuò 声母不同（z / c），声调相同，意思是做、写作。"}, "sentence_index": null, "correct_answer": "错"}, "level_3": {"options": [{"text": "错", "is_correct": true, "explanation": "“数据错了”说数据不正确，与前句“没错”形成对比。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线，数据不能说亮了。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容质地，数据不能说硬了。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，“数据甜了”不成说法。"}], "explanations": {"错": "“数据错了”说数据不正确，与前句“没错”形成对比。", "亮": "搭配：“亮”形容光线，数据不能说亮了。", "硬": "搭配：“硬”形容质地，数据不能说硬了。", "甜": "搭配：“甜”形容味道，“数据甜了”不成说法。"}, "sentence_index": 6, "correct_answer": "错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼很错，远远就能看见。", "explanation": "这里应该用〈高〉。楼的高低说“高”，“错”不能形容楼的高矮。"}, {"text": "这盏灯很错，光线很好，大家都喜欢。", "explanation": "这里应该用〈亮〉。灯的明暗说“亮”，“错”不表示亮度，不能用来形容灯光。"}, {"text": "这块布很错，穿起来很舒服。", "explanation": "这里应该用〈软〉。布的软硬说“软”，“错”不表示软硬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个答案已经错过，我们重新算吧。", "corrected_sentence": "这个答案已经错了，我们重新算吧。", "error_description": "助词错误：“错过”是“错过机会”的意思，这里指答案不对，应用“错了”，不能用“错过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这个名字写了错。", "corrected_sentence": "我把这个名字写错了。", "error_description": "结果补语位置错误：“错”要紧跟动词“写”，应说“写错了”，不能说“写了错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d37356c-0eff-4606-89e5-65e4bfc3cba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
