INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不大是不太多，不太厉害。", "primary_collocate": null, "pronunciation": "bú dà", "ipa": "pu³⁵ ta⁵¹", "syllable_count": 2, "sentences": [{"text": "今天的风不大，我们去公园玩吧。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的雨下得不大，不用带伞。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受的伤不大，过几天就好了。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小毛病不大，不用担心。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的病不大要紧，不用去医院。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒不大厉害，睡一觉就好了。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雪下得不大，路上很好走。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的地震不大，没有人受伤。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事对他的影响不大，他还是很开心。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来的人不大多，教室里很安静。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词；表示数量不太多、程度不太厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f4d827-5213-4efb-b0e0-f6115791d1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不大", "is_correct": true, "explanation": "正确答案：不大（bú dà），表示数量不太多、程度不太厉害。"}, {"text": "不但", "is_correct": false, "explanation": "dàn 与 dà 韵母不同（多一个 n），意思是“不但”，是连词。"}, {"text": "不打", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是不击打。"}, {"text": "不带", "is_correct": false, "explanation": "dài 与 dà 韵母不同（ai 与 a），意思是不携带。"}, {"text": "不答", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是不回答。"}], "explanations": {"不大": "正确答案：不大（bú dà），表示数量不太多、程度不太厉害。", "不但": "dàn 与 dà 韵母不同（多一个 n），意思是“不但”，是连词。", "不打": "dǎ（第三声）与 dà（第四声）声调不同，意思是不击打。", "不带": "dài 与 dà 韵母不同（ai 与 a），意思是不携带。", "不答": "dá（第二声）与 dà（第四声）声调不同，意思是不回答。"}, "sentence_index": null, "correct_answer": "不大"}, "level_3": {"options": [{"text": "不大", "is_correct": true, "explanation": "不大表示风力不强，与“去公园玩”的语境相符。"}, {"text": "很甜", "is_correct": false, "explanation": "语义：风不能是甜的，与句意不合。"}, {"text": "不多", "is_correct": false, "explanation": "搭配：“风”说大小或强弱，不说多少，不能用“不多”形容。"}, {"text": "很贵", "is_correct": false, "explanation": "语义：风不能有价钱，与句意不合。"}], "explanations": {"不大": "不大表示风力不强，与“去公园玩”的语境相符。", "很甜": "语义：风不能是甜的，与句意不合。", "不多": "搭配：“风”说大小或强弱，不说多少，不能用“不多”形容。", "很贵": "语义：风不能有价钱，与句意不合。"}, "sentence_index": 0, "correct_answer": "不大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨下得非常不大，路面却全是积水。", "explanation": "这里应该用〈很大〉。“不大”表示数量不太多、程度不太厉害，不能与“非常”连用，程度深的说法是“很大”。"}, {"text": "这次的风非常不大，却把树全吹倒了。", "explanation": "这里应该用〈猛烈〉。“不大”表示程度不太厉害，不能与“非常”连用，“非常猛烈”才是正确搭配。"}, {"text": "他的感冒完全不大，却躺了一整天。", "explanation": "这里应该用〈严重〉。“不大”表示程度不太厉害，不能与“完全”连用，应说“不太严重”或“很严重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不大", "is_correct": true, "explanation": "不大表示雪下得不猛，与“路上很好走”相符。"}, {"text": "很厚", "is_correct": false, "explanation": "语义：雪下得很厚，路上会很难走，与后句“路上很好走”矛盾。"}, {"text": "很猛", "is_correct": false, "explanation": "语义：雪下得很猛，路上会很难走，与后句“路上很好走”矛盾。"}, {"text": "不高", "is_correct": false, "explanation": "搭配：“下雪”不说“高”，“下得不高”不成立。"}], "explanations": {"不大": "不大表示雪下得不猛，与“路上很好走”相符。", "很厚": "语义：雪下得很厚，路上会很难走，与后句“路上很好走”矛盾。", "很猛": "语义：雪下得很猛，路上会很难走，与后句“路上很好走”矛盾。", "不高": "搭配：“下雪”不说“高”，“下得不高”不成立。"}, "sentence_index": 6, "correct_answer": "不大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛他全部不大投入。", "explanation": "这里应该用〈全力〉。“不大”表示程度不太厉害，不能与“全部”这类表示全部的词搭配，应说“全力投入”。"}, {"text": "这件事他绝对不大在乎。", "explanation": "这里应该用〈完全不〉。“不大”表示程度不太厉害，不能与“绝对”搭配，应说“完全不在乎”。"}, {"text": "这次感冒的症状十分不大，却一直咳嗽不止。", "explanation": "这里应该用〈非常严重〉。“不大”表示程度不太厉害，不能与“十分”连用，程度深的说法是“非常严重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天的风很不大，没有吹坏树。", "corrected_sentence": "昨天的风不大，没有吹坏树。", "error_description": "多余的程度副词：“不大”前面不能再加“很”，应说“风不大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场雪不大下得，路上很好走。", "corrected_sentence": "这场雪下得不大，路上很好走。", "error_description": "语序错误：补语结构中「不大」被提前到动词前，「这场雪不大下得」有误，应为「下得不大」，「不大」须放在「下得」之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87664, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
