INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87664, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不很；程度不深。", "primary_collocate": null, "pronunciation": "bú dà", "ipa": "pu³⁵ ta⁵¹", "syllable_count": 2, "sentences": [{"text": "这件事我不大清楚。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天不大舒服，想回家休息。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜不大好吃。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不大喜欢吃甜的东西。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不大爱说话，总是很安静。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最近不大高兴，大家都看出来了。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语不大好，所以说得很慢。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天不大冷，不用穿很多衣服。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不大明白老师的意思。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的坡不大陡，骑车也能上去。", "target_word": "不大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词；表示程度不深，相当于“不太”“不很”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 4 words above tier T1 (max 2): 条路 (Zipf 3.25), 坡 (Zipf 3.97), 陡 (Zipf 2.96), 骑车 (Zipf 3.58)']::text[], '63f4d827-5213-4efb-b0e0-f6115791d1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不大", "is_correct": true, "explanation": "正确答案：不大（bú dà），表示程度不深，相当于“不太”，是口语常用词。"}, {"text": "不但", "is_correct": false, "explanation": "dàn 与 dà 韵母不同（多一个 n），意思是“不但”，是连词。"}, {"text": "不打", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是不击打。"}, {"text": "不带", "is_correct": false, "explanation": "dài 与 dà 韵母不同（ai 与 a），意思是不携带。"}, {"text": "不答", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是不回答。"}], "explanations": {"不大": "正确答案：不大（bú dà），表示程度不深，相当于“不太”，是口语常用词。", "不但": "dàn 与 dà 韵母不同（多一个 n），意思是“不但”，是连词。", "不打": "dǎ（第三声）与 dà（第四声）声调不同，意思是不击打。", "不带": "dài 与 dà 韵母不同（ai 与 a），意思是不携带。", "不答": "dá（第二声）与 dà（第四声）声调不同，意思是不回答。"}, "sentence_index": null, "correct_answer": "不大"}, "level_3": {"options": [{"text": "不大", "is_correct": true, "explanation": "不大表示程度不深，与“清楚”搭配，符合句意。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示经常发生，不能修饰“清楚”这种状态。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一向如此，与“清楚”这种当下状态不合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行，不能用于“清楚”这种状态。"}], "explanations": {"不大": "不大表示程度不深，与“清楚”搭配，符合句意。", "常常": "语义：“常常”表示经常发生，不能修饰“清楚”这种状态。", "从来": "语义：“从来”表示一向如此，与“清楚”这种当下状态不合。", "正在": "搭配：“正在”表示动作进行，不能用于“清楚”这种状态。"}, "sentence_index": 0, "correct_answer": "不大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜非常不大好吃，大家都没吃完。", "explanation": "这里应该用〈非常不〉。“不大”只表示程度不深，不能与“非常”这类表示程度很深的词连用，强烈否定要说“非常不好吃”。"}, {"text": "他一点也不大愿意参加这次活动。", "explanation": "这里应该用〈完全不〉。“不大”表示程度不深，不能与“一点也”表示的完全否定搭配，应说“完全不愿意”。"}, {"text": "这件事我绝对不大明白。", "explanation": "这里应该用〈彻底不〉。“不大”表示程度不深，不能与“绝对”这类表示绝对的词搭配，应说“彻底不明白”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不大", "is_correct": true, "explanation": "不大表示程度不深，与“好”搭配，与后句“说得很慢”的因果相符。"}, {"text": "很", "is_correct": false, "explanation": "语义：“汉语很好”与后句“所以说得很慢”的因果不通。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“汉语已经好”与后句“所以说得很慢”的因果不通。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示即刻发生，不能修饰表示水平的“好”。"}], "explanations": {"不大": "不大表示程度不深，与“好”搭配，与后句“说得很慢”的因果相符。", "很": "语义：“汉语很好”与后句“所以说得很慢”的因果不通。", "已经": "语义：“汉语已经好”与后句“所以说得很慢”的因果不通。", "立刻": "搭配：“立刻”表示即刻发生，不能修饰表示水平的“好”。"}, "sentence_index": 6, "correct_answer": "不大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他全部不大及格。", "explanation": "这里应该用〈全部不〉。“不大”表示程度不深，不能与“全部”这类表示全部的词搭配，应说“全部不及格”。"}, {"text": "她坚决不大会同意这个计划。", "explanation": "这里应该用〈坚决不〉。“不大”表示程度不深，不能与“坚决”这类表示决断的词搭配，应说“坚决不会同意”。"}, {"text": "这个问题我十分不大懂。", "explanation": "这里应该用〈全然不〉。“不大”表示程度不深，不能与“十分”这类表示程度很深的词连用，应说“全然不懂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种颜色我很不大喜欢。", "corrected_sentence": "这种颜色我不大喜欢。", "error_description": "多余的程度副词：“不大”前面不能再加“很”，“很不大”重复表示程度，应直接说“不大喜欢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道菜我觉得不大的咸。", "corrected_sentence": "这道菜我觉得不大咸。", "error_description": "结构错误：副词“不大”修饰形容词“咸”时不加“的”，应说“不大咸”，不能说“不大的咸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c645df3b-621c-4776-bd13-68de8b7dea98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
