INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87665, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "整整是一点不多也一点不少，正好是那么多。", "primary_collocate": null, "pronunciation": "zhěng zhěng", "ipa": "ʈʂəŋ˨˩˦ ʈʂəŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "数一数，盒子里整整十个苹果，不多不少。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从我家到学校，整整一公里，不多不少。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书整整一百页，一页不多，一页不少。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这箱苹果整整五十斤，称过了，不多也不少。", "target_word": "整整", "complexity_tier": "T3", "furigana": "zhěng zhěng", "sentence_source": "generated"}, {"text": "这张桌子整整两米长，不多也不少。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把钱数了三遍，整整一千块，正好。", "target_word": "整整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有整整四十个同学，一个不少。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杯子里的水整整一升，不多也不少。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说考试时间是整整一小时，不能多也不能少。", "target_word": "整整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了五斤苹果，称出来整整五斤。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整整：数量恰好足数，不多不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd5c4b2d-97ab-40df-bb81-bfbbee817b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整整", "is_correct": true, "explanation": "整整：副词，表示数量恰好足数、不多不少，这里修饰“十个苹果”。"}, {"text": "大约", "is_correct": false, "explanation": "语义：“大约”表示估计，与“不多不少”的精确数目矛盾。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，数苹果并无意外，与“不多不少”的平常语气不合。"}, {"text": "约", "is_correct": false, "explanation": "语域：“约”偏书面，口语数数一般不用，且与“不多不少”的精确之意相冲突。"}], "explanations": {"整整": "整整：副词，表示数量恰好足数、不多不少，这里修饰“十个苹果”。", "大约": "语义：“大约”表示估计，与“不多不少”的精确数目矛盾。", "竟": "语义：“竟”表示出乎意料，数苹果并无意外，与“不多不少”的平常语气不合。", "约": "语域：“约”偏书面，口语数数一般不用，且与“不多不少”的精确之意相冲突。"}, "sentence_index": 0, "correct_answer": "整整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河整整五百米宽，我们只是随口说的。", "explanation": "这里应该用〈将近〉。整整说明数目确切，而“只是随口说的”表示只是随便估计，两者矛盾。"}, {"text": "我们估计车站离这里整整五公里。", "explanation": "这里应该用〈大约〉。“整整”说明数量确切，而“估计”表示不确定，两者矛盾。"}, {"text": "这箱苹果整整五十斤，大家都只是凭感觉。", "explanation": "这里应该用〈近〉。整整说明数目确切，而“大家都只是凭感觉”表示数目不确定，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整整", "is_correct": true, "explanation": "整整：副词，表示数量恰好足数，这里修饰“四十个同学”，与“一个不少”相合。"}, {"text": "大概", "is_correct": false, "explanation": "语义：“大概”表示估计，与“一个不少”的确切之意矛盾。"}, {"text": "差不多", "is_correct": false, "explanation": "语义：“差不多”表示接近，与“一个不少”的确切之意矛盾。"}, {"text": "约莫", "is_correct": false, "explanation": "语域：“约莫”带有口语或方言色彩，且同样是估计，与“一个不少”矛盾。"}], "explanations": {"整整": "整整：副词，表示数量恰好足数，这里修饰“四十个同学”，与“一个不少”相合。", "大概": "语义：“大概”表示估计，与“一个不少”的确切之意矛盾。", "差不多": "语义：“差不多”表示接近，与“一个不少”的确切之意矛盾。", "约莫": "语域：“约莫”带有口语或方言色彩，且同样是估计，与“一个不少”矛盾。"}, "sentence_index": 6, "correct_answer": "整整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这袋苹果整整五斤，我还没称过。", "explanation": "这里应该用〈差不多〉。“整整”说明数目确切，而“我还没称过”表示并未确定，两者矛盾。"}, {"text": "这堆书整整有二十本，我也说不准。", "explanation": "这里应该用〈大概〉。整整说明数目确切，而“我也说不准”表示数目不确定，两者矛盾。"}, {"text": "这箱苹果整整有五十斤，我是估的。", "explanation": "这里应该用〈大致〉。整整说明数目确切，而“我是估的”表示只是估算，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这袋大米整整了二十公斤，一点不多。", "corrected_sentence": "这袋大米整整二十公斤，一点不多。", "error_description": "错误：“了”插在了副词“整整”后面。“整整”是副词，不能直接带“了”；正确是“整整二十公斤”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批书整整了两百本，一本不少。", "corrected_sentence": "这批书整整两百本，一本不少。", "error_description": "错误：“了”放在了“整整”和“两百本”之间。“整整”是副词，不能带“了”；正确是“整整两百本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
