INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示达到某个数目，强调数量足或时间长。", "primary_collocate": null, "pronunciation": "zhěng zhěng", "ipa": "ʈʂəŋ˨˩˦ ʈʂəŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我在车站等了整整三个小时。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了整整一个星期的雨，天还没晴。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他整整睡了十二个小时才醒。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我想了整整一个晚上。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她学了整整五年汉语，说得很好。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家用了整整两天，大家都很累。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他整整哭了一个下午，谁也没办法。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市整整一个月没有下雨了。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做了整整一桌菜，大家吃得很开心。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架上整整三层都是他的书。", "target_word": "整整", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整整：强调时间长或数量足", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd5c4b2d-97ab-40df-bb81-bfbbee817b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整整", "is_correct": true, "explanation": "整整：副词，强调时间长，这里修饰“三个小时”，表示等得久。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示时间短、仅此而已，与“整整”强调时间长的意思相反。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示时间不长、仅此而已，与“整整”强调时间长的意思相反。"}, {"text": "差点", "is_correct": false, "explanation": "语法：“差点”表示几乎，不能直接修饰数量短语，且与“等了三个小时”的事实不合。"}], "explanations": {"整整": "整整：副词，强调时间长，这里修饰“三个小时”，表示等得久。", "才": "语义：“才”表示时间短、仅此而已，与“整整”强调时间长的意思相反。", "只": "语义：“只”表示时间不长、仅此而已，与“整整”强调时间长的意思相反。", "差点": "语法：“差点”表示几乎，不能直接修饰数量短语，且与“等了三个小时”的事实不合。"}, "sentence_index": 0, "correct_answer": "整整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一下子就想清楚了，整整用了一秒钟。", "explanation": "这里应该用〈才〉。“整整”强调时间长，而“一秒钟”极短，应说“才用了一秒钟”。"}, {"text": "他整整敲了一下门，没有人应。", "explanation": "这里应该用〈只〉。“整整”强调时间长，而“敲了一下”是很短的动作，应说“他只敲了一下门”。"}, {"text": "他整整赢了一次比赛，很高兴。", "explanation": "这里应该用〈仅〉。“整整”强调时长或数量充足，而“赢了一次”是单次事件，不能用“整整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整整", "is_correct": true, "explanation": "整整：副词，强调时间长，这里修饰“哭了一个下午”，与后句“谁也没办法”相合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“哭了一个下午”的长时段矛盾。"}, {"text": "很快", "is_correct": false, "explanation": "语义：“很快”表示速度快、时间短，与“哭了一个下午”的长时段矛盾。"}, {"text": "仅", "is_correct": false, "explanation": "语域：“仅”偏书面，口语中不用，且与后句的严重情形不合。"}], "explanations": {"整整": "整整：副词，强调时间长，这里修饰“哭了一个下午”，与后句“谁也没办法”相合。", "立刻": "语义：“立刻”表示马上，与“哭了一个下午”的长时段矛盾。", "很快": "语义：“很快”表示速度快、时间短，与“哭了一个下午”的长时段矛盾。", "仅": "语域：“仅”偏书面，口语中不用，且与后句的严重情形不合。"}, "sentence_index": 6, "correct_answer": "整整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他整整哭了一小会儿就停了。", "explanation": "这里应该用〈只〉。“整整”强调时间长，而“一小会儿”很短，应说“他只哭了一小会儿就停了”。"}, {"text": "他转眼就整整哭了一个下午。", "explanation": "这里应该用〈一会儿〉。“整整”强调时间很长，而“转眼”表示瞬间，两者矛盾；表示很短时间应说“哭了一会儿”。"}, {"text": "他整整两秒钟就把饭吃完了。", "explanation": "这里应该用〈才〉。“整整”强调时间长，而“两秒钟就把饭吃完”是极短时间，应说“他才两秒钟就把饭吃完了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们等了整整了两个小时，车还没来。", "corrected_sentence": "我们等了整整两个小时，车还没来。", "error_description": "错误：“了”放在了“整整”后面。“整整”是副词，修饰数量短语时不能带“了”；正确是“等了整整两个小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们很整整等了两个小时。", "corrected_sentence": "他们整整等了两个小时。", "error_description": "错误：“很”加在了副词“整整”前。“整整”是副词，不能被程度副词“很”修饰；正确是“他们整整等了两个小时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错", "is_correct": true, "explanation": "正确选项。“错”与“不错”表示“对、没错”的意思相对，是反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”表示明白、不模糊，与“对、没错”的意思没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境，与“对、没错”的意思没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧闹，与“对、没错”的意思没有反义关系。"}], "correct_answer": "错", "explanations": {"错": "正确选项。“错”与“不错”表示“对、没错”的意思相对，是反义关系。", "清楚": "“清楚”表示明白、不模糊，与“对、没错”的意思没有反义关系。", "安静": "“安静”形容声音或环境，与“对、没错”的意思没有反义关系。", "热闹": "“热闹”形容场面喧闹，与“对、没错”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错", "is_correct": true, "explanation": "正确选项。“错”与“不错”表示“对、没错”的意思相对，是反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与“对、没错”的意思没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“对、没错”的意思没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁，与“对、没错”的意思没有反义关系。"}], "correct_answer": "错", "explanations": {"错": "正确选项。“错”与“不错”表示“对、没错”的意思相对，是反义关系。", "明亮": "“明亮”形容光线充足或颜色鲜亮，与“对、没错”的意思没有反义关系。", "热情": "“热情”形容待人的态度，与“对、没错”的意思没有反义关系。", "干净": "“干净”形容清洁，与“对、没错”的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不错是对、没有错的意思，用来肯定别人的话或判断。", "primary_collocate": null, "pronunciation": "bú cuò", "ipa": "pu˧˥ tsʰuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "不错，今天确实是周五，你没记错。", "target_word": "不错", "complexity_tier": "T3", "furigana": "bú cuò, jīn tiān què shí shì zhōu wǔ, nǐ méi jì cuò.", "sentence_source": "generated"}, {"text": "不错，我就是你要找的王经理。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“我们现在出发吧？”“不错，就这么办。”", "target_word": "不错", "complexity_tier": "T3", "furigana": "wǒ men xiàn zài chū fā ba? bú cuò, jiù zhè me bàn.", "sentence_source": "generated"}, {"text": "不错，这正是我想说的意思。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“他是不是还在路上？”“不错，他刚发信息说堵车。”", "target_word": "不错", "complexity_tier": "T3", "furigana": "tā shì bu shì hái zài lù shang? bú cuò, tā gāng fā xìn xī shuō dǔ chē.", "sentence_source": "generated"}, {"text": "“学习要多练习吗？”“不错，老师也是这么说的。”", "target_word": "不错", "complexity_tier": "T3", "furigana": "xué xí yào duō liàn xí ma? bú cuò, lǎo shī yě shì zhè me shuō de.", "sentence_source": "generated"}, {"text": "“你是李老师的学生吗？”“不错，我是。”", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不错，这本书确实是我昨天买的。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“会议是三点开，对吧？”“不错，就是三点。”", "target_word": "不错", "complexity_tier": "T3", "furigana": "huì yì shì sān diǎn kāi, duì ba? bú cuò, jiù shì sān diǎn.", "sentence_source": "generated"}, {"text": "“他们是昨天到北京的吧？”“不错，昨天就到了。”", "target_word": "不错", "complexity_tier": "T3", "furigana": "tā men shì zuó tiān dào Běijīng de ba? bú cuò, zuó tiān jiù dào le.", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不错：表示对、没有错，用来肯定别人的话或判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50dfcc0b-fc77-441f-aa12-4c4358322b62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不错", "is_correct": true, "explanation": "正确选项。句首“不错”表示同意对方的判断，意思是“对、没错”，与后句“你没记错”呼应。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”用于称赞外貌或事物，不能用来同意对方说的日期。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或体积，无法用来回应“今天是周五”的判断。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指人的智力，不能用来回应一个日期判断。"}], "explanations": {"不错": "正确选项。句首“不错”表示同意对方的判断，意思是“对、没错”，与后句“你没记错”呼应。", "漂亮": "搭配：“漂亮”用于称赞外貌或事物，不能用来同意对方说的日期。", "高大": "体貌：“高大”形容身材或体积，无法用来回应“今天是周五”的判断。", "聪明": "语义：“聪明”指人的智力，不能用来回应一个日期判断。"}, "sentence_index": 0, "correct_answer": "不错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“你是李老师的学生吗？”“不错，我不是。”", "explanation": "这里“不错”表示“对、没错”，只能用来肯定。前面问“你是…吗”，后面却说“我不是”，前后矛盾；否定应说“不对”。"}, {"text": "“会议是三点开，对吧？”“很不错，就是三点。”", "explanation": "这里加了“很”，“很不错”变成称赞，不再表示肯定；肯定对方时应单独说“不错”，不能加“很”。"}, {"text": "“这份报告写完了吗？”“不错，还没写完。”", "explanation": "这里“不错”表示“对、没错”，只能用来肯定。前面问“写完了吗”，后面却说“还没写完”，前后矛盾；否定应说“没有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不错", "is_correct": true, "explanation": "正确选项。句首“不错”表示肯定，意思是“对、没错”，用来回答“你是……吗”。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，不能用来回答身份问题。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说年龄或时期，不能用来应答“是不是学生”。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”形容性格或样子，与身份判断无关。"}], "explanations": {"不错": "正确选项。句首“不错”表示肯定，意思是“对、没错”，用来回答“你是……吗”。", "温柔": "语义：“温柔”形容性情，不能用来回答身份问题。", "年轻": "搭配：“年轻”说年龄或时期，不能用来应答“是不是学生”。", "活泼": "语义：“活泼”形容性格或样子，与身份判断无关。"}, "sentence_index": 6, "correct_answer": "不错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“你昨天去哪儿了？”“不错，我去了图书馆。”", "explanation": "这里“不错”表示“对、没错”，只用于肯定对方的说法。问“去哪儿了”是问地点，应直接回答“我去了图书馆”，不能用“不错”。"}, {"text": "“她已经走了吗？”“不错，她还在办公室。”", "explanation": "这里“不错”表示肯定，但后面说“她还在办公室”，与“走了”相反，前后矛盾；否定应说“没有”。"}, {"text": "“请问这里是三号楼吗？”“不错，我们在一号楼。”", "explanation": "这里“不错”表示“对、没错”，用来肯定对方。后面却说“我们在一号楼”，与“三号楼”矛盾，应说“不是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“明天我们在图书馆见面吗？”“没不错，就这么定。”", "corrected_sentence": "“明天我们在图书馆见面吗？”“不错，就这么定。”", "error_description": "错误：“没不错”；正确：“不错”。“不错”作应答表示同意，前面不能加否定词“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“你是新来的老师吗？”“不错的，我是。”", "corrected_sentence": "“你是新来的老师吗？”“不错，我是。”", "error_description": "错误：“不错的”；正确：“不错”。作应答的“不错”是独立的词，后面不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "差", "is_correct": true, "explanation": "正确选项。“差”与“不错”（质量好、令人满意）是反义关系，表示质量不好。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”与“不错”都是正面评价，属于近义或同类，不是反义。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“不错”的评价义没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”说价格低，与“不错”的评价义没有反义关系。"}], "correct_answer": "差", "explanations": {"差": "正确选项。“差”与“不错”（质量好、令人满意）是反义关系，表示质量不好。", "漂亮": "“漂亮”与“不错”都是正面评价，属于近义或同类，不是反义。", "清楚": "“清楚”形容明白、不模糊，与“不错”的评价义没有反义关系。", "便宜": "“便宜”说价格低，与“不错”的评价义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糟糕", "is_correct": true, "explanation": "正确选项。“糟糕”表示情况很坏、令人不满意，与“不错”（令人满意）相对。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“不错”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境平静，与“不错”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁，与“不错”的评价义没有反义关系。"}], "correct_answer": "糟糕", "explanations": {"糟糕": "正确选项。“糟糕”表示情况很坏、令人不满意，与“不错”（令人满意）相对。", "热情": "“热情”形容待人的态度，与“不错”没有反义关系。", "安静": "“安静”形容声音或环境平静，与“不错”没有反义关系。", "干净": "“干净”形容清洁，与“不错”的评价义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好；不坏；表示称赞或认可。", "primary_collocate": null, "pronunciation": "bú cuò", "ipa": "pu˧˥ tsʰuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "这家饭馆的菜很不错。", "target_word": "不错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的成绩一直都不错。", "target_word": "不错", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天天气不错，我们去公园走走吧。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手机的拍照效果真不错。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的汉语说得真不错，学了几年了？", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得这个办法不错，可以试试。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作很努力，收入也不错。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服颜色不错，价格也不贵。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友推荐的那家酒店环境很不错，我们住了三天。", "target_word": "不错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试他考得不错，老师还表扬了他。", "target_word": "不错", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不错：形容事物或人好、令人满意，表示称赞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50dfcc0b-fc77-441f-aa12-4c4358322b62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不错", "is_correct": true, "explanation": "正确选项。“很不错”表示菜品好、令人满意，符合称赞的语境。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物体的身材、体积，不能用来评价菜的味道和质量。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指人的智力，菜没有智力，“菜很聪明”说不通。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄或事物的新旧时期，一般不用来形容菜的味道。"}], "explanations": {"不错": "正确选项。“很不错”表示菜品好、令人满意，符合称赞的语境。", "高大": "体貌：“高大”形容人或物体的身材、体积，不能用来评价菜的味道和质量。", "聪明": "语义：“聪明”指人的智力，菜没有智力，“菜很聪明”说不通。", "年轻": "搭配：“年轻”说人的年龄或事物的新旧时期，一般不用来形容菜的味道。"}, "sentence_index": 0, "correct_answer": "不错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种病毒的传播速度很不错，一个星期就感染了全城的人。", "explanation": "这里误把“不错”当成“严重”来用，描述病毒的危害，应说“严重”。“不错”只用于称赞好的事物。"}, {"text": "我们去年的销售额很不错，比前年减少了一半。", "explanation": "这里误把“不错”当成“糟糕”来用，描述销售额下降，应说“下降”。“不错”只能用来称赞好的情况。"}, {"text": "这次事故的损失很不错，大家都很满意。", "explanation": "“不错”只用来称赞好的事物。这里误把“不错”当成“严重”来用，描述事故损失应说“惨重”，不能用“不错”来称赞，句子意思正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不错", "is_correct": true, "explanation": "正确选项。“收入也不错”表示收入令人满意，与前句“工作很努力”的评价一致。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，收入没有性情，句子说不通。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”形容人的性格或样子，不能用来形容收入。"}, {"text": "懒惰", "is_correct": false, "explanation": "搭配：“懒惰”形容人的行为态度，不能说“收入懒惰”，句子说不通。"}], "explanations": {"不错": "正确选项。“收入也不错”表示收入令人满意，与前句“工作很努力”的评价一致。", "温柔": "语义：“温柔”形容性情，收入没有性情，句子说不通。", "活泼": "语义：“活泼”形容人的性格或样子，不能用来形容收入。", "懒惰": "搭配：“懒惰”形容人的行为态度，不能说“收入懒惰”，句子说不通。"}, "sentence_index": 6, "correct_answer": "不错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的感冒越来越不错，昨晚已经烧到四十度了。", "explanation": "这里误把“不错”用来形容病情。“不错”只用于称赞好的事物；前面说“越来越”，后面烧到四十度，病情在加重，应说“严重”。"}, {"text": "这份合同的条款很不错，对我们非常不利。", "explanation": "这里误把“不错”当成“有利”来用，合同对我们不利时应说“苛刻”。“不错”只用于称赞好的事物。"}, {"text": "这次手术失败了，医生说手术效果很不错。", "explanation": "这里误把“不错”当成“成功”来用，但前文说“失败”，应说“糟糕”。“不错”只用于称赞好的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的汉语学的不错。", "corrected_sentence": "他的汉语学得不错。", "error_description": "错误：“学的不错”；正确：“学得不错”。“不错”作补语，补语前要用“得”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的服务很很不错。", "corrected_sentence": "这家店的服务很不错。", "error_description": "错误：“很很不错”；正确：“很不错”。“很”只用一次，重复“很”不符合汉语习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
