INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在表演、体育等领域内有名气、受公众喜爱的人。", "primary_collocate": null, "pronunciation": "míng xīng", "ipa": "miŋ˧˥ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "他是我们国家最有名的足球明星。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位篮球明星每天训练六个小时。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育明星常常要接受采访。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位明星打网球的样子很帅。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻的明星拿了金牌。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位有名的舞蹈明星。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛后，明星们给球迷签名。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小学游泳，现在是游泳明星。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请来了一位乒乓球明星。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个明星的表演让观众很感动。", "target_word": "明星", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "体育明星", "label": "复合"}], "register": "中性", "sense_fingerprint": "表演、体育等领域有名气的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00e5633-a762-4029-b384-af5ebcd7e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球场", "is_correct": false, "explanation": "语义：“他是”之后须接人或身份，球场是场地，不能用来指人。"}, {"text": "球鞋", "is_correct": false, "explanation": "语义：球鞋是物品，不能指“他”这样的人。"}, {"text": "球票", "is_correct": false, "explanation": "语义：球票是票据，不能用来说一个人是什么。"}, {"text": "明星", "is_correct": true, "explanation": "“明星”是在体育领域有名气的人，与“最有名的足球”相符。"}], "explanations": {"球场": "语义：“他是”之后须接人或身份，球场是场地，不能用来指人。", "球鞋": "语义：球鞋是物品，不能指“他”这样的人。", "球票": "语义：球票是票据，不能用来说一个人是什么。", "明星": "“明星”是在体育领域有名气的人，与“最有名的足球”相符。"}, "sentence_index": 0, "correct_answer": "明星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把旧扫帚是明星，天天被人拿着在院子里扫地。", "explanation": "这里应该用〈工具〉。明星指人，扫帚是工具，不能这样称呼。"}, {"text": "这扇旧窗户是明星，每天都在电视里上镜。", "explanation": "这里应该用〈部件〉。明星指人，窗户是建筑部件，不能这样称呼。"}, {"text": "这位工人从没参加过任何比赛，也没有人认识他，却是一名明星。", "explanation": "这里应该用〈普通人〉。明星需要在表演、体育领域有名气，没人认识的人不能叫明星。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观众", "is_correct": false, "explanation": "语义：观众是看比赛的人，不是有名气、被签名的人，句意不符。"}, {"text": "记者", "is_correct": false, "explanation": "语义：记者一般不给球迷签名，这一句的语义说不通。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“老师”与“比赛后给球迷签名”的语境不搭配。"}, {"text": "明星", "is_correct": true, "explanation": "“明星”是有名气的运动员或艺人，比赛后给球迷签名符合常理。"}], "explanations": {"观众": "语义：观众是看比赛的人，不是有名气、被签名的人，句意不符。", "记者": "语义：记者一般不给球迷签名，这一句的语义说不通。", "老师": "搭配：“老师”与“比赛后给球迷签名”的语境不搭配。", "明星": "“明星”是有名气的运动员或艺人，比赛后给球迷签名符合常理。"}, "sentence_index": 6, "correct_answer": "明星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位明星每天在地里干活，从没上过舞台，也没参加过任何比赛。", "explanation": "这里应该用〈农民〉。农民在田里干活；明星指在表演、体育领域有名气的人，没上过舞台、没参加比赛的人不能叫明星。"}, {"text": "这位明星在图书馆里整理书籍，从不参加任何表演或比赛。", "explanation": "这里应该用〈图书管理员〉。整理书籍的是图书管理员；明星的领域是表演和体育，这份工作与之无关。"}, {"text": "这个人从来没有上过舞台，也没有人认识他，却是一名明星。", "explanation": "这里应该用〈路人〉。路人是街上的普通人，明星需要在表演、体育领域有名气，没人认识的人不能叫明星。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只明星每天训练六个小时。", "corrected_sentence": "这位明星每天训练六个小时。", "error_description": "量词错误：指人的“明星”应用“位”或“个”，不能用“只”。应为“这位明星”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们是两位体育明星们。", "corrected_sentence": "他们是两位体育明星。", "error_description": "词尾错误：“明星们”不能与数量词“两位”连用，数量短语后应直接说“明星”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ff0417-da32-4c3d-9bf6-c9ae69f91f29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
