INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87684, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写文章或创作作品的人。", "primary_collocate": null, "pronunciation": "zuò zhě", "ipa": "tswo˥˩ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本书的作者是一位老师。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者在书里写了自己的故事。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢这位作者写的小说。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的作者没有写名字。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读者想问作者一个问题。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位作者每天早上都写三个小时。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者写完书以后，找了出版社。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这首诗的作者，大家都认识他。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的封面上有作者的名字。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者用简单的话写了这个故事。", "target_word": "作者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "原作者", "label": "复合"}], "register": "中性", "sense_fingerprint": "写文章或创作作品的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac8ff967-745b-40e1-9201-f6f0972c5a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "作者", "is_correct": true, "explanation": "正确。作者（zuò zhě）指写文章或创作作品的人。"}, {"text": "坐着", "is_correct": false, "explanation": "zhe（轻声）与 zhě（第三声）声调不同，意思是“坐着”，指保持坐的姿势。"}, {"text": "做主", "is_correct": false, "explanation": "zhǔ 与 zhě 韵母不同（u 与 e），意思是“做主”，即替别人决定。"}, {"text": "坐车", "is_correct": false, "explanation": "chē 与 zhě 声母不同（ch 与 zh），声调也不同，意思是“坐车”，即乘车。"}], "explanations": {"作者": "正确。作者（zuò zhě）指写文章或创作作品的人。", "坐着": "zhe（轻声）与 zhě（第三声）声调不同，意思是“坐着”，指保持坐的姿势。", "做主": "zhǔ 与 zhě 韵母不同（u 与 e），意思是“做主”，即替别人决定。", "坐车": "chē 与 zhě 声母不同（ch 与 zh），声调也不同，意思是“坐车”，即乘车。"}, "sentence_index": null, "correct_answer": "作者"}, "level_3": {"options": [{"text": "作者", "is_correct": true, "explanation": "正确。“这本书的作者”指写这本书的人，可以是一位老师。"}, {"text": "封面", "is_correct": false, "explanation": "语义：封面是书的外皮，不是人，不能说它是一位老师。"}, {"text": "书名", "is_correct": false, "explanation": "搭配：“是一位老师”要求主语是人，书名不能是人。"}, {"text": "出版社", "is_correct": false, "explanation": "语义：出版社是机构，不是一个人，不能说它是一位老师。"}], "explanations": {"作者": "正确。“这本书的作者”指写这本书的人，可以是一位老师。", "封面": "语义：封面是书的外皮，不是人，不能说它是一位老师。", "书名": "搭配：“是一位老师”要求主语是人，书名不能是人。", "出版社": "语义：出版社是机构，不是一个人，不能说它是一位老师。"}, "sentence_index": 0, "correct_answer": "作者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位作者每天在厨房里炒菜，大家都说很好吃。", "explanation": "这里应该用〈厨师〉。作者指写作的人，在厨房炒菜的人要说厨师。"}, {"text": "我每天都是这家书店的作者，常常来这里买书。", "explanation": "这里应该用〈读者〉。作者是写作品的人，常来书店买书的是读者。"}, {"text": "这幅画是他最得意的作者。", "explanation": "这里应该用〈作品〉。作者指写作的人，画是作品，不能说画是作者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87684, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "作者", "is_correct": true, "explanation": "正确。作者（zuò zhě）指写文章或创作作品的人。"}, {"text": "做着", "is_correct": false, "explanation": "zhe（轻声）与 zhě（第三声）声调不同，意思是“做着”，即正在做。"}, {"text": "坐直", "is_correct": false, "explanation": "zhí 与 zhě 韵母不同（i 与 e），意思是“坐直”，即身体挺直地坐。"}, {"text": "坐诊", "is_correct": false, "explanation": "zhěn 与 zhě 韵母不同（en 与 e），意思是“坐诊”，即坐在诊室里给病人看病。"}], "explanations": {"作者": "正确。作者（zuò zhě）指写文章或创作作品的人。", "做着": "zhe（轻声）与 zhě（第三声）声调不同，意思是“做着”，即正在做。", "坐直": "zhí 与 zhě 韵母不同（i 与 e），意思是“坐直”，即身体挺直地坐。", "坐诊": "zhěn 与 zhě 韵母不同（en 与 e），意思是“坐诊”，即坐在诊室里给病人看病。"}, "sentence_index": null, "correct_answer": "作者"}, "level_3": {"options": [{"text": "作者", "is_correct": true, "explanation": "正确。“作者写完书以后”指写书的人，写完书后去找出版社。"}, {"text": "读者", "is_correct": false, "explanation": "语义：读者是读书的人，不写书，所以“读者写完书”不成立。"}, {"text": "书架", "is_correct": false, "explanation": "配价：“写完书”需要能写的人作主语，书架不能写书。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“写完书”需要能写的人作主语，桌子不能写书。"}], "explanations": {"作者": "正确。“作者写完书以后”指写书的人，写完书后去找出版社。", "读者": "语义：读者是读书的人，不写书，所以“读者写完书”不成立。", "书架": "配价：“写完书”需要能写的人作主语，书架不能写书。", "桌子": "配价：“写完书”需要能写的人作主语，桌子不能写书。"}, "sentence_index": 6, "correct_answer": "作者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位作者做的红烧肉很好吃。", "explanation": "这里应该用〈厨师〉。作者指写作的人，做菜的人要说厨师。"}, {"text": "这位作者每天给很多病人看病。", "explanation": "这里应该用〈医生〉。作者指写作的人，给病人看病的人要说医生。"}, {"text": "这位作者每天开车上班。", "explanation": "这里应该用〈司机〉。作者指写作的人，开车的人要说司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本作者的新书很受欢迎。", "corrected_sentence": "这位作者的新书很受欢迎。", "error_description": "量词错误：“作者”指人，应用“位”，“本”用于书籍，“这本作者”应改为“这位作者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌的作者是哪一本？", "corrected_sentence": "这首歌的作者是哪一位？", "error_description": "量词错误：“作者”指人，应用“位”，“本”用于书，“哪一本”应改为“哪一位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
