INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87691, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "过去当面称呼别人时用的称呼，多用于不熟悉的人，可加在姓后或单独使用。", "primary_collocate": null, "pronunciation": "tóng zhì", "ipa": "tʰʊŋ˧˥ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "同志，请问去火车站怎么走？", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同志，您的包忘在车上了。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同志，这里不能停车。", "target_word": "同志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "张同志，请您先坐这里。", "target_word": "同志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "李同志，会议室在二楼。", "target_word": "同志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那位同志，请把门关一下。", "target_word": "同志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我说：“同志，谢谢你帮忙。”", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同志，这是你要的材料。", "target_word": "同志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "王同志，你的电话来了。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同志，请排队，不要着急。", "target_word": "同志", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "同志们", "label": "复数"}, {"form": "同誌", "label": "繁体"}], "register": "正式", "sense_fingerprint": "同志：当面称呼别人的用语，常加在姓后或单独使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50dfcc0b-fc77-441f-aa12-4c4358322b62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87691, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同志", "is_correct": true, "explanation": "正确答案：同志（tóng zhì），这里指当面称呼别人的用语。"}, {"text": "同事", "is_correct": false, "explanation": "shì（第四声）与 zhì（第四声）的声母不同（sh 与 zh），意思是同事。"}, {"text": "同时", "is_correct": false, "explanation": "shí（第二声）与 zhì（第四声）的声母和声调都不同，意思是同时。"}, {"text": "通知", "is_correct": false, "explanation": "tōng（第一声）与 tóng 声调不同，zhī（第一声）与 zhì 声调不同，意思是通知。"}], "explanations": {"同志": "正确答案：同志（tóng zhì），这里指当面称呼别人的用语。", "同事": "shì（第四声）与 zhì（第四声）的声母不同（sh 与 zh），意思是同事。", "同时": "shí（第二声）与 zhì（第四声）的声母和声调都不同，意思是同时。", "通知": "tōng（第一声）与 tóng 声调不同，zhī（第一声）与 zhì 声调不同，意思是通知。"}, "sentence_index": null, "correct_answer": "同志"}, "level_3": {"options": [{"text": "同志", "is_correct": true, "explanation": "正确：这里是当面称呼陌生人的用法，与“请问去火车站怎么走”相符。"}, {"text": "老婆", "is_correct": false, "explanation": "语义：“老婆”指配偶，不用来称呼陌生人问路。"}, {"text": "宝贝", "is_correct": false, "explanation": "语域：“宝贝”是亲昵称呼，不用于礼貌地向陌生人问路。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”是贬义的人称，与礼貌问路的语境不合。"}], "explanations": {"同志": "正确：这里是当面称呼陌生人的用法，与“请问去火车站怎么走”相符。", "老婆": "语义：“老婆”指配偶，不用来称呼陌生人问路。", "宝贝": "语域：“宝贝”是亲昵称呼，不用于礼貌地向陌生人问路。", "小偷": "语义：“小偷”是贬义的人称，与礼貌问路的语境不合。"}, "sentence_index": 0, "correct_answer": "同志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子，同志，你的书掉在地上了。", "explanation": "这里应该用〈小朋友〉。同志用于彼此称呼一起做事的成年人，不用于称呼小孩子。"}, {"text": "我们住在同一栋楼里，是很好的同志。", "explanation": "这里应该用〈邻居〉。同志用于称呼或指一起做事的人，不用于仅仅住在同一栋楼的人。"}, {"text": "我和他是老相识，一起长大的同志。", "explanation": "这里应该用〈发小〉。同志用于称呼一起做事的人，不用于指童年的玩伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87691, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同志", "is_correct": true, "explanation": "正确答案：同志（tóng zhì），这里指当面称呼别人的用语。"}, {"text": "同室", "is_correct": false, "explanation": "shì（第四声）与 zhì（第四声）的声母不同（sh 与 zh），意思是同一个房间。"}, {"text": "童子", "is_correct": false, "explanation": "zǐ（第三声）与 zhì（第四声）的声母和声调都不同（z 与 zh），意思是儿童。"}, {"text": "统治", "is_correct": false, "explanation": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统治。"}], "explanations": {"同志": "正确答案：同志（tóng zhì），这里指当面称呼别人的用语。", "同室": "shì（第四声）与 zhì（第四声）的声母不同（sh 与 zh），意思是同一个房间。", "童子": "zǐ（第三声）与 zhì（第四声）的声母和声调都不同（z 与 zh），意思是儿童。", "统治": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统治。"}, "sentence_index": null, "correct_answer": "同志"}, "level_3": {"options": [{"text": "同志", "is_correct": true, "explanation": "正确：这里是称呼对方的用语，与“谢谢你帮忙”的语境相符。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：“仇人”与向对方道谢的语气矛盾。"}, {"text": "劫匪", "is_correct": false, "explanation": "语义：“劫匪”指抢劫的人，与道谢的语境不符。"}, {"text": "胖子", "is_correct": false, "explanation": "体貌：“胖子”描述体型，用来称呼对方并道谢，语气失礼，与句意不合。"}], "explanations": {"同志": "正确：这里是称呼对方的用语，与“谢谢你帮忙”的语境相符。", "仇人": "语义：“仇人”与向对方道谢的语气矛盾。", "劫匪": "语义：“劫匪”指抢劫的人，与道谢的语境不符。", "胖子": "体貌：“胖子”描述体型，用来称呼对方并道谢，语气失礼，与句意不合。"}, "sentence_index": 6, "correct_answer": "同志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑是我的同志，我每天都用它。", "explanation": "这里应该用〈帮手〉。同志指人，不能用来指物品。"}, {"text": "妈妈对儿子说：同志，把碗洗了。", "explanation": "这里应该用〈孩子〉。同志是称呼一起做事的人，不用于父母称呼自己的儿子。"}, {"text": "那两个同志在门口望风，是来帮忙的。", "explanation": "这里应该用〈同伙〉。同志指志向、目标一致的人，不用于一起做坏事的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面那只同志，请稍等一下。", "corrected_sentence": "前面那位同志，请稍等一下。", "error_description": "错误：量词。称呼人的“同志”应用量词“位”，应说“那位同志”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "张同志们，请您把东西拿好。", "corrected_sentence": "张同志，请您把东西拿好。", "error_description": "错误：复数标记“们”。称呼单个人时用“同志”，应说“张同志”，不能加“们”说“张同志们”；“同志们”只用于称呼一群人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
