INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "志同道合的人；过去也用作对人的称呼。", "primary_collocate": null, "pronunciation": "tóng zhì", "ipa": "tʰʊŋ˧˥ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他们是为同一个目标工作的同志。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在工作中，我们都是好同志。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几位同志在工作中互相帮助，很有团队精神。", "target_word": "同志", "complexity_tier": "T3", "furigana": "zhè jǐ wèi tóngzhì zài gōngzuò zhōng hùxiāng bāngzhù, hěn yǒu tuánduì jīngshén.", "sentence_source": "generated"}, {"text": "他找到了几位同志一起做研究。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位同志工作认真，大家都信任他。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同志们，今天的会就开到这里。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一位值得我们学习的同志。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了同一件事，我们成了同志。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把我当成同志，什么都愿意告诉我。", "target_word": "同志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张和我在一个单位，也是好同志。", "target_word": "同志", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "同志们", "label": "复数"}, {"form": "同誌", "label": "繁体"}], "register": "正式", "sense_fingerprint": "同志：志向、目标相同，一起做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50dfcc0b-fc77-441f-aa12-4c4358322b62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87692, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同志", "is_correct": true, "explanation": "正确答案：同志（tóng zhì），指志同道合、一起做事的人。"}, {"text": "童子", "is_correct": false, "explanation": "zǐ（第三声）与 zhì（第四声）的声母和声调都不同（z 与 zh），意思是儿童。"}, {"text": "同时", "is_correct": false, "explanation": "shí（第二声）与 zhì（第四声）的声母和声调都不同，意思是同时。"}, {"text": "统治", "is_correct": false, "explanation": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统治。"}, {"text": "通知", "is_correct": false, "explanation": "tōng（第一声）与 tóng 声调不同，zhī（第一声）与 zhì 声调不同，意思是通知。"}], "explanations": {"同志": "正确答案：同志（tóng zhì），指志同道合、一起做事的人。", "童子": "zǐ（第三声）与 zhì（第四声）的声母和声调都不同（z 与 zh），意思是儿童。", "同时": "shí（第二声）与 zhì（第四声）的声母和声调都不同，意思是同时。", "统治": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统治。", "通知": "tōng（第一声）与 tóng 声调不同，zhī（第一声）与 zhì 声调不同，意思是通知。"}, "sentence_index": null, "correct_answer": "同志"}, "level_3": {"options": [{"text": "同志", "is_correct": true, "explanation": "正确：“同志”指志向、目标一致、一起做事的人，与“为同一个目标工作”相符。"}, {"text": "对手", "is_correct": false, "explanation": "语义：“对手”指相互竞争的人，与“为同一个目标工作”的意思相反。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“敌人”与“为同一个目标工作”的人正好对立，句子不通。"}, {"text": "老板", "is_correct": false, "explanation": "配价：“老板”是雇用、指挥别人的人，不是与人并肩为同一目标工作的人。"}], "explanations": {"同志": "正确：“同志”指志向、目标一致、一起做事的人，与“为同一个目标工作”相符。", "对手": "语义：“对手”指相互竞争的人，与“为同一个目标工作”的意思相反。", "敌人": "语义：“敌人”与“为同一个目标工作”的人正好对立，句子不通。", "老板": "配价：“老板”是雇用、指挥别人的人，不是与人并肩为同一目标工作的人。"}, "sentence_index": 0, "correct_answer": "同志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我大学的同志。", "explanation": "这里应该用〈同学〉。同志指志向、目标一致、一起做事的人；一起读书的人应说同学。"}, {"text": "我们住在同一个小区，是很好的同志。", "explanation": "这里应该用〈邻居〉。同志指志向、目标一致、一起做事的人，只是住得近不能说同志。"}, {"text": "他是我的亲弟弟，我们是很好的同志。", "explanation": "这里应该用〈兄弟〉。同志指志向、目标一致、一起做事的人，不用于有血缘关系的亲人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87692, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同志", "is_correct": true, "explanation": "正确答案：同志（tóng zhì），指志同道合的人。"}, {"text": "同室", "is_correct": false, "explanation": "shì（第四声）与 zhì（第四声）的声母不同（sh 与 zh），意思是同一个房间。"}, {"text": "童子", "is_correct": false, "explanation": "zǐ（第三声）与 zhì（第四声）的声母和声调都不同（z 与 zh），意思是儿童。"}, {"text": "统制", "is_correct": false, "explanation": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统一管制。"}], "explanations": {"同志": "正确答案：同志（tóng zhì），指志同道合的人。", "同室": "shì（第四声）与 zhì（第四声）的声母不同（sh 与 zh），意思是同一个房间。", "童子": "zǐ（第三声）与 zhì（第四声）的声母和声调都不同（z 与 zh），意思是儿童。", "统制": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统一管制。"}, "sentence_index": null, "correct_answer": "同志"}, "level_3": {"options": [{"text": "同志", "is_correct": true, "explanation": "正确：“同志”指值得学习的志同道合者，与句中的评价相符。"}, {"text": "坏蛋", "is_correct": false, "explanation": "语义：“坏蛋”是坏人，与“值得我们学习”的评价矛盾。"}, {"text": "骗子", "is_correct": false, "explanation": "语义：“骗子”指欺骗别人的人，与“值得我们学习”的评价矛盾。"}, {"text": "懒虫", "is_correct": false, "explanation": "语域：“懒虫”是口语戏称，与这句正式的评价语气不合，且意思与“值得学习”相反。"}], "explanations": {"同志": "正确：“同志”指值得学习的志同道合者，与句中的评价相符。", "坏蛋": "语义：“坏蛋”是坏人，与“值得我们学习”的评价矛盾。", "骗子": "语义：“骗子”指欺骗别人的人，与“值得我们学习”的评价矛盾。", "懒虫": "语域：“懒虫”是口语戏称，与这句正式的评价语气不合，且意思与“值得学习”相反。"}, "sentence_index": 6, "correct_answer": "同志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们是抢劫的同志。", "explanation": "这里应该用〈同伙〉。同志指志向、目标一致的人，不用于一起做坏事的人。"}, {"text": "我和他是同志，都是做餐厅生意的。", "explanation": "这里应该用〈同行〉。同行指同一行业的人；同志表示志向一致、一起做事，不用于仅仅同业的人。"}, {"text": "他们在比赛中是同志，互不相让。", "explanation": "这里应该用〈对手〉。同志指志向一致、彼此合作的人，不用于竞争关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们部门有三只同志负责这个项目。", "corrected_sentence": "我们部门有三位同志负责这个项目。", "error_description": "错误：量词。“同志”指人，应用量词“位”，应说“三位同志”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们三个同志们都来了。", "corrected_sentence": "我们三个同志都来了。", "error_description": "错误：复数标记“们”。有“三个”这样的数量词时不再加“们”，应说“三个同志”，不能说“三个同志们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
