INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87707, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87707, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在形容词前，表示程度很深，相当于“非常”。", "primary_collocate": null, "pronunciation": "hǎo bù", "ipa": "xau̯˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "过年的时候，街上好不热闹。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考上大学，家里人好不高兴。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见孩子们在雪地里玩，老人好不快活。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三十多个人挤在一间小屋里，好不拥挤。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着新衣服在大家面前走来走去，好不得意。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了三天大雨，路上的行人好不狼狈。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次离开家，妈妈心里好不难过。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明天要去旅行，孩子们好不兴奋。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人住在山里，晚上好不冷清。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着大马走在队伍前面，好不威风。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "好不+形容词：强调程度很深，意思是非常", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 人住 (Zipf 3.36), 山里 (Zipf 3.64), 冷清 (Zipf 3.23)','sentence 9 above tier T1: 3 words above tier T1 (max 2): 骑着 (Zipf 3.21), 大马 (Zipf 3.54), 威风 (Zipf 3.27)']::text[], '410cbcc6-88e5-4dbf-9766-d970c97f3598') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87707, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好不", "is_correct": true, "explanation": "好不 hǎo bù，副词，表示程度很深，意思是非常。"}, {"text": "毫不", "is_correct": false, "explanation": "háo（第二声）与 hǎo（第三声）声调不同，毫不意思是一点也不，是否定用法。"}, {"text": "好处", "is_correct": false, "explanation": "chù 与 bù 声母不同（ch 与 b），好处意思是益处，是名词。"}, {"text": "好物", "is_correct": false, "explanation": "wù 与 bù 声母不同（w 与 b），好物意思是好东西。"}, {"text": "好路", "is_correct": false, "explanation": "lù 与 bù 声母不同（l 与 b），好路意思是好走的路。"}], "explanations": {"好不": "好不 hǎo bù，副词，表示程度很深，意思是非常。", "毫不": "háo（第二声）与 hǎo（第三声）声调不同，毫不意思是一点也不，是否定用法。", "好处": "chù 与 bù 声母不同（ch 与 b），好处意思是益处，是名词。", "好物": "wù 与 bù 声母不同（w 与 b），好物意思是好东西。", "好路": "lù 与 bù 声母不同（l 与 b），好路意思是好走的路。"}, "sentence_index": null, "correct_answer": "好不"}, "level_3": {"options": [{"text": "好不", "is_correct": true, "explanation": "好不表示程度很深，与“热闹”搭配，符合过年时街上的气氛。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不热闹”与“过年的时候”的热闹气氛相矛盾。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有可以转折的前文，句意不通。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”需与否定词连用，不能直接修饰肯定的“热闹”。"}], "explanations": {"好不": "好不表示程度很深，与“热闹”搭配，符合过年时街上的气氛。", "不": "语义：“不热闹”与“过年的时候”的热闹气氛相矛盾。", "却": "语义：“却”表示转折，句中没有可以转折的前文，句意不通。", "从来": "搭配：“从来”需与否定词连用，不能直接修饰肯定的“热闹”。"}, "sentence_index": 0, "correct_answer": "好不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他好不容易才把作业做完，大家都很惊讶。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}, {"text": "他好不容易才找到钥匙。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}, {"text": "这次考试好不容易才及格。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好不", "is_correct": true, "explanation": "好不表示程度很深，与“难过”搭配，符合孩子第一次离开家时妈妈的心情。"}, {"text": "从不", "is_correct": false, "explanation": "搭配：“从不”多与习惯性动作搭配，不与“难过”这类情感状态搭配。"}, {"text": "毫不", "is_correct": false, "explanation": "语义：“毫不”表示一点也不，与“妈妈心里难过”的意思正相反。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与预期相反或故意如此，句中没有这样的前提。"}], "explanations": {"好不": "好不表示程度很深，与“难过”搭配，符合孩子第一次离开家时妈妈的心情。", "从不": "搭配：“从不”多与习惯性动作搭配，不与“难过”这类情感状态搭配。", "毫不": "语义：“毫不”表示一点也不，与“妈妈心里难过”的意思正相反。", "偏偏": "语义：“偏偏”表示与预期相反或故意如此，句中没有这样的前提。"}, "sentence_index": 6, "correct_answer": "好不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的感冒好不了，已经两周了。", "explanation": "这里是另一个词“好不了”，表示病无法痊愈，不是表示程度的“好不”。"}, {"text": "这次比赛好不容易才结束。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}, {"text": "我好不容易才借到那本书。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪下了一整天，屋里好不的暖和。", "corrected_sentence": "雪下了一整天，屋里好不暖和。", "error_description": "错误形式是“好不的暖和”，正确形式是“好不暖和”。“好不”是程度副词，直接修饰形容词，中间不能加“的”，应删去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人在家，屋子里好不很安静。", "corrected_sentence": "他一个人在家，屋子里好不安静。", "error_description": "“好不”本身已经表示程度很深，不能再与“很”连用，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
