INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87708, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在某些形容词前，表示程度很深。", "primary_collocate": null, "pronunciation": "hǎo bù", "ipa": "xau̯˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "新年到了，大家好不开心。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在外地工作，好不辛苦。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个好消息，全家人好不欢喜。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的花园里，鸟儿唱着歌，好不快活。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明丢了新书包，好不着急。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的老街没有一个人，好不凄凉。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赢了比赛，站在台上好不神气。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里放风筝，好不快乐。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出新手机，同学们看着，好不惊奇。", "target_word": "好不", "complexity_tier": "T3", "furigana": "tā ná chū xīn shǒu jī， tóng xué men kàn zhe， hǎo bù jīng qí。", "sentence_source": "generated"}, {"text": "第一次上台讲话，他心里好不紧张。", "target_word": "好不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，置于某些形容词前，表示程度很深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 花园里 (Zipf 3.19), 鸟儿 (Zipf 3.55), 快活 (Zipf 3.5)','sentence 4 above tier T1: 3 words above tier T1 (max 2): 小明 (Zipf 3.37), 书包 (Zipf 3.62), 着急 (Zipf 3.93)','sentence 5 above tier T1: 3 words above tier T1 (max 2): 夜里 (Zipf 3.96), 老街 (Zipf 3.29), 凄凉 (Zipf 3.32)']::text[], '410cbcc6-88e5-4dbf-9766-d970c97f3598') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87708, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好不", "is_correct": true, "explanation": "好不 hǎo bù，副词，用在形容词前，表示程度很深，意思是非常。"}, {"text": "毫不", "is_correct": false, "explanation": "háo（第二声）与 hǎo（第三声）声调不同，毫不意思是一点也不，是否定用法。"}, {"text": "好处", "is_correct": false, "explanation": "chù 与 bù 声母不同（ch 与 b），好处意思是益处，是名词。"}, {"text": "好物", "is_correct": false, "explanation": "wù 与 bù 声母不同（w 与 b），好物意思是好东西。"}, {"text": "好路", "is_correct": false, "explanation": "lù 与 bù 声母不同（l 与 b），好路意思是好走的路。"}], "explanations": {"好不": "好不 hǎo bù，副词，用在形容词前，表示程度很深，意思是非常。", "毫不": "háo（第二声）与 hǎo（第三声）声调不同，毫不意思是一点也不，是否定用法。", "好处": "chù 与 bù 声母不同（ch 与 b），好处意思是益处，是名词。", "好物": "wù 与 bù 声母不同（w 与 b），好物意思是好东西。", "好路": "lù 与 bù 声母不同（l 与 b），好路意思是好走的路。"}, "sentence_index": null, "correct_answer": "好不"}, "level_3": {"options": [{"text": "好不", "is_correct": true, "explanation": "好不表示程度很深，与“开心”搭配，符合新年的喜庆气氛。"}, {"text": "从不", "is_correct": false, "explanation": "搭配：“从不”多与习惯性动作搭配，不与“开心”这类情感状态搭配。"}, {"text": "毫不", "is_correct": false, "explanation": "语义：“毫不开心”与“新年到了”的喜庆气氛相反。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有可以转折的前文，句意不通。"}], "explanations": {"好不": "好不表示程度很深，与“开心”搭配，符合新年的喜庆气氛。", "从不": "搭配：“从不”多与习惯性动作搭配，不与“开心”这类情感状态搭配。", "毫不": "语义：“毫不开心”与“新年到了”的喜庆气氛相反。", "却": "语义：“却”表示转折，句中没有可以转折的前文，句意不通。"}, "sentence_index": 0, "correct_answer": "好不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他好不容易才吃上一顿热饭。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}, {"text": "妈妈好不容易才把孩子哄睡。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}, {"text": "他好不容易才把题目做完。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好不", "is_correct": true, "explanation": "好不表示程度很深，与“神气”搭配，符合他赢了比赛后站在台上的样子。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”需与否定词连用，不能直接修饰肯定的“神气”。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”表示徒然，与“赢了比赛”的结果相矛盾。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与预期相反，而赢了比赛后神气是符合预期的，句中没有相反的前提。"}], "explanations": {"好不": "好不表示程度很深，与“神气”搭配，符合他赢了比赛后站在台上的样子。", "从来": "搭配：“从来”需与否定词连用，不能直接修饰肯定的“神气”。", "白": "语义：“白”表示徒然，与“赢了比赛”的结果相矛盾。", "偏偏": "语义：“偏偏”表示与预期相反，而赢了比赛后神气是符合预期的，句中没有相反的前提。"}, "sentence_index": 6, "correct_answer": "好不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他好不容易才找到那本书。", "explanation": "这里是固定词组“好不容易”，表示费了很大力气才（终于），不是表示程度很深的“好不”。"}, {"text": "他的病好不了，已经三天了。", "explanation": "这里是另一个词“好不了”，表示病无法痊愈，不是表示程度的“好不”。"}, {"text": "这台电脑好不了，只能换新的。", "explanation": "这里是另一个词“好不了”，表示无法修好、无法好转，不是表示程度很深的“好不”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他第一次一个人过节，好不的寂寞。", "corrected_sentence": "他第一次一个人过节，好不寂寞。", "error_description": "错误形式是“好不的寂寞”，正确形式是“好不寂寞”。“好不”是程度副词，直接修饰形容词，中间不能加“的”，应删去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天的公园里，好不很热闹。", "corrected_sentence": "春天的公园里，好不热闹。", "error_description": "“好不”本身已经表示程度很深，不能再与“很”连用，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
