INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古代君主制国家的最高统治者。", "primary_collocate": null, "pronunciation": "huáng dì", "ipa": "xwɑŋ˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "秦始皇是中国的第一个皇帝。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝是古代国家最高的统治者。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个王朝一共出过十位皇帝。", "target_word": "皇帝", "complexity_tier": "T3", "furigana": "zhè ge wáng cháo yí gòng chū guo shí wèi huáng dì", "sentence_source": "generated"}, {"text": "十岁的太子登上皇位，成了新皇帝。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝死后，太子成为新的君主。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上写着很多皇帝的故事。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清朝的皇帝住在北京的故宫里。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝通过大臣管理整个国家。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一九一二年，中国最后一位皇帝退位了。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢历史，常读皇帝的传记。", "target_word": "皇帝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "末代皇帝", "label": "复合"}], "register": "书面", "sense_fingerprint": "古代君主制国家的最高统治者，王朝的君主", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2629cfaa-ecb6-48f0-80ae-066a0850e85a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皇帝", "is_correct": true, "explanation": "“皇帝”指古代君主制国家的最高统治者，与“第一个”搭配，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：秦始皇是人，不能是桌子。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：秦始皇是人，不能是窗户。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：秦始皇是统治者，不是厨师。"}], "explanations": {"皇帝": "“皇帝”指古代君主制国家的最高统治者，与“第一个”搭配，符合句意。", "桌子": "语义：秦始皇是人，不能是桌子。", "窗户": "语义：秦始皇是人，不能是窗户。", "厨师": "语义：秦始皇是统治者，不是厨师。"}, "sentence_index": 0, "correct_answer": "皇帝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "紫禁城里住着一把皇帝。", "explanation": "这里应该用〈位〉。“把”用于有柄的物件，指人不能用“把”。"}, {"text": "英国的皇帝住在白金汉宫里。", "explanation": "这里应该用〈国王〉。白金汉宫是英国君主的住所，英国君主称国王或女王，不称皇帝。"}, {"text": "这座城市的皇帝由市民选举产生。", "explanation": "这里应该用〈市长〉。皇帝是世袭的君主，不经选举产生；城市的行政首长是市长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皇帝", "is_correct": true, "explanation": "“皇帝”指君主，清朝皇帝住在北京的故宫里符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“住”要求有生命的主语，石头不能住。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：清朝没有汽车，与句中的时代不合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：清朝没有电脑，与句中的时代不合。"}], "explanations": {"皇帝": "“皇帝”指君主，清朝皇帝住在北京的故宫里符合语境。", "石头": "配价：“住”要求有生命的主语，石头不能住。", "汽车": "语义：清朝没有汽车，与句中的时代不合。", "电脑": "语义：清朝没有电脑，与句中的时代不合。"}, "sentence_index": 6, "correct_answer": "皇帝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个王国的皇帝由议会选出，任期五年。", "explanation": "这里应该用〈首相〉。皇帝是君主，不由议会选出；由议会选出的行政首长是首相。"}, {"text": "这个国家的皇帝每年都要向议会报告工作。", "explanation": "这里应该用〈总理〉。皇帝不向议会报告；向议会报告工作的是政府首脑，称总理。"}, {"text": "这个民主国家的皇帝不能世袭，只能通过选举产生。", "explanation": "这里应该用〈总统〉。皇帝是世袭的君主；经选举产生的国家元首称总统。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他十岁就当了上皇帝。", "corrected_sentence": "他十岁就当上了皇帝。", "error_description": "错误：结果补语“上”应紧跟动词“当”，“了”应放在“当上”之后，应说“当上了皇帝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
