INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "委员会的成员；被选出或任命来参加某委员会工作的人。", "primary_collocate": null, "pronunciation": "wěi yuán", "ipa": "wei̯˨˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他是我们学校新选出的委员。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位委员在会上提出了一个好办法。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生被任命为这个小组的委员。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每位委员都要在会上说说自己的看法。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，委员们先看了一遍材料。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "委员们一致同意了这个计划。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当选为市政协的委员，工作很忙。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会一共有九位委员，今天来了八位。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老委员已经工作了二十年。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三位委员不同意，计划没有通过。", "target_word": "委员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位委员", "label": "量词"}, {"form": "委员会", "label": "复合"}, {"form": "委员长", "label": "复合"}], "register": "中性", "sense_fingerprint": "委员会的成员，被选出或任命参加工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410cbcc6-88e5-4dbf-9766-d970c97f3598') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "委员", "is_correct": true, "explanation": "委员指委员会的成员，可以被选出，与“选出”搭配，符合句意。"}, {"text": "委员会", "is_correct": false, "explanation": "搭配：“委员会”指机构，“他是……的”后要接指人的名词，不能这样搭配。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“新选出的”与“小偷”相矛盾，没有人会被选为小偷。"}, {"text": "校车", "is_correct": false, "explanation": "语义：校车是交通工具，不是人，不能被选出做委员。"}], "explanations": {"委员": "委员指委员会的成员，可以被选出，与“选出”搭配，符合句意。", "委员会": "搭配：“委员会”指机构，“他是……的”后要接指人的名词，不能这样搭配。", "小偷": "语义：“新选出的”与“小偷”相矛盾，没有人会被选为小偷。", "校车": "语义：校车是交通工具，不是人，不能被选出做委员。"}, "sentence_index": 0, "correct_answer": "委员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班新买了一个委员，用来放书。", "explanation": "“委员”指人，不能指家具；这里应该用〈书架〉。"}, {"text": "我们在委员里讨论了这个计划。", "explanation": "这里应该用〈委员会〉。“委员”指人，指机构要用“委员会”，不能说“在委员里讨论”。"}, {"text": "这支球队的委员很努力训练。", "explanation": "这里应该用〈球员〉。“委员”指参加委员会工作的人，不能指球队里训练的运动员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "委员", "is_correct": true, "explanation": "委员指委员会的成员，与“当选为”搭配，符合句意。"}, {"text": "候选人", "is_correct": false, "explanation": "搭配：“当选为”后接职务，“候选人”不是职务，句中“当选”与“候选人”不搭配。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物品，不能当选，也不能担任委员。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，与“当选为”的人物语境不符。"}], "explanations": {"委员": "委员指委员会的成员，与“当选为”搭配，符合句意。", "候选人": "搭配：“当选为”后接职务，“候选人”不是职务，句中“当选”与“候选人”不搭配。", "窗户": "语义：窗户是物品，不能当选，也不能担任委员。", "眼镜": "语义：眼镜是物品，与“当选为”的人物语境不符。"}, "sentence_index": 6, "correct_answer": "委员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的小狗是班里的委员。", "explanation": "“委员”指有职务的人，不能用来指动物。"}, {"text": "他的委员又大又软，躺着很舒服。", "explanation": "“委员”指人，不能指枕头这类物品，这里应该用〈枕头〉。"}, {"text": "我在委员下面坐着。", "explanation": "“委员”指人，不能当处所名词用；这里应该用〈桌子〉之类的处所名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校委员会里有一只委员提出了建议。", "corrected_sentence": "学校委员会里有一位委员提出了建议。", "error_description": "错误是量词“只”，正确是“位”。“委员”指人，应该用人的量词“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们那个委员会有五位委员们。", "corrected_sentence": "他们那个委员会有五位委员。", "error_description": "错误是在“五位委员”后又加了复数后缀“们”。数量词已经表示数目，不能再加“们”，应删去“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
