INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87723, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将就是不太满意，但是先这样用着。", "primary_collocate": null, "pronunciation": "jiāng jiu", "ipa": "tɕjɑŋ˥ tɕjoʊ", "syllable_count": 2, "sentences": [{"text": "这个椅子不太舒服，先将就坐一下吧。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间有点小，但我今晚将就住一晚。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有新杯子，你将就用这个吧。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机慢了点，我先将就着用。", "target_word": "将就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭不太好吃，不过饿了就将就吃吧。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有新衣服，只好将就穿旧的。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件外套有点大，天冷，我将就穿着。", "target_word": "将就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床太硬了，可是我只能将就睡。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天再买新的，今天先将就一下。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "笔不好写，他还是将就用了一天。", "target_word": "将就", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "将就着", "label": "体标"}, {"form": "将就了", "label": "体标"}, {"form": "将就将就", "label": "重叠"}], "register": "口语", "sense_fingerprint": "不太满意但先凑合着用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50dfcc0b-fc77-441f-aa12-4c4358322b62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87723, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将就", "is_correct": true, "explanation": "正确：“将就”表示先凑合着用，与“不太舒服，先……坐一下吧”相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“先……坐一下吧”的建议相反，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”要接被修理的物品，不能接“坐一下”这样的动作。"}, {"text": "挑剔", "is_correct": false, "explanation": "搭配：“挑剔”多用于对人或事的毛病，不能说“先挑剔坐一下”。"}], "explanations": {"将就": "正确：“将就”表示先凑合着用，与“不太舒服，先……坐一下吧”相符。", "拒绝": "语义：“拒绝”与“先……坐一下吧”的建议相反，句意不通。", "修理": "配价：“修理”要接被修理的物品，不能接“坐一下”这样的动作。", "挑剔": "搭配：“挑剔”多用于对人或事的毛病，不能说“先挑剔坐一下”。"}, "sentence_index": 0, "correct_answer": "将就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我将就着疼痛继续工作。", "explanation": "这里应该用〈忍〉。将就指凑合着用某物或某种条件，不用于忍受疼痛。"}, {"text": "他将就着老板的批评。", "explanation": "这里应该用〈忍耐〉。将就指凑合着用不太满意的东西，不用于承受他人的批评。"}, {"text": "我们将就了一笔钱，给他买了礼物。", "explanation": "这里应该用〈凑〉。将就表示勉强接受、凑合着用，不用于凑集钱财。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将就", "is_correct": true, "explanation": "正确：“将就”表示凑合着穿，与“有点大，天冷”的语境相符。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示看不上，与“天冷”而仍要穿的语境不合。"}, {"text": "脱掉", "is_correct": false, "explanation": "语义：“脱掉”与“穿着”意思相反，句意不通。"}, {"text": "珍惜", "is_correct": false, "explanation": "搭配：“珍惜”接的是机会、物品、感情等，不接“穿着”这类动作。"}], "explanations": {"将就": "正确：“将就”表示凑合着穿，与“有点大，天冷”的语境相符。", "嫌弃": "语义：“嫌弃”表示看不上，与“天冷”而仍要穿的语境不合。", "脱掉": "语义：“脱掉”与“穿着”意思相反，句意不通。", "珍惜": "搭配：“珍惜”接的是机会、物品、感情等，不接“穿着”这类动作。"}, "sentence_index": 6, "correct_answer": "将就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次演出太精彩了，观众都将就地鼓掌。", "explanation": "这里应该用〈热烈〉。将就表示勉强、凑合，不能用于形容热烈的鼓掌。"}, {"text": "我们将就了一顿丰盛的晚饭，招待客人。", "explanation": "这里应该用〈准备〉。将就表示勉强接受，不用于为客人准备丰盛的饭菜。"}, {"text": "他将就着这次机会，一下子冲了上去。", "explanation": "这里应该用〈把握〉。将就表示勉强凑合，与积极抓住机会的态度相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台旧电脑有点慢，我先将就了用一阵子。", "corrected_sentence": "这台旧电脑有点慢，我先将就着用一阵子。", "error_description": "错误：体标。表示“将就”的持续状态应用“着”，说“将就着用”，不能用“了”，“将就了用”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件外套有点大，我们先把将就穿，明天再换。", "corrected_sentence": "这件外套有点大，我们先将就穿，明天再换。", "error_description": "错误：多余的“把”。此处“将就”直接作谓语，不应插入“把”，应说“先将就穿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
