INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87755, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人数是有多少个人。", "primary_collocate": null, "pronunciation": "rén shù", "ipa": "ɻən˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "今天来开会的人数不多。", "target_word": "人数", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请先数一数我们班的人数。", "target_word": "人数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人数太多，教室坐不下。", "target_word": "人数", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师问了一下全班的人数。", "target_word": "人数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加比赛的人数比去年多。", "target_word": "人数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间的人数最多是十个。", "target_word": "人数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人数不够，我们明天再踢球。", "target_word": "人数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道今天去爬山的人数吗？", "target_word": "人数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我们这次旅行的人数。", "target_word": "人数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭店要先知道吃饭的人数。", "target_word": "人数", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一共有多少个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50dfcc0b-fc77-441f-aa12-4c4358322b62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87755, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人数", "is_correct": true, "explanation": "正确：听到的是“人数”（rén shù），指有多少个人。"}, {"text": "认输", "is_correct": false, "explanation": "“认输”（rènshū）两个音节的声调都与“人数”（rén shù）不同，意思是承认失败。"}, {"text": "人士", "is_correct": false, "explanation": "“人士”（rénshì）的韵母是 i，与“人数”的 u 不同，意思是某类有身份的人。"}, {"text": "人寿", "is_correct": false, "explanation": "“人寿”（rénshòu）的韵母是 ou，与“人数”的 u 不同，意思是人的寿命。"}], "explanations": {"人数": "正确：听到的是“人数”（rén shù），指有多少个人。", "认输": "“认输”（rènshū）两个音节的声调都与“人数”（rén shù）不同，意思是承认失败。", "人士": "“人士”（rénshì）的韵母是 i，与“人数”的 u 不同，意思是某类有身份的人。", "人寿": "“人寿”（rénshòu）的韵母是 ou，与“人数”的 u 不同，意思是人的寿命。"}, "sentence_index": null, "correct_answer": "人数"}, "level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "语义：“人口”指一个地区的全部居民，不能用来指今天来开会的人。"}, {"text": "人气", "is_correct": false, "explanation": "语义：“人气”指受欢迎的程度，不指来开会的人数。"}, {"text": "人数", "is_correct": true, "explanation": "正确：“人数”指人的数目，“今天来开会的人数不多”通顺自然。"}, {"text": "人生", "is_correct": false, "explanation": "语义：“人生”指一个人的生存经历，与“来开会”不相容。"}], "explanations": {"人口": "语义：“人口”指一个地区的全部居民，不能用来指今天来开会的人。", "人气": "语义：“人气”指受欢迎的程度，不指来开会的人数。", "人数": "正确：“人数”指人的数目，“今天来开会的人数不多”通顺自然。", "人生": "语义：“人生”指一个人的生存经历，与“来开会”不相容。"}, "sentence_index": 0, "correct_answer": "人数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的产品人数每年都在增加。", "explanation": "这里应该用〈数量〉。“人数”只指人的数目，产品的多少要用“数量”。"}, {"text": "这家公司的人数都很年轻。", "explanation": "这里应该用〈人员〉。“人数”只说有多少人，不能用来描述年龄；说员工年轻要用“人员”。"}, {"text": "这家饭店急需招一个人数。", "explanation": "这里应该用〈员工〉。“招”的是员工，“人数”是数目，不能说“招一个人数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人才", "is_correct": false, "explanation": "语义：“人才”指有本领的人，踢球缺的是参加的人手，不是人才。"}, {"text": "人数", "is_correct": true, "explanation": "正确：“人数不够”指参加的人不足，与“我们明天再踢球”的语境吻合。"}, {"text": "人群", "is_correct": false, "explanation": "搭配：“人群”指聚在一起的一大群人，不能说“人群不够”。"}, {"text": "人间", "is_correct": false, "explanation": "语义：“人间”指人类世界，与“不够”和踢球的安排无关。"}], "explanations": {"人才": "语义：“人才”指有本领的人，踢球缺的是参加的人手，不是人才。", "人数": "正确：“人数不够”指参加的人不足，与“我们明天再踢球”的语境吻合。", "人群": "搭配：“人群”指聚在一起的一大群人，不能说“人群不够”。", "人间": "语义：“人间”指人类世界，与“不够”和踢球的安排无关。"}, "sentence_index": 6, "correct_answer": "人数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校培养了很多人数。", "explanation": "这里应该用〈人才〉。“培养”的对象是人才，“人数”只是数目，不能被培养。"}, {"text": "广场上挤满了人数。", "explanation": "这里应该用〈人群〉。“挤满”的是人群，“人数”不能被挤满。"}, {"text": "公司要节约人数成本。", "explanation": "这里应该用〈人力〉。“节约”的是人力成本，“人数”不是可以节约的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的一个人数是三十。", "corrected_sentence": "我们班的人数是三十。", "error_description": "错误形式是“一个人数”，正确形式是“人数”。“人数”表示人的数目，是抽象名词，前面不能加“一个”之类的量词，应直接说“我们班的人数是三十”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动的人数多很。", "corrected_sentence": "这次活动的人数很多。", "error_description": "错误形式是“多很”，正确形式是“很多”。“很”是程度副词，只能放在“多”前面修饰它，不能放在后面；说人数多，应说“人数很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d05e43-3e44-4b42-b320-c22a1538dea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
