INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "负责掌握、处理或带领（会议、活动等）。", "primary_collocate": null, "pronunciation": "zhǔ chí", "ipa": "ʈʂu˨˩˦ ʈʂʰɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "明天的会议由王经理主持。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来主持今天的会？", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我主持这次班会。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主持过很多次大会。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在主持会议。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会议我来主持，你们准备吧。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长主持了开学典礼。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她主持会议很认真。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个星期一的会，都由他主持。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能不能帮我主持一下今天的会议？", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主持了", "label": "体标"}, {"form": "主持过", "label": "体标"}, {"form": "主持人", "label": "复合"}], "register": "中性", "sense_fingerprint": "负责掌握并带领会议或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7b4bed-94d6-4b97-9460-5a5161d44bdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主持", "is_correct": true, "explanation": "主持：负责带领会议，与“由王经理”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说“吃会议”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”接房间、场地，不接“会议”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能带“会议”作宾语。"}], "explanations": {"主持": "主持：负责带领会议，与“由王经理”搭配，符合句意。", "吃": "语义：“吃”的对象是食物，不能说“吃会议”。", "打扫": "搭配：“打扫”接房间、场地，不接“会议”。", "睡": "配价：“睡”是不及物动词，后面不能带“会议”作宾语。"}, "sentence_index": 0, "correct_answer": "主持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在主持电梯，很辛苦。", "explanation": "这里应该用〈修理〉。主持指负责带领会议或活动，不能用来说电梯。"}, {"text": "她每天主持窗户，很辛苦。", "explanation": "这里应该用〈擦〉。主持指负责带领会议或活动，不能用来说擦窗户这类具体动作。"}, {"text": "他正在主持卧室的墙。", "explanation": "这里应该用〈粉刷〉。主持指负责带领会议或活动，不能用来说墙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主持", "is_correct": true, "explanation": "主持：带领、掌握典礼的进行，符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”接桌子、玻璃等，不接“典礼”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，不能说“喝典礼”。"}, {"text": "逛", "is_correct": false, "explanation": "配价：“逛”是不及物动词，不能带“典礼”作宾语。"}], "explanations": {"主持": "主持：带领、掌握典礼的进行，符合句意。", "擦": "搭配：“擦”接桌子、玻璃等，不接“典礼”。", "喝": "语义：“喝”的对象是饮料，不能说“喝典礼”。", "逛": "配价：“逛”是不及物动词，不能带“典礼”作宾语。"}, "sentence_index": 6, "correct_answer": "主持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他主持过学校的秘书。", "explanation": "这里应该用〈担任〉。“主持”指带领会议，不能用来说明职务，应说“担任秘书”。"}, {"text": "他在比赛中主持了一个球。", "explanation": "这里应该用〈踢进〉。主持指负责带领会议或活动，不能用来说球员的动作。"}, {"text": "他主持过班长，管得很好。", "explanation": "这里应该用〈当〉。“主持”不能接职务名词“班长”，应说“当班长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她主持地很认真，大家都很满意。", "corrected_sentence": "她主持得很认真，大家都很满意。", "error_description": "结构助词错误：动词后带程度补语要用“得”，不能用“地”，应说“主持得很认真”；“地”用于动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他主持着两次班会。", "corrected_sentence": "他主持过两次班会。", "error_description": "体标错误：表示经历过几次，要用“过”，不能用“着”。“着”表示动作或状态的持续，不能与“两次”搭配，应说“主持过两次班会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成功", "is_correct": true, "explanation": "反义：“成功”与“失败”指想做的事是否做成，意思相反。"}, {"text": "散步", "is_correct": false, "explanation": "无关：散步是日常动作，与“失败”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：游泳是运动，与“失败”没有反义关系。"}, {"text": "种植", "is_correct": false, "explanation": "无关：种植是劳动动作，与“失败”没有反义关系。"}], "correct_answer": "成功", "explanations": {"成功": "反义：“成功”与“失败”指想做的事是否做成，意思相反。", "散步": "无关：散步是日常动作，与“失败”没有反义关系。", "游泳": "无关：游泳是运动，与“失败”没有反义关系。", "种植": "无关：种植是劳动动作，与“失败”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成功", "is_correct": true, "explanation": "反义：“成功”与“失败”指想做的事是否做成，意思相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：唱歌是文娱活动，与“失败”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：睡觉是生理活动，与“失败”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：跳舞是文娱活动，与“失败”没有反义关系。"}], "correct_answer": "成功", "explanations": {"成功": "反义：“成功”与“失败”指想做的事是否做成，意思相反。", "唱歌": "无关：唱歌是文娱活动，与“失败”没有反义关系。", "睡觉": "无关：睡觉是生理活动，与“失败”没有反义关系。", "跳舞": "无关：跳舞是文娱活动，与“失败”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "失败是想做成一件事，可是没有成功。", "primary_collocate": null, "pronunciation": "shī bài", "ipa": "ʂʅ˥ pai˥˩", "syllable_count": 2, "sentences": [{"text": "这个实验做了三次，都失败了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次做生意就失败了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不怕失败，还想再试一次。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划为什么会失败呢？", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她失败了很多次，最后还是成功了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为准备得太少，所以这次试验失败了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的第一个计划失败了，但是他没有放弃。", "target_word": "失败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败并不可怕，可怕的是不再试。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，失败一次没关系，要再努力。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的第一次试飞失败了，大家都很难过。", "target_word": "失败", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失败了", "label": "完成体"}, {"form": "失败过", "label": "经历体"}, {"form": "失败者", "label": "复合词"}, {"form": "失敗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想做的事、计划、实验没有成功", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1b6033-d2c6-4adf-8a03-9e18bc04078f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失败", "is_correct": true, "explanation": "语义正确：“都失败了”指三次尝试都没有成功。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：实验不能“睡觉”，“都睡觉了”与句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：实验不会“散步”，句子不成立。"}, {"text": "发明", "is_correct": false, "explanation": "配价：“发明”要求带所发明的对象，“都发明了”缺少宾语。"}], "explanations": {"失败": "语义正确：“都失败了”指三次尝试都没有成功。", "睡觉": "语义：实验不能“睡觉”，“都睡觉了”与句意不通。", "散步": "语义：实验不会“散步”，句子不成立。", "发明": "配价：“发明”要求带所发明的对象，“都发明了”缺少宾语。"}, "sentence_index": 0, "correct_answer": "失败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的钱包在地铁上失败了。", "explanation": "这里应该用〈丢失〉。“失败”指想做的事没有成功，东西遗失要说“丢失”。"}, {"text": "这辆车在山路上突然失败了。", "explanation": "这里应该用〈失控〉。车辆、局面不受控制要说“失控”；“失败”指想做成的事没有成功，不用于描述车辆。"}, {"text": "那只小狗昨天就失败了。", "explanation": "这里应该用〈失踪〉。动物或人下落不明要说“失踪”；“失败”不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失败", "is_correct": true, "explanation": "语义正确：“计划失败了”与“但是他没有放弃”形成转折，句意通顺。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：计划不能“游泳”，句子不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：计划不会“生病”，“计划生病了”不合常理。"}, {"text": "丢失", "is_correct": false, "explanation": "配价：“丢失”要求带失去的对象，“计划丢失了”的说法不成立。"}], "explanations": {"失败": "语义正确：“计划失败了”与“但是他没有放弃”形成转折，句意通顺。", "游泳": "语义：计划不能“游泳”，句子不通。", "生病": "语义：计划不会“生病”，“计划生病了”不合常理。", "丢失": "配价：“丢失”要求带失去的对象，“计划丢失了”的说法不成立。"}, "sentence_index": 6, "correct_answer": "失败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的双眼突然失败了。", "explanation": "这里应该用〈失明〉。眼睛看不见要说“失明”；“失败”不用于人的眼睛。"}, {"text": "这棵树在大风里突然失败了。", "explanation": "这里应该用〈倒〉。树木被风吹倒要说“倒”；“失败”指想做的事没有成功，不用于树木。"}, {"text": "这把伞在风里失败了。", "explanation": "这里应该用〈坏〉。物品损坏要说“坏了”，“失败”不用于描述物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次试验我们失败着，大家都很沮丧。", "corrected_sentence": "这次试验我们失败了，大家都很沮丧。", "error_description": "体标错误：“失败”表示已经完成的结果，应用“了”；“着”表示持续的状态，与此不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他失败了过很多次，但是从来不放弃。", "corrected_sentence": "他失败过很多次，但是从来不放弃。", "error_description": "体标错误：“失败过”表示经历过，“了”与“过”不能同用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87788, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "获胜", "is_correct": true, "explanation": "反义：“获胜”与“失败”在比赛、对抗中意思相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：唱歌与比赛中的“失败”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：跳舞与比赛中的“失败”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：睡觉与比赛中的“失败”没有反义关系。"}], "correct_answer": "获胜", "explanations": {"获胜": "反义：“获胜”与“失败”在比赛、对抗中意思相反。", "唱歌": "无关：唱歌与比赛中的“失败”没有反义关系。", "跳舞": "无关：跳舞与比赛中的“失败”没有反义关系。", "睡觉": "无关：睡觉与比赛中的“失败”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
