INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "教授是在大学里教书、懂得很多的人。", "primary_collocate": null, "pronunciation": "jiào shòu", "ipa": "tɕjɑʊ˥˩ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这位教授在大学里教了二十年书。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里的教授懂得很多，学生都喜欢问他问题。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爸爸是大学教授，他每天都在看书。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教授说，做研究要有耐心。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都去听这位教授的课，觉得他懂得很多。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位教授的课很难，可是我学到了很多。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们把问题写在纸上，交给了教授。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授常去国外大学讲课。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教授的办公室里放着很多书，学生常来问问题。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在图书馆遇到了教我们历史的教授。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位教授", "label": "量词"}, {"form": "副教授", "label": "复合"}, {"form": "客座教授", "label": "复合"}], "register": "中性", "sense_fingerprint": "教授：在大学里教书、懂得很多的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84eaa279-90ef-4dbd-b39e-63b4c5dbbc90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87795, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教授", "is_correct": true, "explanation": "教授 jiàoshòu：在大学里教书、懂得很多的人，正确答案。"}, {"text": "教室", "is_correct": false, "explanation": "教室 jiàoshì 与 教授 jiàoshòu 第二音节的韵母不同（i 与 ou），声调相同（都是第四声），意思是上课的房间。"}, {"text": "教师", "is_correct": false, "explanation": "教师 jiàoshī 与 教授 jiàoshòu 第二音节的韵母和声调不同，意思是教书的人。"}, {"text": "教书", "is_correct": false, "explanation": "教书 jiàoshū 与 教授 jiàoshòu 第二音节的韵母和声调不同，意思是从事教学工作。"}], "explanations": {"教授": "教授 jiàoshòu：在大学里教书、懂得很多的人，正确答案。", "教室": "教室 jiàoshì 与 教授 jiàoshòu 第二音节的韵母不同（i 与 ou），声调相同（都是第四声），意思是上课的房间。", "教师": "教师 jiàoshī 与 教授 jiàoshòu 第二音节的韵母和声调不同，意思是教书的人。", "教书": "教书 jiàoshū 与 教授 jiàoshòu 第二音节的韵母和声调不同，意思是从事教学工作。"}, "sentence_index": null, "correct_answer": "教授"}, "level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生是学书的人，不在大学里教书，与“在大学里教了二十年书”矛盾。"}, {"text": "教授", "is_correct": true, "explanation": "教授：在大学里教书的人，与“在大学里教了二十年书”相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民不在大学里教书，与“在大学里教了二十年书”矛盾。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“教书”要求主语是从事教学的人，厨师不能说“在大学里教书”。"}], "explanations": {"学生": "语义：学生是学书的人，不在大学里教书，与“在大学里教了二十年书”矛盾。", "教授": "教授：在大学里教书的人，与“在大学里教了二十年书”相符。", "农民": "语义：农民不在大学里教书，与“在大学里教了二十年书”矛盾。", "厨师": "搭配：“教书”要求主语是从事教学的人，厨师不能说“在大学里教书”。"}, "sentence_index": 0, "correct_answer": "教授"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小学的教授每天教我们写字。", "explanation": "这里应该用〈老师〉。教授专指大学里的教师职称，小学教师要说“老师”。"}, {"text": "我姐姐是一位教授，每天在饭店里炒菜。", "explanation": "这里应该用〈厨师〉。教授是高等学校的教师职称，饭店里炒菜的人不能称教授。"}, {"text": "我弟弟今年考上了教授。", "explanation": "这里应该用〈大学生〉。教授是高校的职称，需要多年教学和研究才能评上，学生考入大学不能说“考上教授”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87795, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "教授", "is_correct": true, "explanation": "教授 jiàoshòu：在大学里教书、懂得很多的人，正确答案。"}, {"text": "交手", "is_correct": false, "explanation": "交手 jiāoshǒu 与 教授 jiàoshòu 两个音节的声调都不同，意思是交战、动手。"}, {"text": "脚手", "is_correct": false, "explanation": "脚手 jiǎoshǒu 与 教授 jiàoshòu 两个音节的声调都不同，意思是脚和手，常见于“脚手架”。"}, {"text": "交售", "is_correct": false, "explanation": "交售 jiāoshòu 与 教授 jiàoshòu 第一音节声调不同（阴平与去声），意思是把东西交给国家。"}], "explanations": {"教授": "教授 jiàoshòu：在大学里教书、懂得很多的人，正确答案。", "交手": "交手 jiāoshǒu 与 教授 jiàoshòu 两个音节的声调都不同，意思是交战、动手。", "脚手": "脚手 jiǎoshǒu 与 教授 jiàoshòu 两个音节的声调都不同，意思是脚和手，常见于“脚手架”。", "交售": "交售 jiāoshòu 与 教授 jiàoshòu 第一音节声调不同（阴平与去声），意思是把东西交给国家。"}, "sentence_index": null, "correct_answer": "教授"}, "level_3": {"options": [{"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能读问题，也不能接收写在纸上的问题，与句子的语境矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“交给”的接受者要是人，不能说“交给了桌子”。"}, {"text": "教授", "is_correct": true, "explanation": "教授：学生把问题交给的对象，与“学生们把问题写在纸上，交给了”相符。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁不能接收纸上的问题，句子的语境与墙壁无关。"}], "explanations": {"小狗": "语义：小狗不能读问题，也不能接收写在纸上的问题，与句子的语境矛盾。", "桌子": "搭配：“交给”的接受者要是人，不能说“交给了桌子”。", "教授": "教授：学生把问题交给的对象，与“学生们把问题写在纸上，交给了”相符。", "墙壁": "语义：墙壁不能接收纸上的问题，句子的语境与墙壁无关。"}, "sentence_index": 6, "correct_answer": "教授"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们足球队的教授，每天带我们训练。", "explanation": "这里应该用〈教练〉。教授指大学里的教师职称，足球队的指导要说“教练”。"}, {"text": "这首歌的教授唱得很好听。", "explanation": "这里应该用〈歌手〉。教授指大学里的教师，唱歌的人不能称教授。"}, {"text": "这所幼儿园的教授每天帮孩子们换尿布。", "explanation": "这里应该用〈保育员〉。教授是大学教师的职称，照顾幼儿的人员不能称教授。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表姐的老师是一只大学教授，讲课很有意思。", "corrected_sentence": "表姐的老师是一位大学教授，讲课很有意思。", "error_description": "量词错误：“教授”指人，应用量词“位”，不能用“只”（“只”多用于动物）。正确说法：一位大学教授。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位大学地教授很受学生欢迎。", "corrected_sentence": "这位大学教授很受学生欢迎。", "error_description": "结构助词错误：“大学”修饰“教授”时应直接相连或加“的”，不能用“地”（“地”用于修饰动词）。正确说法：这位大学教授。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
